#   10:30~  중복 -> Pullback
# 단독 편입 종목은 시각과 무관하게 자기 전략만 탄다(완전 분리).
DUAL_SOURCE_PULLBACK_FROM = time(10, 30)
# [2026-08-01 제거] 조건검색식별 09:20 지연 게이트(OTHER_COND_START).
# 07-29에 돌파자동매매용을 09:20까지 지연시켰던 근거는 "그때의 1A(거래량
