# 버스트 포착이라 분봉도 워밍업도 필요 없고 09:00부터 그대로 판정 가능하다.
# 반대로 급등이 가장 많이 나오는 개장 20분을 통째로 버리는 손실이 컸고,
# 1B 폐지로 돌파자동매매용은 1A 외에 갈 곳도 없어졌다. 진입 품질은 새 1A의
# 대량체결 게이트가 이미 담당하므로 시간으로 또 막을 근거가 없어 제거한다.
# (상수는 남겨두지 않는다 — 참조가 사라진 시간 상수는 나중에 "왜 안 걸리지"
#  하고 다시 붙일 위험이 있어 흔적을 남기지 않는 편이 안전하다.)
# [2026-08-02 제거] 1L(주도주) 시간 윈도우 LEADING_START/LEADING_END —
# 1L 전략 삭제와 함께 제거. GROUP_A_START(09:00)가 그 역할을 대신한다.

# 진입 조건 (Phase 1A 설정값 사용)
SURGE_THRESHOLD = PHASE_1A["surge_threshold"]
MA_TOUCH_TOLERANCE = PHASE_1A["ma_tolerance"]
VOLUME_SURGE_RATIO = PHASE_1A["volume_surge_ratio"]
VOLUME_LOOKBACK = 5

# 1A 점수 커트라인 (10:30 이후 상향 + 지수경보(CAUTION) 시 추가 상향)
# (2026-07-31) 이 점수 기반 로직은 "주도주상위" 조건검색식이 아닌 경로
# (돌파자동매매용/기타)에만 계속 쓰인다 — 주도주상위 경로는 아래
# evaluate_1a_leading_strength로 대체됨(사용자 지정, 413630 실사례처럼
# HTS가 이미 거른 종목에 거래량증가지속+2분강도지속+점수를 또 씌우면
# 이중 필터링으로 지연만 유발한다는 판단).
PHASE1A_SCORE_NORMAL = 6.5
PHASE1A_SCORE_TIGHT = 8.5
PHASE1A_SCORE_CAUTION_BONUS = 1.0

# ── 1A 체결강도 단독 즉시진입 (2026-07-31 신규, 사용자 지정) ──────
# 처음엔 주도주상위 소스에만 적용했으나(HTS가 이미 강한 종목만 골라 넘겨주니
# 그 위에 거래량증가지속/테마 요구사항을 또 얹지 않는다는 취지), 같은 논리로
# 돌파자동매매용까지 확장 — 조건검색식 소스 구분 없이 1A 전체가 이제 체결강도
# 하나만 짧게 확인해서 즉시매수한다. 이 경로가 1L(테마리더+강도100 2분)과
# 사실상 겹쳤고(짧은 쪽이 항상 먼저 사감) 그래서 1L은 2026-07-31에 죽고
# 08-02에 삭제됐다. 거래량/MA/양봉 등 품질필터가 전부 빠지는 트레이드오프를
# 사용자가 인지하고 수용함(핵심 목표는 "고가 아닌 트리거 지점에서 매수").
# ⚠️ [미사용 / 2026-08-03 확인] 아래 PHASE1A_LEADING_* 3종은 **죽은 상수**다.
#   유일한 사용처가 evaluate_1a_leading_strength()인데 그 함수는 08-02 틱 구동
#   전환 때 호출부가 교체되어 **라이브 호출이 0건**이다(테스트만 호출).
#   실제 1A/Pullback 무장은 TICK_STRENGTH_MIN / TICK_STRENGTH_SUSTAIN_SEC가
#   담당하며, 그 게이트는 전략 라우팅보다 **앞**에 있어 두 전략에 공통 적용된다.
#   즉 여기 3초를 고쳐도 매매는 1도 안 바뀐다.
#   이름이 `PHASE1A_...`라서 "1A는 3초구나"로 오해하기 딱 좋아 배너를 단다 —
#   이 프로젝트는 이름 때문에 실거래 사고가 두 번 났다(08-01 _cleanup_watched가
#   1A 틱 버퍼를 지운 것 / 07-31 1L 조기청산).
PHASE1A_LEADING_STRENGTH_MIN = 100.0   # [미사용]
PHASE1A_LEADING_SUSTAIN_SEC = 3        # [미사용] 실제 값은 TICK_STRENGTH_SUSTAIN_SEC
# 3초 윈도우 체결강도 판정 최소 틱 수. 이 미만이면 compute_strength가 중립값
# (100.0)을 돌려주는데, 임계값도 100이라 "100 < 100 = False"로 **통과**해버린다.
# 즉 데이터가 없을수록 오히려 쉽게 뚫리는 구조였다 — 1A는 그 우연을 쓰지 않고
# 틱 수를 직접 확인해서 부족하면 명시적으로 탈락시킨다(아래 평가 함수 참고).
PHASE1A_STRENGTH_MIN_TICKS = 3
# 지수 방어 CAUTION 시 강도 임계값 배수(2026-07-31, 사용자 지정 "동적 강도
# 임계값"의 한 축) — 옛 1A 점수시스템의 PHASE1A_SCORE_CAUTION_BONUS와 같은
# 전제(시장 전체가 불안하면 컷라인을 높인다)를 강도 임계값에 적용한 것.
# 판단치 — 실전 관찰 필요.
PHASE1A_LEADING_CAUTION_MULTIPLIER = 1.2

# ── 1A 대량체결 버스트 필터 (2026-08-01 사용자 지정, 기존 60초 누적
# 거래대금 필터를 대체) ────────────────────────────────────────────
# 기존 PHASE1A_MIN_TRADE_VALUE(60초 누적 3천만원)는 잔챙이 체결이 길게 쌓여도
# 채워져서 "지금 큰 손이 때리고 있는가"를 구분하지 못했다. 3초로 창을 줄인
# 만큼, 그 3초 안에 실제로 큰 체결이 터지고 있는지를 두 갈래(OR)로 확인한다:
#   ① 단일 체결 PHASE1A_BURST_TRADE_VALUE 이상이 PHASE1A_BURST_TRADE_COUNT회 이상
#   ② 단일 체결 PHASE1A_SINGLE_TRADE_VALUE 이상이 1건이라도 (한 방에 들어온 대량)
# 둘 다 TradeFlowTracker의 같은 틱 버퍼를 재사용 — REST 호출/지연 추가 없음.
# 주의: 사용자 지시의 "3000천만"은 3천만원(30,000,000)으로 해석했다.
#
# (2026-08-04 상향 3천만 -> 4천만, 사용자 지정) 08-03~04 실거래 32건에서
# **버스트 규모와 성과가 단조 관계**로 나왔다(추정 거래대금 = 문턱 x 건수):
#     0.8억 미만 : 19건 승률 37% 평균 -0.64%
#     0.8~1.5억  :  8건 승률 62% 평균 +0.10%
#     1.5~3.0억  :  4건 승률 50% 평균 +0.89%
# 특히 **문턱에 딱 걸린 신호가 가장 나빴다** — 19건 중 다수가 정확히
# 0.60억(=3천만x2건)에 몰려 있었다. 간신히 넘긴 버스트는 신호가 아니라
# 노이즈에 가깝다는 뜻이다.
# 4천만으로 올리면 절대 경로 2건 요구가 곧 0.8억이 되어 위 개선 구간에 든다.
# 강건성 확인(과최적화 판별): 08-03(9건 -0.13% -> 7건 +0.54%)과
# 08-04(10건 -1.10% -> 6건 +0.40%) **양일 각각** 개선됐고, 1A(-1.21%->+0.44%)와
# 눌림(+0.14%->+0.51%) **양 전략** 모두 개선됐다. 손절 비중은 21.9% -> 7.7%.
# 대가: 하루 진입이 16.0건 -> 6.5건으로 준다(슬롯은 남아돌았으므로 그 자리를
# 다른 종목이 대신 채우지는 않는다 — 그냥 거래가 줄어든다).
# ⚠️ 표본이 2일 32건뿐이다. 되돌릴 때는 이 값만 30_000_000으로 되돌리면 된다.
PHASE1A_BURST_TRADE_VALUE = 40_000_000    # 대량체결 1건의 최소 금액 (4천만원)
# (2026-08-02 사용자 지정) 3건 -> 2건. "1틱 3천만원 2회 또는 1틱 1억 1회".
PHASE1A_BURST_TRADE_COUNT = 2
PHASE1A_SINGLE_TRADE_VALUE = 100_000_000  # 단일 체결만으로 통과시키는 금액 (1억원)

# ══════════════════════════════════════════════════════════════════════
# 틱 구동 진입 (2026-08-02 전면 개편, 사용자 지정)
# ══════════════════════════════════════════════════════════════════════
# [배경 — 왜 바꿨나]
# 이전까지 1A/Pullback 진입 평가가 실행되는 경로는 딱 둘뿐이었다:
#   ① on_condition_hit — 편입 순간 1회 (이때는 틱이 0개라 "체결틱 부족"으로
#      무조건 탈락한다. 즉 실질적으로 평가 기회가 아니었다)
#   ② task_watchlist_reentry — **15초 주기 폴링** (main.py)
# 그런데 진입 조건은 "체결강도 100 이상 수 초 유지"라는 짧은 신호다.
# 3초짜리 신호를 15초 간격으로 들여다보면 평균 7.5초/최대 15초가 늦고,
# 강도가 3~5초만 100을 넘었다 꺼지는 종목은 아예 관측조차 되지 않는다.
# 1B/1L을 비활성화할 때 그 둘이 갖고 있던 "실시간 틱 콜백 진입" 경로가
# 통째로 사라졌는데 새 1A가 그걸 물려받지 못한 것이 원인이었다.
# -> 평가를 on_trade(체결 틱 콜백) 안으로 옮긴다. 판정은 전부 메모리
#    연산이라 REST 0콜이고, 조건이 차는 그 틱에서 즉시 발화한다.
#
# [무장 -> 발사 순서가 핵심]
#   무장: 체결강도 100 이상 연속 유지(TICK_STRENGTH_SUSTAIN_SEC)  <- 느린 조건
#   발사: 대량체결 버스트 도착              <- 순간 이벤트(빠름)
# 순서를 반대로 하면(버스트 먼저 보고 강도 3초를 기다리면) 최대 3초를
# 손해 본다. 이 순서라면 버스트 틱이 도착한 **그 콜백 안에서** 이미 무장이
# 끝나 있으므로 추가 대기가 0이다.
TICK_ENTRY_ENABLED = True          # 즉시 끄는 스위치(False면 기존 폴링 경로만 사용)

# ── 무장: 체결강도 3초 '연속' 유지 ────────────────────────────────
# 강도 소스로 **키움 공식 체결강도(FID 228)**를 쓴다. 자체 compute_strength가
# 아닌 이유 두 가지:
#   ① compute_strength는 틱이 부족하면 정확히 100.0(중립값)을 반환하는데
#      임계값도 100이라 "100 < 100 = False"로 조용히 통과한다 — 데이터가
#      없을수록 쉽게 뚫리는 구조다(trade_flow.py STRENGTH_NEUTRAL 참고).
#   ② compute_strength는 짧은 윈도우의 '평균'이라 "3초 연속 유지"라는
#      사용자 정의와 의미가 다르다. 228은 당일 누적 기준이라 안정적이고,
#      무엇보다 **사용자가 HTS 화면에서 보는 바로 그 값**이다.
# 228은 이미 매 체결 틱에 실려 온다(api/kiwoom_ws.py의 parsed["strength"]) —
# 계산 0회, 추가 호출 0회, 지연 0ms.
TICK_STRENGTH_MIN = 100.0          # 이 값 이상이어야 무장 타이머가 돈다
# (2026-08-03) 3.0 -> 2.0 -> **1.5초**. **백테스트로 검증한 값이 아니다** — FID228 이력이
# 남지 않아 과거 재현이 원리적으로 불가능하다(틱 아카이브엔 시각·가격·거래량만
# 있다). 간접 근거는 08-03 매수 16건의 '매수 시점 강도 지속시간 vs 성과'가
# 짧을수록 좋았다는 것뿐인데(3~5초 1건 +1.76% / 5~20초 4건 +0.13% / 20초+
# 11건 +0.03%), 가장 짧은 구간이 1건이라 근거로는 약하다.
# 모의투자에서 노출을 넓혀보자는 사용자 판단으로 완화한다.
# 되돌릴 때는 이 값만 3.0으로 바꾸면 된다.
# ⚠️ 이 값을 더 낮출 때 주의: 무장은 '매수세가 실제로 유지되는가'의 유일한
# 증거다. 너무 짧으면 순간 스파이크에도 무장돼 버스트 하나만으로 매수가 나간다.
# ⚠️ 1.5초에서 더 내릴 때 주의 — 저유동 종목은 틱 간격 자체가 길다.
#   08-03 실측 틱 밀도: 037070 23.2틱/초 / 006360 10.0 / 000400 **0.4틱/초**.
#   000400 같은 종목은 틱이 2.5초에 하나라, 요구시간을 1.5초로 낮춰도 실제로는
#   "2틱"으로 무장이 성립한다(타이머는 강도>=100인 첫 틱에서 시작해 다음 틱까지의
#   경과를 재므로). 즉 저유동 종목에선 값을 낮춰도 체감 완화가 거의 없고,
#   대신 **증거 자체가 2틱뿐**이라는 위험만 남는다. 유동성 필터와 버스트 조건이
#   그 위험을 받치고 있다는 전제에서만 유효하다.
TICK_STRENGTH_SUSTAIN_SEC = 1.5    # 연속 유지 요구 시간(초). 밑으로 떨어지면 리셋
# 무장 후 이 시간(초) 안에 버스트가 안 오면 무장 해제. 강도가 계속 100 위라도
# 버스트 없이 오래 끌면 "이미 지나간 자리"일 가능성이 커서 무한 대기를 막는다.
TICK_ARM_TTL_SEC = 120.0

# ── 발사: 대량체결 버스트 3경로(OR) ──────────────────────────────
# 창을 5초로 잡은 이유(사용자 원안 "1초" -> 5초): 키움 체결 FID 20이
# HHMMSS **초 단위**라 같은 초에 들어온 두 체결은 타임스탬프가 동일하다.
# 게다가 WS는 여러 틱을 배치로 몰아 보내기도 해서 '1초 이내 2회'는 물리적으로
# 판정이 불가능하다. 5초는 신호의 의미(집중된 대량 유입)를 해치지 않으면서
# 판정이 가능한 최소 창이다.
TICK_BURST_WINDOW_SEC = 5.0

# [경로 ③] 자기 정규화 — 그 종목 평균 1틱 체결금액의 N배.
# 절대금액만 쓰면 종목별 난이도가 다르다: 조건검색식이 보장하는 건 일 거래대금
# 100억 이상뿐이고, 그 안에서도 평균 1틱 금액은 30만~300만원으로 10배 벌어진다.
# 이 경로는 **시간대 보정이 자동**이라는 게 진짜 장점이다 — 점심에 시장이
# 마르면 분모도 같이 줄어 '평균의 20배'라는 난이도가 시각과 무관하게 유지된다.
TICK_BURST_REL_MULT = 20.0         # 평균 1틱 체결금액의 몇 배면 대량으로 볼지
TICK_BURST_REL_FLOOR = 10_000_000  # 상대경로에도 두는 절대 하한(1천만원)
TICK_BURST_REL_WINDOW_SEC = 300.0  # 평균을 재는 구간(5분)
TICK_BURST_REL_COUNT = 2           # 상대경로 요구 건수

# ── 시간대 계수 (사용자 지정: "시간이 지날수록 장이 느슨해지니 반영") ──
# 장중 거래량은 U자 곡선이라 오전 3천만원과 점심 3천만원은 난이도가 완전히
# 다르다. 절대 임계값을 시각에 따라 낮춰 "같은 난이도"를 유지한다.
# (start_hhmm, 계수) — 오름차순, 해당 시각 이상이면 그 계수를 쓴다.
# 경로 ③은 자기 정규화라 이 계수를 적용하지 않는다(중복 완화 방지).
#
# ⚠️ (2026-08-03) 점심 계수 0.65 -> 1.00으로 되돌림. 08-03 실거래 16건을
# 계수별로 갈라보니 완화 폭이 클수록 성과가 나빴다:
#     계수 1.00(09:00~10:30) 7건  합계 +6.56%  평균 +0.94%
#     계수 0.85(10:30~11:30) 3건  합계 -0.60%  평균 -0.20%
#     계수 0.65(11:30~13:00) 3건  합계 -5.29%  평균 -1.76%  ← 3건 전부 손실
#     계수 0.80(13:00~14:00) 3건  합계 +1.91%  평균 +0.64%
# 그날 손실 청산 4건(손절 1 + 슬롯교체 3)이 전부 11:23~12:56에 몰렸고,
# 오전에 번 +6.56%를 점심 -5.29%가 거의 다 지웠다.
# 원래 의도("안 낮추면 오후가 통째로 죽는다")는 거래량을 유지하려는 것이었지만,
# 실제로는 **유동성이 가장 마른 시간에 가장 낮은 문턱으로 들어가는** 구조였다.
# 점심에 신호가 안 나오는 건 시장에 큰 손이 없다는 뜻이지 문턱을 깎을 이유가
# 아니다 — 억지로 만든 진입이 3전 3패였다.
# 남은 0.85/0.80/0.95는 그날 표본으로는 판단이 갈려(0.85 손실 / 0.80 이익)
# 그대로 뒀었다.
#
# ⚠️⚠️ (2026-08-04) **오후 완화를 전부 제거했다.** 08-03+08-04 실거래 36건을
# 시간대로 갈라보니 오후는 완화할 구간이 아니라 오히려 강화할 구간이었다:
#     09:00~10:30  21건 승률 48% 평균 -0.11%  최선 +6.32%  +2%이상 4건  정체청산  0%
#     10:30~11:30   6건 승률 50% 평균 -0.05%  최선 +2.76%  +2%이상 1건  정체청산 33%
#     11:30~13:00   3건 승률  0% 평균 -1.76%  최선 -1.17%  +2%이상 0건  정체청산100%
#     13:00~14:50   6건 승률 83% 평균 +0.13%  최선 +0.70%  +2%이상 0건  정체청산 67%
#
# 핵심은 "오후엔 큰 수익이 구조적으로 없다"는 것이다 — 11:30 이후 9건 중
# +2% 이상이 **0건**이고 최선이 +0.70%다. 그런데 손실은 -1.4~2.4%가 나온다
# (순손익 기준 승자 3건 합 +1.22% vs 패자 합 -7.78%). 작게 이기고 크게 지는
# 전형적인 음수 기대값 구조다.
#
# 더 결정적인 근거: **무장 시간이 오후가 2배 길다**(71.7초 vs 32.8초).
# 신호가 약해서 못 사는 게 아니라, 강도 100이 오래 유지되는데도 가격이 안
# 움직인다. 같은 지표가 시간대에 따라 다른 것을 가리키는 것이다 —
# 오전의 버스트는 '신규 매수세 유입'이지만 오후의 버스트는 '잔여 유동성
# 소화'에 가깝다. 오후 청산의 77%가 정체성 청산(슬롯교체/정체정리/본전스톱/
# 강제청산)인 것이 그 증거다(오전은 0%).
#
# 그런데 코드는 정확히 반대로 **오후에 문턱을 20% 낮추고** 있었다. 실제로
# 오후 9건 중 6건이 계수 0.80~0.65로 진입했다. 08-03에 점심 0.65를 없앤 것과
# 같은 결함이 13:00~ 구간에 그대로 남아 있었던 셈이다.
# -> 전 시간대 1.00. 이제 어떤 시각에도 문턱이 원기준보다 헐거워지지 않는다.
# 되돌리려면 이 표만 옛 값으로 바꾸면 된다(0.85/0.80/0.95).
TICK_BURST_TIME_MULT = [
    ((9, 0),   1.00),   # 개장~10:30 : 거래 폭발 구간, 원래 기준 그대로
    ((10, 30), 1.00),   # (구 0.85) 완화 제거
    ((11, 30), 1.00),   # 점심 — 완화 금지 (08-03 실측: 완화 구간이 전부 손실)
    ((13, 0),  1.00),   # (구 0.80) 완화 제거 — 오후 9건 중 6건이 이 계수로 진입
    ((14, 0),  1.00),   # (구 0.95) 완화 제거
]

# ── 폭주 방지 ────────────────────────────────────────────────────
# 무장이 끝난 종목은 틱마다 버스트를 재확인하는데, 초당 수십 틱이 들어오는
# 종목에서 매 틱 전체 게이트(등락률 상한/슬롯/재매수차단...)를 다 도는 건
# 낭비다. 무장 이후에만 걸리는 짧은 쿨다운이라 최악 지연이 이 값으로 묶인다
# (기존 15초 폴링 대비 60배 개선). 0으로 두면 쿨다운 없음.
TICK_ENTRY_COOLDOWN_SEC = 0.25

# ── 1A 하이브리드 주문(지정가/시장가 자동 선택) (2026-08-01 사용자 지정) ──
# 매수 직전 매도 1~3호가에 쌓인 총 잔량 '금액'을 보고 주문 방식을 고른다:
#   잔량금액 >= PHASE1A_ASK_DEPTH_MIN  -> 호가창이 채워져 있음 -> 시장가
#       (받아줄 물량이 충분하니 즉시 체결이 유리, 슬리피지도 제한적)
#   잔량금액 <  PHASE1A_ASK_DEPTH_MIN  -> 텅 빈 호가창 -> 지정가
#       (시장가로 때리면 위쪽 호가를 훑어 올라가 크게 불리하게 체결됨)
#   호가 스냅샷 자체가 없음(판단 불가)  -> 지정가 (보수적 기본값)
PHASE1A_ASK_DEPTH_LEVELS = 3
# 2026-08-05 실전 1일차 실측으로 5천만 -> 1천만 인하.
# 이 문턱의 목적은 "우리 주문이 호가를 훑고 올라가지 않을 만큼 두꺼운가"인데,
# **주문 크기가 바뀌었는데 문턱만 그대로**여서 4배 과보수적이 돼 있었다:
#     모의(200만원 시절) 주문 200만 / 문턱 5,000만 = 4.0%
#     실전(50만원 + 되돌림 분할) 트랜치 22.5만 / 문턱 5,000만 = 0.45%
#     -> 1,000만으로 낮춰도 2.2%로 모의 시절보다 여전히 보수적이다.
# 실측 대가: 08-05 호가잔량 중앙값이 1,235만원인데 문턱이 5,000만이라
# 매수주문 29건 중 24건(83%)이 지정가로 나갔고, 그중 3건이 미체결로 정리됐다.
# 그 3건의 기회손실 — 대원전선 +11.33% / 마키나락스 +15.06% / GS건설 +5.71%.
# 지정가는 이미 '매도3호가'에 걸므로 슬리피지 2~3틱은 어차피 감수 중이고,
# 시장가 전환의 추가 비용(0.1~0.5%p)보다 미체결 손실(5~15%)이 압도적으로 크다.
PHASE1A_ASK_DEPTH_MIN = 10_000_000  # 1천만원

# 주도주상위 시가대비 급등 매수보류 (2026-07-31, 사용자 지정) — 개장 직후
# 시가 대비 이미 5% 이상 오른 종목은 가파른 상승 뒤 눌림(되돌림) 가능성이
# 크다고 보고 보수적으로 매수를 보류한다. 주도주상위 소스에만 적용(사용자가
# 그렇게 범위 지정) — 전일종가 기준 MAX_ENTRY_CHANGE_PCT(16%)와는 별개로,
# 이건 "당일 시가 대비"라 갭상승 여부와 무관하게 장중 상승폭만 본다.
PHASE1A_LEADING_OPEN_SURGE_CAP = 5.0

# ── 1A 개장초반 슬롯 우선순위 교체 (2026-07-31, 사용자 지정) ──────
# "장 시작하자마자 여러 종목이 동시에 조건을 만족하면 먼저 틱이 온 놈이
# 아니라 가장 강한 놈이 슬롯을 차지해야 한다"는 요구 구현. 슬롯(3개)에
# 여유가 있는 동안은 그냥 즉시매수(지연 없음) — 슬롯이 이미 꽉 찼을 때만
# 새 후보와 "가장 약한 보유종목"을 비교해서 확실히 더 강하면(마진 이상)
# 즉시 교체한다. 시간창을 개장초반(GROUP_A_START~EARLY_WINDOW_END, 09:00~
# 09:10)으로 제한한 이유: 그 이후엔 기존 slot_replacement.py(정체 10분+
# 강도/거래량 하락)가 계속 관리하므로 중복 불필요, 또 장중 내내 이 로직이
# 켜져 있으면 잘 벌고 있는 자리를 순간 강도 스파이크 하나로 뺏길 위험이 큼.
# 마진(1.2배)과 최소보유시간(30초) 가드는 슬롯을 사자마자 되파는 무의미한
# 왕복수수료 낭비를 막기 위함 — slot_replacement.py의 CANDIDATE_SCORE_MARGIN
# 관례를 그대로 재사용.
# [2026-08-01 전면 재설계 — "조건검색식 우선순위가 아니라 종목 우선순위"]
# 설계 원칙: **비교는 미리 해두고, 트리거는 즉시 실행한다.**
#   ① 슬롯에 여유가 있으면 순위를 아예 보지 않고 즉시 매수 (딜레이 0).
#      실측상 슬롯 사용률이 10%라 대부분의 시간은 이 경로다 —
#      급등 포착 속도는 예전과 완전히 동일하다.
#   ② 슬롯이 꽉 찬 순간에만 순위를 본다. 이때도 후보를 모아 기다리지 않고,
#      이미 틱 버퍼에서 계산돼 있는 값(_candidate_tier, REST 0콜/대기 0초)을
#      조회만 하므로 여전히 즉시 실행된다.
#   ③ 순위 지표는 **자기 자신 대비 비율**(거래대금 가속도 x 체결강도)이라
#      조건검색식(주도주상위=소형 급등 / 돌파자동매매용=대형주)이 달라도
#      공평하게 비교된다 — 조건식별 우선순위 자체가 필요 없어진다.
#   ④ 순위를 모르는 종목(틱 데이터 부족)은 남의 슬롯을 빼앗지만 못할 뿐,
#      빈 슬롯 매수는 그대로 한다. '모름'이 매수를 막지 않게 하는 게 중요.
PHASE1A_PRIORITY_MARGIN = 1.3       # 후보 tier >= 최약 보유종목 tier * 이 배수여야 교체
PHASE1A_PRIORITY_MIN_HOLD_SEC = 30  # 이 시간 안 된 포지션은 교체 대상에서 제외
# 교체 대상은 "아직 결과가 안 난 자리"로 제한한다 — 이미 오르고 있는 포지션을
# 순간 tier 스파이크로 빼앗으면 잘 벌고 있는 자리를 스스로 걷어차게 된다.
PHASE1A_PRIORITY_FLAT_BAND = 0.005  # 순손익 ±0.5% 이내인 포지션만 교체 대상
# tier 계산에 필요한 최소 틱 수. 미달이면 tier=0(판단 불가) -> 교체 자격 없음.
PHASE1A_TIER_MIN_TICKS = 10
PHASE1A_TIER_SHORT_SEC = 30
PHASE1A_TIER_LONG_SEC = 120

# [제안 A] 신호 세기 계층화 (2026-08-01) — 진입 트리거는 "3천만x3건 OR 단일
# 1억"을 동등하게 취급하지만, 단일 1억은 훨씬 압도적인 신호다. 슬롯이 꽉 찼을
# 때 어느 후보가 자리를 가져갈지 겨루는 tier에서는 이 차이를 반영한다.
# 배수는 상한이 고정된 이산값 — tier가 폭주하지 않도록 곱셈 항을 유한하게 묶는다.
PHASE1A_TIER_SINGLE_MULT = 1.5   # 최근 30초에 단일 1억+ 체결이 있었다
PHASE1A_TIER_BURST_MULT = 1.2    # 최근 30초에 단일 3천만+ 체결이 있었다

# [제안 C] tier 기반 매수금액 가중 (2026-08-01) — 같은 슬롯 하나를 쓰더라도
# 신호가 강한 자리에 더 태운다. **위쪽으로만** 움직인다(기존 대비 줄어드는
# 종목은 없음) — 축소 방향까지 열면 평범한 후보의 체결 수량이 0이 되는 등
# 부작용이 생기고, 지금은 자본의 2.4%만 쓰는 단계라 줄일 이유도 없다.
PHASE1A_SIZE_TIER_FULL = 1.5     # tier가 이 값 이상이면 최대 배수 적용
PHASE1A_SIZE_MAX_MULT = 1.5      # 최대 1.5배 (200만 -> 300만)

# [제안 B] 조건검색식별 성과 자동 보정 (2026-08-01) — strategy_performance의
# 축소추정 로직을 전략 축뿐 아니라 **조건검색식 축**으로도 돌린다.
# "오늘 주도주상위는 잘 되는데 돌파자동매매용은 안 된다"가 자동 반영된다.
# 우선순위(줄 세우기)가 아니라 '문턱 조정'이므로 진입 지연이 전혀 없다.
