# Pullback 반등 확인용 OBV(누적거래량) 확인 구간 — 몇 봉 전과 비교할지.
# (2026-07-29 신규: 거래량 없는 가짜 반등을 VWAP과 함께 걸러내는 용도)
# ⚠️ [미사용, 2026-08-02] Pullback이 틱 구동으로 바뀌면서 분봉·OBV·VWAP 경로가
