# 매수 진입 등락률 상한. 이미 많이 오른 종목을 추격매수하는 걸 막기 위한 필터
# — 1A/Pullback/1B/1L 전체 전략에 동일 적용. (2026-07-28)
# 기준을 "당일 시가 대비"에서 "전일종가 대비"로 변경(2026-07-31, 실거래로 발견) —
# 시가 기준은 갭상승 출발일에 실제 상승폭을 과소평가한다. 예: 093370(후성)은
# 시가대비로는 +4.60%(통과)였지만 전일종가 대비로는 +18.18%(실제로는 상한
# 초과)였다. HTS 조건검색식(F 지표)도 전일종가 기준이라 이제 완전히 일치.
# (2026-08-01 사용자 지정) 전략별 분리. 1A는 12% -> 16%로 완화하고, 눌림목은
# 10%로 더 조인다. 근거: 1A는 "지금 매수세가 터지는 자리"를 잡는 추세추종이라
# 이미 오른 종목이 더 가는 경우를 12%에서 잘라내고 있었고, 반대로 Pullback은
# "고가에서 되돌린 자리"를 사는 전략이라 애초에 전일종가 대비 많이 오른 종목은
# 되돌림 폭도 그만큼 커서 위험하다. 같은 상한을 두 전략에 쓰면 한쪽은 기회를
# 잃고 다른 쪽은 과도한 위험을 진다.
# 2026-08-05: 1A 16.0 -> 13.0 (사용자 지정). 실전 1일차 실측에서 진입시점
# 등락률이 낮을수록 이후 성과가 좋았다 — 구간별 (이후최고/이후최저/변동폭):
#     ~10%   (n=13)  +7.41% / -2.52% / 9.92%   <- 전 지표 1위
#     10~14% (n=1)   +3.64% / -5.82% / 9.46%
#     14~20% (n=2)   +5.05% / -3.23% / 8.28%
# "이미 많이 오른 종목이 회전율·변동성이 커서 먹을 게 많다"는 통념과 반대다.
# 이미 +19% 오른 종목은 '눈에 띄게 움직인 것'이지 '앞으로 움직일 것'이 아니다.
# ⚠️ 08-05 기준으로는 이 변경의 비용이 0이다 — 그날 상한에 걸린 종목이
#    전부 눌림목(10%) 경로였고 1A(16%)에 걸린 건 하나도 없었다.
MAX_ENTRY_CHANGE_PCT = 13.0           # 1A 및 기본
MAX_ENTRY_CHANGE_PCT_PULLBACK = 10.0  # 눌림목자동 조건검색 -> Pullback 전용

# 신규매수 전면 하드 컷오프. 1A(~14:50)/1L(~10:50)은 자체 시간 윈도우가 있지만
# 1B(FSM 감시)는 Pullback 미체결 후보를 계속 지켜보다 READY_TO_BUY가 되면 바로
# 매수해서 자체 종료 시각이 없음 — 장마감(15:30) 직전까지 실시간 틱이 들어오는
# 한 계속 매수를 시도하던 문제(2026-07-29 실전 확인, 수동 종료 전까지 지속).
# _execute_buy 단일 지점에서 전략 무관하게 막아서 1B처럼 자체 윈도우가 없는
# 전략이 추가돼도 항상 걸리게 함.
ENTRY_HARD_CUTOFF = time(15, 10)

# 지수 급락(폭락장) 대응 — MARKET_DEFENSE_ENABLED와 무관하게 항상 감시(2026-07-28).
# 코스피/코스닥 중 더 나쁜 쪽이 이 이하로 떨어지면: 트레일링 없이 전 전략
# flat SEVERE_CRASH_TAKE_PROFIT로 익절 통일(손절 -3%는 그대로), SEVERE_CRASH_ENTRY_CUTOFF
# 이후 신규매수만 중단(보유종목 청산은 그대로 진행, 강제청산 없음 — 사용자 수동판단).
# 조건검색 자체를 더 타이트하게(N봉 신고가+거래량 AND) 걸어놔서 진입 품질은
# 이미 높다는 전제.
SEVERE_CRASH_THRESHOLD = -5.0
SEVERE_CRASH_TAKE_PROFIT = 0.015
SEVERE_CRASH_ENTRY_CUTOFF = time(11, 0)

# ── 지수 하락 가드 (2026-08-03 사용자 지정) ─────────────────────────
# 위 SEVERE_CRASH(-5%)보다 **한 단계 얕은** 방어선. 둘은 공존한다:
#   -3% (여기)  : 11:00 이후 발동 -> 신규매수 중단 + 본전 이상이면 정리 +
#                 남은 건 14:50 강제청산
#   -5% (기존)  : 익절 flat 1.5% + 11:00 이후 신규매수 중단
# 판정은 **코스피/코스닥 중 나쁜 쪽**(둘 중 하나라도 -3% 이하면 발동).
#
# 왜 11:00부터인가: 개장 직후의 일시적 급락에 과민 반응하지 않기 위해서다.
# 11시까지 회복 못 한 하락은 그날 추세일 가능성이 높다는 판단(사용자 지정).
#
# 왜 '본전 이상만' 파는가: 지수가 무너지는 날 반등을 기다리는 것보다 본전에
# 나오는 게 낫다는 판단. 손실 중인 종목까지 즉시 던지면 저점 매도가 되므로,
# 그건 14:50까지 회복 기회를 주고 그때도 안 되면 정리한다.
#
# ⚠️ 지수 조회는 _refresh_market_rates()의 60초 캐시를 그대로 재사용한다 —
# 이미 _is_severe_crash가 매 가격갱신마다 부르고 있어 **REST 추가 부담 0**.
#
# ⚠️⚠️ (2026-08-03) 임계를 -3.0 -> **-5.0**으로 변경하면서 위 SEVERE_CRASH와
# **완전히 같은 조건**이 됐다(-5%, 11:00). 즉 지금은 지수가 -5% 이하로 빠지면
# **두 규칙이 동시에 켜진다.** 서로 상충하진 않지만 역할이 다르다:
#     SEVERE_CRASH : 익절캡을 1.5%로 축소 (+ 매수중단, 중복)
#     INDEX_GUARD  : 매수중단 + 11:30까지 본전청산 + 14:50 강제청산
#   합쳐진 결과(시뮬레이션 검증):
#     11:30 이전 순 0% 이상 -> 가드 본전청산
#     11:30 이후 순 +1.5% 이상 -> SEVERE_CRASH 익절
#     그 사이(0~1.5%)와 손실분 -> 손절(-3%) 또는 14:50 강제청산
# **둘 중 하나만 고치면 동작이 어긋난다.** 임계를 바꿀 땐 반드시 같이 볼 것 —
# 이 정합성은 test_patch_20260803.py가 검사한다.
INDEX_GUARD_ENABLED = True
INDEX_GUARD_THRESHOLD = -5.0            # 코스피/코스닥 중 하나라도 이 값 이하
INDEX_GUARD_FROM = time(11, 0)          # 이 시각부터 감시(그 전 급락은 무시)
INDEX_GUARD_BREAKEVEN_UNTIL = time(11, 30)  # 이때까지 본전 이상이면 청산
INDEX_GUARD_FORCE_CLOSE = time(14, 50)  # 남은 보유분(본전 미만) 강제청산

# 청산 정책 (EXIT_POLICY 딕셔너리에서 가져옴)
TAKE_PROFIT_CAP = EXIT_POLICY["default"]["take_profit_cap"]
STOP_LOSS_RATE = EXIT_POLICY["default"]["stop_loss_rate"]
