# [2026-08-02 제거] TRAIL_ACTIVATE / TRAIL_GIVEBACK — 트레일링 익절은
# `sub_strategy == "1L"`이 유일한 진입점이었고, 1L 삭제로 도달 불가가 됐다.
# 지금 익절은 전 전략 flat 캡(1.5% / 2.5% + 동적 상향)으로 통일돼 있다.
# EXIT_POLICY["default"]에는 trail_activate/trail_giveback 키가 그대로 남아
# 있으므로, 되살릴 때는 여기서 다시 읽어오면 된다.

# 전략/시간대별 익절 캡 (2026-07-30 사용자 지정) — 손절(-3%)은 전부 그대로 유지.
# 1B/Pullback은 짧은 반등을 노리는 전략이라 기본 2.5%까지 기다리다 되돌림에
# 물리는 경우가 많았고, 개장 직후 10분은 변동성이 커서 빠른 확정이 유리하다는
# 판단. 익절 캡은 "매수 시점"으로 결정해 포지션 보유 중에 정책이 바뀌지 않게 한다
# (09:09에 산 종목이 09:11에 기준이 올라가면 판단이 흔들리므로).
# (2026-08-02) TAKE_PROFIT_CAP_1B는 1B 삭제와 함께 제거 — 값은 Pullback과 같았다.
# (2026-08-03) 1.5% -> 2.5%. 08-03 실거래에서 익절 계열 청산 평균이 수수료
# (0.23%)를 겨우 넘는 수준이라 캡이 사실상 '수수료 내고 본전'을 만들고 있었다.
# 1A 기본캡(4.0%)보다는 여전히 타이트하게 둬서 전략 간 성격 차이는 유지한다.
TAKE_PROFIT_CAP_PULLBACK = 0.025
TAKE_PROFIT_CAP_EARLY = 0.025
EARLY_WINDOW_END = time(9, 10)  # GROUP_A_START~이 시각 사이 매수분은 이 캡

# ── 동적 익절캡 (2026-07-30 사용자 지정) ───────────────────────
# 1.5%캡 종목이 보유 중 체결강도 상승을 보이면 캡을 2.5%로 올려 더 태우고,
# 2.5%캡 종목은 체결강도 하락 AND 거래량 하락이 동시에 오면 즉시 매도한다.
# 백테스트(07-29+07-30, 확증진입 14건, 체결강도는 분봉 대용지표로 근사):
#   익절 1.5% 고정        -> 건당 -0.659%, 승률 57.1%
#   동적 상향 + 즉시매도   -> 건당 +0.040%, 승률 64.3%  (유일한 플러스 구간)
# 파라미터 표면이 매끄러웠고(상향기준 1.0<1.2<1.5 단조, 상한캡 2.5≈3.0>2.0,
# 거래량배수 0.8이 1.0보다 우수 = '진짜 감소'를 요구해야 함), 무엇보다
# 하락 판정을 AND로 걸어야 효과가 났다(OR로는 과민해서 오히려 악화).
# 주의: 강도 임계값은 과거 틱이 없어 백테스트로 검증 불가 — 실전 관찰 필요.
# 하락 임계값은 검증된 slot_replacement와 같은 값을 재사용해 일관성 유지.
# ⚠️ [대체됨, 2026-08-03] TP_CAP_UPGRADED_MAX(6.0%)로 교체. 이 값을 고쳐도
# 반영되지 않는다 — 1A 기본캡과 값이 같아(둘 다 0.025) 동적캡 즉시매도가
# 모든 1A에서 항상 참이 되던 결함의 원인이었다(아래 cap_exit 주석 참고).
TP_CAP_UPGRADED = 0.025             # [미사용]
# 상향 판단 시점 = 순수익 +1.0% 도달 (2026-07-31 사용자 지시로 1.5%->1.0% 하향).
# 이 시점에 체결강도로 갈림길을 만든다:
#   강도 상승 -> 캡을 2.5%로 올려 더 태움
#   강도 미상승 -> 여기서 익절 확정(작은 이익을 되돌림 전에 잠금)
# 백테스트에서 이 '갈림길' 구조가 핵심이었음 — 상향기준 1.0%가 1.2/1.5%보다
# 일관되게 우수(건당 -0.18~-0.28% vs -0.4~-0.63%, 승률 64.3% vs 57.1/50.0%)했고
# 유일하게 플러스가 나온 구간이었다.
# 주의: 백테스트는 gross(가격) 기준이었으나 라이브 캡 비교는 전부 net(수수료
# 차감) 기준이라 여기서도 net으로 통일했다(0.23%p 차이는 사용자에게 유리한 방향).
TP_UPGRADE_TRIGGER = 0.010
TP_UPGRADE_STRENGTH_RATIO = 1.2     # 기준강도 대비 이 배수 이상이면 상향
TP_DECLINE_STRENGTH_RATIO = 0.8     # 기준강도 대비 이 배수 미만이면 "강도 하락"
TP_DECLINE_VOLUME_RATIO = 1.0       # volume_ratio 이 값 미만이면 "거래량 하락"
TP_VOL_CHECK_SEC = 30               # 거래량 확인(REST) 종목당 최소 간격
TP_CAP_UPGRADED_MAX = 0.060         # 상향 시 목표 캡 (2026-08-03, 2.5% -> 6.0%)

# ── 본전스톱 (2026-08-03 신규, '익절 조기확정'을 대체) ─────────────
# 기존: 순 +1.0% 도달 시 체결강도가 안 올랐으면 **그 자리서 매도**(조기확정).
# 문제: 08-03 실거래 2건 모두 매도 후 더 올랐다(037070 매도가 대비 +12.0%,
#       439960 +3.4%). 이익을 지킨 게 아니라 기회를 확정해 버린 셈이었다.
# 변경: 같은 지점에서 매도하는 대신 **손절선을 본전으로 끌어올린다**.
#       하방을 먼저 닫으므로 캡을 올려도 리스크가 늘지 않는다
#       (최악의 경우 = 왕복수수료 0.23%만 손실).
# 왜 트레일링이 아니라 본전스톱인가: 08-03 틱 재생 결과 고점 대비 -0.5~1.0%
# 트레일링은 오히려 현행보다 나빴다(+0.72% vs +0.86%). 매수 직후 본격
# 상승 전에 -2.7%까지 밀리는 흔들림이 있어 좁은 트레일은 전부 털린다.
# 의미 있는 개선은 -3.0% 트레일(+9.44%)부터인데, 그 폭은 하루치 1종목으로
# 정하기엔 위험이 커서 캡(예측 가능) + 본전스톱(하방 차단) 조합을 먼저 쓴다.
#
# ⚠️ (2026-08-03 저녁) **끔**. 도입 당일 저녁에 08-03 실제 틱으로 재생해보니
# 개장 구간(09:00~09:10, 진입 16건)에서 오히려 손해였다:
#     본전스톱 끔    캡2.5% -0.177% / 캡4.0% -0.176%
#     +1.0%(도입값)  캡2.5% -0.325% / 캡4.0% -0.638%
#     +1.5%          캡2.5% -0.436%
#     +2.0%          캡2.5% -0.253%
# 개장 직후엔 변동이 커서 +1%를 찍고 무장한 뒤 되돌려 본전에 털리는 일이 잦고,
# 그게 캡까지 갈 수 있었던 포지션을 0%로 만든다.
# 단, 이 시뮬레이션의 진입은 **버스트만으로 생성**한 것이라 라이브의 무장
# (FID228) 게이트가 빠져 있어 실제보다 품질이 낮은 진입이 섞여 있다 —
# 수치를 그대로 믿을 수는 없다. 모의투자로 실험한다는 사용자 판단에 따라
# 우선 끄고, 켠 상태와 비교할 데이터를 모은다.
# 되살리려면 이 플래그만 True로 바꾸면 된다(나머지 로직은 그대로 살아있다).
# (2026-08-04 재활성화) 08-04 오전 실거래 대조 분석 결과, 조기확정 폐지로
# 비워진 중간 안전판 자리를 아무것도 대신하지 못해 손절(-3%)까지 그대로
# 밀리는 포지션이 급증(같은 09:00~09:40 창 기준 순손익 +165,345원 -> -427,200원,
# 손절 0건 -> 5건). 사용자 지정으로 재활성화.
BREAKEVEN_STOP_ENABLED = True
BREAKEVEN_TRIGGER = 0.010           # 순 +1.0% 도달 시 무장
# 2026-08-05: 0.000 -> 0.002. 바닥을 정확히 '순 0%'로 두면 매도가 시장가라
# 체결이 판정가보다 한 틱 아래에서 이뤄져 **결국 마이너스로 나간다**
# (08-05 포톤 실측: 본전스톱 발동가는 0%였는데 실현 순손익 -0.04%).
# "본전 매도 시 최대한 손실 안 나는 선"이라는 요구에 맞춰 슬리피지만큼 올렸다.
BREAKEVEN_FLOOR = 0.002             # 무장 후 순수익이 이 값 아래로 떨어지면 청산

# ── 되돌림 대기 분할매수 (2026-08-04 신규, 사용자 지정) ──────────
# 08-04 틱 재생으로 확인된 사실: **버스트 트리거 시점은 국소 고점이다.**
# 측정한 6건 전부가 트리거 후 60초 안에 되돌림을 겪었다(-0.45% ~ -1.78%).
# 버스트는 정의상 "그 순간 열기가 가장 뜨거운 지점"이라 거기서 사면 구조적으로
# 가장 비싸게 산다(동적캡 분석에서 진입강도가 300 상한으로 포화됐던 것과 같은 현상).
#
# 그래서 트리거 즉시 사지 않고 **되돌림을 기다렸다 산다.** 실측 비교:
#   즉시매수     : +5분 -0.44% / +10분 +0.97%
#   -0.5% 대기   : +5분 +0.03% / +10분 +1.64%  ← 6건 전부 체결(스킵 0건)
#   -1.0% 대기   : +5분 +0.38% / +10분 +2.05%  (1건 스킵)
# -0.5%를 1차로 쓰는 이유는 **표본이 전혀 안 바뀌는데(스킵 0) 진입가만 평균
# +0.74% 개선**되기 때문이다 — 선택 편향이 없는 순수 개선이라 근거가 가장 깨끗하다.
# 손실 거래도 같이 개선된다(빛과전자 -3.41%->-1.74%, 원익홀딩스 -3.33%->-2.63%):
# 진입가가 낮아지면 -3% 손절선까지의 거리가 그만큼 늘어나기 때문.
#
# 2단 분할인 이유: -1.0%가 성과는 더 좋지만 6건 중 1건을 놓쳤다. 절반을 -0.5%에
# 확보해 "안 오면 못 산다"를 없애고, 더 깊이 밀리면 나머지 절반이 평단가를 낮춘다.
# ⚠️ 이 표본은 09:00~09:15 틱 아카이브 6건뿐이다. **되돌림 없이 그대로 솟는
#    진짜 폭등을 놓칠 위험**은 이 표본(6/6 체결)으로는 측정되지 않았다.
ENTRY_PULLBACK_ENABLED = True
# (트리거가 대비 되돌림폭, 그 트랜치에 배정할 비중) — 비중 합은 1.0
# 2026-08-05: (0.005,0.010) -> (0.003,0.007). 실전 1일차에 되돌림 계획 21건 중
# 9건이 미도달/부분체결이었고, 실제 되돌림 폭을 재보니 -0.16~-0.96%였다.
# 1차 -0.5%는 적절했으나(9건 중 5건 체결) **2차 -1.0%가 너무 깊어**
# 1/2만 체결된 5건이 전부 -0.60~-0.96%에서 멈췄다.
#   삼기 -0.43% / SK오션플랜트 -0.35% / 포톤 -0.78% / 일승 -0.70% / JW신약 -0.60%
#   삼기 -0.87% / PS일렉 -0.96% / 금호타이어 -0.27% / GS건설 -0.16%
# 이 값으로 바꾸면 9건 중 4건의 체결이 개선된다(0/2->1/2 2건, 1/2->2/2 3건).
# ⚠️ 손익 개선은 약 +1,200원으로 거의 중립이다. 진짜 가치는 손익이 아니라
#    **설계대로 총액 100%가 체결되게 하는 것** — 지금은 의도 금액의 절반만
#    사져서 성과 측정 자체가 설계와 어긋나 있었다.
ENTRY_PULLBACK_TRANCHES = ((0.003, 0.5), (0.007, 0.5))
ENTRY_PULLBACK_TIMEOUT_SEC = 120.0   # 이 시간 안에 안 오면 남은 트랜치는 포기

# ── 되돌림 대기 중 '상승 이탈' 즉시진입 (2026-08-05 신규) ──────────────
# 되돌림을 기다리는데 **오히려 올라가면** 되돌림이 안 온다는 관측 증거다.
# 그때 남은 트랜치를 전량 시장가로 즉시 체결한다. 예측이 아니라 관측이라
# "되돌림이 안 올 종목을 미리 맞히는" 불가능한 문제를 우회한다.
#
# 실측(08-05, 계획 21건): 트리거 시점 지표로는 되돌림 깊이를 예측할 수 없었다.
#   경로별 평균 되돌림 — 절대 -0.75% / 단일 -1.30% / 상대 -1.69%
#   (절대 경로가 가장 얕고 미체결 3건이 전부 절대였지만, 같은 절대 경로에서
#    씨이랩 -4.50% / 금호건설 -3.00%도 나와 판별력이 없다)
# 반면 '+0.3% 상승 이탈' 규칙은 미도달 9건 중 7건에서 발동하고,
# 못 사던 4건을 **전부** 잡는다. 그 4건의 진입 후 결과는 3승 1패:
#   삼기 +13.30% / 금호타이어 +5.01% / GS건설 +0.99% / SK오션플랜트 +0.19%(최저 -2.70%)
#
# 되돌림 1차(-0.3%)와 대칭인 +0.3%를 쓴다 — "0.3% 내려오면 사고, 0.3% 올라가도
# 산다. 그 사이에서 머뭇거리면 안 산다"는 ±0.3% 브레이크아웃 밴드가 된다.
# ⚠️ 고가 추격 위험이 있다(SK오션플랜트가 그 사례). 손절 -3%가 받쳐준다.
ENTRY_BREAKOUT_ENABLED = True
ENTRY_BREAKOUT_PCT = 0.003       # 트리거가 대비 이만큼 오르면 잔여 전량 즉시매수

# ── 손절 대신 추가매수 (Rescue Add, 2026-08-05 신규 — 사용자 지정) ──────
# -3% 손절선에 닿았을 때, **매수세가 오히려 몰리고 있다는 증거 3개가 전부**
# 성립하면 매도 대신 같은 금액을 추가 매수해 평단을 낮춘다.
#
# ⚠️ 이건 손절이라는 최후 방어선을 조건부로 미루는 변경이다. 반드시 지킬 것:
#   - 조건은 **AND**다. 하나라도 불충족이면 그냥 손절한다.
#   - 판정 중 **예외가 나면 손절**로 수렴한다(안전측).
#   - 추가매수 후에는 **원가 대비 -6%가 무조건 청산선**이다. 이게 없으면
#     손실이 무한대로 열린다.
#   - 종목당 1회, 하루 RESCUE_ADD_MAX_PER_DAY회.
#   - MDD 차단/지수 가드/WS 격리 중이면 미발동(= 그냥 손절).
#
# 08-05 역산(조건①만 검증 가능, ②③은 틱·호가 이력이 없어 검증 불가):
#   KBI메탈 4.59배 -> 추가매수했다면 09:10에 최저 4,025로 **-6% 최종손절**
#           (그 뒤 09:24에 익절선 도달 — 바닥을 먼저 찍고 털리는 최악 경로)
#   씨이랩  3.93배 -> 익절 +2.5% 성공
#   금호건설 0.68배 -> 미발동(그냥 손절)
#   => 1승 1패, 금액으로는 -20,700원. 조건③(반등 확증)이 KBI메탈을 걸러줬을
#      가능성이 높지만(09:02~09:10 단조 하락) 확인할 방법이 없다.
RESCUE_ADD_ENABLED = True
# ① 거래대금 급증: value_acceleration(최근30초 / 120초 균일기대치) 배수
#    ⚠️ 08-05 분석에서 쓴 '당일 분봉 평균 대비 3.9~4.6배'와 창이 다르다
#       (틱 버퍼가 120초뿐이라 당일 평균을 잴 수 없다). 같은 개념의 근사치다.
RESCUE_ADD_ACCEL_MIN = 3.0
# ② 체결강도: 이 값 이상 AND 기준선(_strength_baseline) 대비 상승
RESCUE_ADD_MIN_STRENGTH = 100.0
# ③ 반등 확증: 최근 RESCUE_ADD_LOW_WINDOW초 저점 대비 이만큼 올라와 있어야 한다.
#    "안 밀리고 버틴다"가 아니라 **실제로 되돌아 올라왔다**를 요구한다 —
#    07-30에 1B 반등확증 게이트로 승률 29.7%->50%를 만든 것과 같은 구조.
RESCUE_ADD_REBOUND_PCT = 0.003
RESCUE_ADD_LOW_WINDOW = 30.0
# 추가매수 후 최종 방어선 (원가 대비). 평단 기준으로는 약 -4.5%.
RESCUE_ADD_FINAL_STOP = 0.06
RESCUE_ADD_MAX_PER_DAY = 2

# ⚠️ 관찰 창 — 이게 없으면 조건③(반등 확증)은 **원리적으로 성립할 수 없다.**
# 손절은 -3%에 **최초로 닿는 순간** 발동하는데, 그 시점엔 현재가가 곧 최근
# 저점이라 "저점 대비 +0.3% 반등"이 정의상 0%다. 즉 그냥 두면 이 기능은
# 영원히 발동하지 않는다(2026-08-05 테스트 작성 중 발견).
#
# 그래서 -3% 도달 시 조건①②(거래대금·강도)가 이미 성립해 있으면 매도를
# **잠시 보류**하고 이 시간 동안 지켜본다. 그 사이 저점을 갱신하며
#   · 저점 대비 +RESCUE_ADD_REBOUND_PCT 반등  -> 추가매수
#   · 원가 대비 -RESCUE_ADD_OBSERVE_FLOOR 이탈 -> 즉시 손절(관찰 포기)
#   · 창 만료                                  -> 손절
# 를 판정한다. 이게 사용자가 말한 "하락이 안 나오고 버티거나 상승으로 나올 시"의
# 정확한 구현이다.
#
# **추가되는 리스크는 정확히 이만큼이다**: 구조받지 못한 포지션의 손절이
# -3%가 아니라 최대 -RESCUE_ADD_OBSERVE_FLOOR(-4.5%)에서 난다. 관찰은
# ①②가 이미 성립한 경우에만 시작하므로 아무 종목에나 걸리지 않는다.
RESCUE_ADD_OBSERVE_SEC = 15.0
RESCUE_ADD_OBSERVE_FLOOR = 0.045

# ── 분할매도 (2026-08-04 신규, 사용자 지정) ──────────────────
# 체결강도 하락 신호의 예측 지평을 틱으로 실측한 결과:
#   +1분 평균 -0.91% (6건 전부 음수 — 신호가 맞다)
#   +3분 평균 +0.24% / +5분 평균 +0.22% (부호가 갈린다. 037070은 +6.5%)
# 즉 이 신호가 잡아내는 건 **일시적 눌림이지 추세 종료가 아니다.** 그런데 기존
# 코드는 이 1분짜리 신호로 포지션을 100% 영구청산했다 — 시간지평 불일치다.
# 실제 손해: 매드업 +1.95%에 전량청산했으나 6분 뒤 +3.62%(MFE +4.39%),
#            037070 +1.14%에 청산했으나 MFE +13.29% — 가용 수익의 44%/9%만 챙겼다.
# 대응: 신호의 1분 정확도는 **절반을 좋은 가격에 빼는 데** 쓰고, 3~5분 불확실성은
#       **절반을 남겨** 회복을 탄다. 어느 집단인지 미리 맞힐 필요가 없어진다.
# 트레일 3%인 이유: '고점 도달 전 되돌림'을 실측하니 매드업 2.03% / 037070 3.90%였다.
#       이보다 좁은 트레일은 본 상승 전에 반드시 털린다(08-03에 -0.5~1.0% 트레일이
#       현행보다 나빴던 이유가 이것으로 설명된다).
PARTIAL_EXIT_ENABLED = True
PARTIAL_EXIT_FRACTION = 0.5      # 신호 시 이 비중만 먼저 매도
PARTIAL_EXIT_TRAIL = 0.030       # 잔량은 고점 대비 이만큼 밀리면 청산

# ── 손실 반등 하이브리드 매도 (2026-07-31 사용자 지정) ──────────
# 손실 중인 종목이 저점에서 한 번 반등했는데 그 반등이 체결강도·거래량 어느
# 쪽으로도 뒷받침되지 않으면, 손절선(-3%)까지 끌려가지 않고 그 자리에서
# 손실을 줄여 청산한다. "수익이 나지 않더라도 손실을 최대한 적게" 대응하는 용도로,
# 되돌아온 반등 구간을 이용해 -3%보다 나은 가격에 빠져나오는 것이 목적.
# 하락 판정을 AND로 두는 건 동적 익절캡과 같은 이유 — OR은 과민해서 백테스트상
# 오히려 악화됐음(건당 -0.328% -> -0.532%, 2026-07-30).
LOSS_REBOUND_MIN = 0.01          # 저점 대비 이만큼(+1%) 이상 올라와야 '반등' 인정
LOSS_REBOUND_MIN_HOLD_MIN = 5    # 매수 후 최소 보유(분) — 직후 노이즈로 잘리는 것 방지

# ── 정체 포지션 조기 정리 (2026-08-01) ──────────────────────────
# 실측(07-28~31, 73건): 슬롯·분의 25%를 '시간정리 30분'이 먹었는데 평균
# -0.78%였고, 손익 ±0.5% 이내로 끝난 '무의미 청산' 14건이 185분(22%)을
# 점유했다. 돈을 번 청산(익절+트레일링)은 슬롯·분의 19%만 썼다.
# 30분을 다 기다리지 않고, 15분이 지나도록 아무 방향도 못 잡은 자리는
# 기회비용으로 보고 비운다. 30분 컷(HOLDING_TIMEOUT)은 최후 방어로 유지.
DEAD_POSITION_MIN = 15           # 이 시간 경과 후 판정
DEAD_POSITION_BAND = 0.005       # 순손익이 ±이 범위 안이면 '정체'로 간주

# 익절 후 재매수 상한 (2026-07-30 사용자 지정) — 손절 종목은 이미 당일 전면
# 차단이므로 사실상 익절 종목에만 적용된다. 최초 1회 + 재매수 2회 = 총 3회.
MAX_BUYS_PER_STOCK = 3

# 매도 실패 & 쿨다운 & 워밍업
MAX_SELL_FAIL = 3
REBUY_COOLDOWN = timedelta(minutes=COMMON["rebuy_cooldown_min"])
RESTART_WARMUP = timedelta(seconds=60)
BUY_WARMUP = timedelta(seconds=COMMON["buy_warmup_sec"])

# 금액 + 슬롯 (1A/Pullback/1L/1B 각각 자체 상한 3 + 전체 합산 MAX_HOLDINGS=6 공유)
POSITION_AMOUNT = COMMON["position_amount"]
MAX_HOLDINGS = COMMON["max_holdings"]
# 확장 슬롯 (2026-07-31 사용자 지정) — 평소 6개만 쓰다가, 점수가 컷라인을 크게
# 웃도는 후보가 나왔는데 슬롯교체도 성립하지 않는 상황에서만 7~8번째를 연다.
MAX_HOLDINGS_HARD = COMMON.get("max_holdings_hard", MAX_HOLDINGS)
SLOT_EXPANSION_SCORE_MARGIN = 1.5   # 컷라인 대비 이 배수 이상이어야 '정말 좋은 종목'
SLOT_EXPANSION_WAIT_SEC = 90        # 슬롯 만석이 이 시간 이상 지속돼야 확장 허용
                                    # (슬롯교체 태스크가 60초 주기 -> 한 사이클을
                                    #  넘겨도 교체가 안 됐다 = 교체 대상 없음)
# 전략별 슬롯 상한 (2026-08-01 재조정, 각 3 -> 4).
# 직전 버전에선 "10:30 이후 Pullback 슬롯이 노니까 1A 캡을 5로 올린다"였는데,
# Pullback 창이 14:50까지 늘어나면서 그 전제(노는 슬롯)가 사라졌다. 대신
# **두 전략의 캡 합(8)이 공유 상한(MAX_HOLDINGS=6)을 넘도록** 잡는다:
#   - 3/3이면 합이 정확히 6이라 한쪽이 하루 종일 후보를 못 찾아도 다른 쪽이
#     그 자리를 못 쓰고 슬롯이 논다(실측 슬롯 사용률 9.9%인 상황에서 특히 손해).
#   - 4/4면 공유 상한이 실제 제한자가 되어, 기회를 찾은 쪽이 최대 4까지 쓰고
#     경합은 tier 기반 우선순위 교체가 조정한다.
#   - 부수 효과로 확장 슬롯(7~8)의 구조적 도달 불가도 계속 해소된 상태로 유지
#     (합 8 > 6이라 7번째를 요청할 주체가 존재).
# 한 전략이 6칸을 독식하는 일은 여전히 불가능하다(캡 4).
PHASE1A_MAX_SLOTS = 4
PULLBACK_MAX_SLOTS = 4

# ⚠️ [미사용, 2026-08-02] 옛 watch_candidates 큐(1N 눌림목) 시절의 잔재.
# 그 전략은 2026-07-27에 삭제됐고 지금 감시 목록은 watch_list_today +
# phase1b.watched로 관리되며 별도 상한/타임아웃을 두지 않는다.
MAX_WATCH_SLOTS = 10
WATCH_TIMEOUT = timedelta(minutes=10)

# [2026-08-02 제거] 1L 슬롯/임계값 상수(LEADING_MAX_SLOTS/STRENGTH_MIN/SUSTAIN).

# ── 1B 전략 삭제 (2026-08-02, 사용자 지정) ─────────────────────────
# 2026-08-01에 PHASE1B_ENABLED=False로 비활성화한 뒤 실제로 한 번도 켜지
# 않았고, 되살릴 계획도 없어 관련 코드/상수를 전부 제거했다.
#
# 비활성화 당시의 판단 근거(보존): 1A와 1B가 같은 후보 풀(조건검색 편입
# 종목)과 같은 데이터 소스(TradeFlowTracker)를 공유하면서 정반대 방향을
# 본다 — 1A는 '지금 매수세가 터진다'에 사고, 1B는 '60초 내 -2% 밀렸다'에
# 산다. 같은 종목이 두 트리거를 번갈아 만족하면 진입 타이밍이 오락가락하고
# 어느 로직이 그 자리를 만들었는지 사후 분석도 불가능해진다.
#
# 삭제된 것: PHASE1B_ENABLED / PHASE1B_MAX_SLOTS / PHASE1B_PULLBACK_PCT /
#   PHASE1B_PULLBACK_WINDOW_SEC / PHASE1B_CONFIRM_* / TAKE_PROFIT_CAP_1B,
#   _try_phase1b_buy / _check_1b_confirmations / can_buy_phase1b / _1b_confirm,
#   on_trade의 하락 트리거, WallDetector·ChemulEvaluator 배선.
#   되살릴 일이 있으면 커밋 900757c를 참고할 것(파라미터 근거 주석 포함).
#
# ⚠️ phase1b **컨트롤러 객체**는 삭제하지 않았다 — 이제 1B 전략이 아니라
# 1A/Pullback의 체결틱·호가 데이터 파이프라인(TradeFlowTracker,
# OrderbookTracker)이기 때문이다. 없애면 두 전략이 눈이 먼다.

# MDD 일손실 차단
DAILY_LOSS_LIMIT = COMMON["mdd_daily_loss_limit"]


def _notify(msg: str, target: str = "signal"):
    if send_telegram is None:
        return
    try:
        send_telegram(msg, target=target)
    except Exception as e:
        logger.warning("텔레그램 전송 실패: %s", e)


class StrategyManager:
    def __init__(
        self,
        kiwoom_rest,
        order_manager,
        phase1b_controller=None,
        portfolio_optimizer=None,
        now_func=None,
    ):
        self.api = kiwoom_rest
        self.order_manager = order_manager
        self.phase1b = phase1b_controller
        self.optimizer = portfolio_optimizer
        self._now = now_func or datetime.now

        self.holdings: dict[str, dict] = {}
        # 재평가 대상 후보 (watchlist_reentry / slot_replacement가 순회)
        self.watch_list_today: set[str] = set()
        # DB(watch_list_log)에 실제로 행을 쓴 종목 (2026-08-01 분리).
        # 기존엔 watch_list_today 하나로 두 역할을 겸해서, 평가 지연 경로가
        # watch_list_today에 먼저 넣어버리면 나중에 _record_watch_list가
        # "이미 있음"으로 조기 반환해 **DB 행이 영영 안 남는** 구멍이 있었다
        # (09:20 지연 종목/장 시작 전 편입 종목 → 일일 백테스트·틱아카이브
        #  유니버스에서 통째로 누락).
        self._watch_db_written: set[str] = set()
        self.pending: set[str] = set()
        self._stock_names: dict[str, str] = {}
        self._cond_names: dict[str, str] = {}  # stock_code -> 최초 편입 조건검색식 이름
        self._opening_prices: dict[str, float] = {}  # stock_code -> 당일 시가 (1A 서지율 점수용)
        self._prev_closes: dict[str, float] = {}  # stock_code -> 전일종가 (등락률 상한 체크용, 2026-07-31)
        # 평상시 상한(MAX_HOLDINGS)이 꽉 찬 시각 — 확장 슬롯(7~8) 판정용 (2026-07-31)
        self._soft_cap_full_since: Optional[datetime] = None
        # 장중 전략 성과 추적 — 잘 되는 전략의 컷라인을 낮추고 안 되는 전략은
        # 물러나게 하는 자동 우선순위 조정 (2026-07-31, core/strategy_performance.py)
        self.perf = StrategyPerformanceTracker(now_func=self._now)
        # 프로그램 매매 유입 관측 (2026-07-31) — 지금은 기록/백테스트 전용이고
        # 매매 판단에는 전혀 쓰지 않는다. 데이터 소스가 확정되면(WS 0B FID 또는
        # 시장 전체 랭킹 REST) record_minute()으로 넣어주기만 하면 된다.
        self.program_flow = ProgramFlowTracker(now_func=self._now)
        self._watch_scores: dict[str, float] = (
            {}
        )  # stock_code -> 워치리스트 등재 시 점수 (슬롯교체용, 2026-07-26)
        self.vwap_strategy = VWAPStrategy()  # 눌림목(1A) VWAP AND 필터
        self.explosion_scorer = (
            ExplosionPatternScorer()
        )  # 거래대금 폭발 이력 스코어러 (2026-07-26)

        # 주도테마 초기화 (등락률 기반, 2026-07-06 재설계)
        # ⚠️ 1L 전략은 삭제됐지만 theme_mgr은 계속 살아있다 — 이제 매수 "전"
        # 게이트가 아니라 매수 "후" 동적 익절캡 가산점으로 쓰인다
        # (on_price_update의 is_leading 참고).
        self.theme_mgr = ThemeManager(rest_api=kiwoom_rest)
        self.theme_mgr.fetch_themes_from_github()
        self.theme_mgr.start_auto_update()

        # ── 진입 진단 (2026-08-01 신규) ────────────────────────────
        # "조건검색엔 계속 포착되는데 매수가 안 된다"를 장중에 원인별로
        # 판단할 수 있게 하는 관측 인프라. 종목별 마지막 탈락 사유와
        # 사유별 종목 수를 들고 있다가 주기적으로 텔레그램으로 요약한다.
        # 로그를 뒤지지 않고도 "필터가 막는 중"인지 "코드가 고장난 것"인지
        # 구분하는 게 목적이라, 카테고리를 그 두 축으로 나눠 집계한다.
        self._last_reject: dict[str, tuple[str, str, datetime]] = {}  # code -> (분류, 원문, 시각)
        self._last_buy_at: Optional[datetime] = None

        # 매수 진행중(pending) 종목의 전략 — 슬롯 오버부킹 방지용 (2026-08-01).
        # _execute_buy가 주문 직전에 넣고 finally에서 지운다.
        self._pending_strategy: dict[str, str] = {}

        # ── 틱 구동 진입 상태 (2026-08-02) ────────────────────────────
        # _strength_since: 키움 체결강도(FID 228)가 TICK_STRENGTH_MIN 이상으로
        #   올라선 최초 시각(epoch). 밑으로 떨어지면 None으로 리셋되므로
        #   "지금 몇 초째 연속 유지 중인가"가 now - 이 값으로 바로 나온다.
        #   윈도우 평균이 아니라 진짜 '연속'을 재기 위한 구조.
        self._strength_since: dict[str, float] = {}
        # 무장(3초 충족) 완료 시각 — TICK_ARM_TTL_SEC 안에 버스트가 와야 발사.
        self._armed_at: dict[str, float] = {}
        # 종목별 마지막 전체 게이트 평가 시각(쿨다운용)
        self._tick_entry_last: dict[str, float] = {}
        # on_trade는 asyncio.to_thread로 실행돼 여러 틱이 동시에 들어올 수 있다.
        # 슬롯 확인~pending 등록 사이가 열려 있으면 같은 종목을 두 번 사거나
        # 마지막 슬롯 하나를 둘이 통과할 수 있어서 진입 구간을 직렬화한다.
        self._tick_entry_lock = threading.Lock()
        # 진단용 — 틱 경로가 실제로 도는지, 어디서 걸리는지 집계
        self._tick_entry_stats = {
            "ticks": 0, "armed": 0, "burst_ok": 0, "bought": 0,
        }
        # ── FID 228(키움 공식 체결강도) 수신 감시 (2026-08-02) ──────────
        # 무장 -> 발사 전체가 이 필드 하나에 걸려 있는데, **실거래에서 값이
        # 들어오는 걸 확인한 적이 없다**(파싱 코드는 예전부터 있었지만 1L을
        # 주석처리한 뒤로 아무도 쓰지 않았다). 228이 안 오면 무장이 영원히
        # 0건이고 -> 하루 종일 매수 0건인데, 로그를 직접 뒤지기 전엔 원인을
        # 알 수 없다. 그래서 "체결틱은 오는데 228만 없는" 상태를 명시적으로
        # 구분해 진단 알림이 바로 짚어주게 한다.
        self._trade_tick_total = 0          # 수신한 체결틱 총수(0B 자체가 오는가)
        self._fid228_seen: set[str] = set()  # 228이 실제로 실려온 종목
        self._fid228_alerted = False         # 긴급 경고 1회만
        # 당일 시가는 기존 _opening_prices 캐시를 그대로 쓴다(중복 캐시 금지).
        # 틱 경로는 분봉을 아예 안 받으므로 캐시가 비어 있으면 "시가대비 +5%
        # 매수보류" 필터를 건너뛴다 — 모르는 값으로 매수를 막지 않는다.
        # 편입 시 _prearm_candidate()가 미리 채워준다.

        # 되돌림 대기 분할매수 계획 (2026-08-04).
        # {code: {"trigger_price","targets":[(price,frac),...],"deadline",
        #         "sub_strategy","info","cond_name","phase","stock_name","filled"}}
        # ⚠️ 이 dict에 있는 종목은 **슬롯을 점유한 것으로 센다**(occupied_slots).
        #    안 그러면 대기하는 동안 다른 종목이 그 자리를 가져가, 되돌림이 와도
        #    살 자리가 없어진다 — 대기 설계 자체가 무의미해진다.
        self._entry_plans: dict[str, dict] = {}
        # 종목별 당일 매수 횟수(익절 후 재매수 상한용) + 동적캡 거래량확인 throttle
        self._buy_count_today: dict[str, int] = {}
        self._tp_vol_checked_at: dict[str, datetime] = {}

        self.sell_fail_count: dict[str, int] = {}
        self.sell_blocked: set[str] = set()
        self.sold_at: dict[str, datetime] = {}
        self._stoploss_blocked: set[str] = set()  # 손절로 나간 종목(당일 재매수 금지)
        self._buy_success_count = 0
        # 손절 대신 추가매수(Rescue Add) 당일 발동 횟수 (2026-08-05)
        self._rescue_count_today = 0
        # MDD 일손실 차단 (실현손익 기준 -3%)
        self._base_capital = None  # 기준자본 (첫 매수 시도 때 1회 기록)
        self._daily_realized = 0.0  # 오늘 실현손익 누적
        self._risk_tripped = False  # 차단기 발동 여부
        self._risk_date = self._now().date()
        # 지수 방어 (코스피+코스닥 중 더 나쁜 쪽 기준 threshold 조절/매수 차단)
        self._kospi_rate = 0.0
        self._kosdaq_rate = 0.0
        self._market_rate_at = None  # 마지막 조회 시각
        # WS 재연결 격리기간 (신규매수만 보류, 청산감시는 계속) — main.py가 설정
        self.quarantine_until = self._now()
        self._last_market_mode = "NORMAL"  # 지수방어 모드 전환 알림용
        self._last_severe_crash_state = False  # 지수 급락 대응 모드 전환 알림용
        self._last_index_guard_state = False   # 지수 하락 가드 전환 알림용
        self._index_guard_exited: set[str] = set()  # 가드로 이미 청산한 종목

        # 점수 기반 진입 설정 (1A 전용). surge_min은 score_phase1이 안 쓰는
        # 필드라 ScoreConfig 기본값 그대로 둠.
        self.score_cfg = ScoreConfig(
            surge_target=SURGE_THRESHOLD,
            ma_tolerance=MA_TOUCH_TOLERANCE,
            volume_target=VOLUME_SURGE_RATIO,
            threshold_ratio=0.75,
        )
        # Pullback 전용 cfg (2026-07-29 분리) — MA/양봉은 게이트(눌림성립+반등확인)로
        # 이미 확정된 값이라 점수에서 빼고 거래량/강도/OBV로 9점 재분배, 컷라인도
        # 낮춤(0.75->0.5). 실측 근거: 1A와 같은 cfg를 쓰던 기존엔 MA+양봉이 항상
        # 만점(4/9 고정)이고 강도는 phase1b 감시 시작 전이라 거의 항상 0점이라,
        # 오늘 점수단계 277건이 전부 탈락(0건 통과)했었음.
        self.pullback_score_cfg = ScoreConfig(
            ma_tolerance=MA_TOUCH_TOLERANCE,
            volume_target=VOLUME_SURGE_RATIO,
            w_volume=4.0,
            w_strength=3.0,
            w_obv=2.0,
            threshold_ratio=0.5,
        )
        self._restore_from_db()
        self._last_phase = self.get_current_phase()

    # ========================================
    # 당일/전일 분봉 병합 (장초반 MA 계산용)
    # ========================================
    def _get_merged_candles(
        self, stock_code: str, interval: int = 1, count: int = 60
    ) -> list:
        """
        당일 분봉만으로 개수가 부족할 경우, 전일 분봉을 끌어다 붙여서 개수를 맞춤.
        장 초반(예: 9:20)에 30MA 계산을 위해 30개를 요청해도 20개만 올 때 유용.
        """
        # 1. 일단 당일 데이터 요청
        today_candles = self.api.get_minute_candles(
            stock_code, interval=interval, count=count
        )

        # 2. 요구 개수를 채웠거나 당일 데이터가 아예 없으면 그대로 반환
        if not today_candles or len(today_candles) >= count:
            return today_candles or []

        # 3. 부족한 개수 계산
        needed = count - len(today_candles)

        # 4. 전일 날짜 계산
        yesterday = (self._now() - timedelta(days=1)).strftime("%Y%m%d")

        try:
            # 5. 전일 데이터 요청 (최근 봉부터 과거로 내려옴)
            yesterday_candles = self.api.get_minute_candles(
                stock_code, interval=interval, count=needed, base_date=yesterday
            )

            if yesterday_candles:
                # 6. 전일 데이터(과거) + 당일 데이터(최근) 순서로 병합
                merged = yesterday_candles + today_candles
                logger.info(
                    f"📊 [{stock_code}] 분봉 부족 보완: 당일 {len(today_candles)}개 "
                    f"+ 전일 {len(yesterday_candles)}개 = 총 {len(merged)}개"
                )
                return merged
        except Exception as e:
            logger.warning(f"[{stock_code}] 전일 분봉 조회 실패: {e}")

        # 전일 조회 실패 시 그냥 당일 데이터라도 반환
        return today_candles

    @staticmethod
    def source_flags(cond_name: str) -> tuple[bool, bool]:
        """조건검색식 소스 판별 -> (1A 소스 있음, 눌림목 소스 있음).

        (2026-08-01) 중복 편입 종목의 시간대별 전략 전환을 위해 분리했다.
        기존엔 "눌림목자동 in cond_name" 하나로만 봤는데, 그러면 중복 종목이
        시각과 무관하게 항상 Pullback으로 가버려 오전 모멘텀 구간을 못 쓴다.
        """
        cn = cond_name or ""
        has_1a = ("주도주상위" in cn) or ("돌파자동매매용" in cn)
        has_pb = "눌림목자동" in cn
        return has_1a, has_pb

    @classmethod
    def resolve_strategy(cls, cond_name: str, now_t) -> str:
        """이 종목을 어느 전략이 가져갈지 결정 -> "1A" | "1A_눌림".

        (2026-08-01 사용자 지정) 단독 소스는 완전 분리, 중복 소스만
        DUAL_SOURCE_PULLBACK_FROM(10:30)을 경계로 갈아탄다:
            눌림목자동 단독            -> 항상 1A_눌림
            주도주상위/돌파 단독       -> 항상 1A
            중복(둘 다)                -> 10:30 이전 1A / 이후 1A_눌림
            둘 다 아님("기타" 등)      -> 1A (기존 폴백 유지)
        라우팅과 주문 직전 가드가 같은 함수를 쓰므로 둘이 어긋날 수 없다.
        """
        has_1a, has_pb = cls.source_flags(cond_name)
        if has_pb and has_1a:
            return "1A_눌림" if now_t >= DUAL_SOURCE_PULLBACK_FROM else "1A"
        return "1A_눌림" if has_pb else "1A"

    @staticmethod
    def _entry_change_cap(sub_strategy: str) -> float:
        """전략별 매수 등락률 상한(전일종가 대비 %) (2026-08-01 사용자 지정).

        눌림목 = 10% / 그 외(1A) = 16%.

        기준을 **실제 매수한 전략(sub_strategy)** 하나로 통일했다. 예전엔
        cond_name도 같이 봐서 "눌림목자동이 섞여 있으면 무조건 10%"였는데,
        중복 종목이 오전에 1A로 매수되는 경로가 생기면서 그 종목만 1A인데
        눌림목 상한(10%)이 걸리는 모순이 생긴다. 상한은 "어떤 전략으로
        샀는가"를 따라가는 게 맞다.
        """
        if sub_strategy == "1A_눌림":
            return MAX_ENTRY_CHANGE_PCT_PULLBACK
        return MAX_ENTRY_CHANGE_PCT

    @staticmethod
    def cond_perf_key(cond_name: str) -> str:
        """조건검색식 성과 추적용 정규화 키 (2026-08-01, 제안 B).

        cond_name은 "주도주상위+돌파자동매매용"처럼 병합돼 들어올 수 있는데,
        그대로 키로 쓰면 조합마다 표본이 쪼개져 최소표본(3건)에 영원히 도달하지
        못한다. 우선순위가 아니라 **표본을 모으기 위한** 대표값 하나로 접는다.
        (주도주상위가 1A의 주 소스이므로 먼저 확인)
        """
        cn = cond_name or ""
        for name in ("주도주상위", "돌파자동매매용", "눌림목자동"):
            if name in cn:
                return COND_PERF_PREFIX + name
        return COND_PERF_PREFIX + "기타"

    @staticmethod
    def _score_ratio(info: dict) -> float:
        """전략 공통 비교용 '컷라인 대비 비율' (2026-08-01 신규).

        1A는 체결강도(0~300), Pullback은 점수(0~9)로 스케일이 완전히 달라서
        원점수를 그대로 비교하면 슬롯교체·확장슬롯 판정이 전부 1A 쪽으로
        기울었다. 1.0 = 자기 컷라인을 정확히 충족, 1.5 = 컷라인의 1.5배.
        점수 정보가 없는 경로(1B/1L)는 0.0 — 비교 대상에서 자연히 빠진다.
        """
        score = info.get("score")
        thr = info.get("score_threshold")
        if score is None:
            return 0.0
        try:
            score = float(score)
            thr = float(thr) if thr else 0.0
        except (TypeError, ValueError):
            return 0.0
        if thr <= 0:
            return 0.0
        return score / thr

    def _today_open(self, candles: list) -> float:
        """분봉 리스트에서 **당일** 첫 봉의 시가를 뽑는다 (2026-08-01 신규).

        기존 호출부들은 `candles[-1]["open"]`을 '당일 시가'로 썼는데, 이
        프로젝트의 분봉은 내림차순(최신->과거)이라 그건 '가장 오래된 봉'이고,
        개장 직후엔 키움이 요청 개수를 채우려고 **전일 봉까지** 붙여 주므로
        실제로는 전일 데이터였다(07-30 09:01 실측: candles[-1] = 07-29 15:09봉).
        그 결과 1A의 "시가대비 +5% 매수보류"가 사실상 '전일종가 대비 +5%'로
        동작해 개장 초반 주도주 대부분이 잘렸다.

        time_str로 오늘 봉만 걸러 가장 이른 봉의 시가를 쓴다. 오늘 봉이
        하나도 없으면 0.0 — 호출부는 0이면 시가 기반 필터를 건너뛴다
        (모르는 값으로 막지 않는다).
        """
        if not candles:
            return 0.0
        today_str = self._now().strftime("%Y%m%d")
        today_only = [
            c for c in candles
            if str(c.get("time_str", "")).startswith(today_str)
        ]
        if not today_only:
            return 0.0
        first = min(today_only, key=lambda c: str(c.get("time_str", "")))
        try:
            return float(first.get("open") or 0.0)
        except (TypeError, ValueError):
            return 0.0

    # ========================================
    # 순수익률 계산 (수수료 차감)
    # ========================================
    @staticmethod
    def _gross_rate(buy_price: float, current_price: float) -> float:
        return (current_price - buy_price) / buy_price if buy_price else 0.0

    @staticmethod
    def _net_rate(buy_price: float, current_price: float) -> float:
        """수수료(왕복)+세금 차감 순수익률."""
        if not buy_price:
            return 0.0
        gross = (current_price - buy_price) / buy_price
        return gross - ROUND_TRIP_COST

    @staticmethod
    def _net_profit(buy_price: float, current_price: float, qty: int) -> float:
        """실제 순손익 금액 (왕복 수수료/세금 차감, _net_rate와 동일 기준)."""
        buy_amt = buy_price * qty
        gross_profit = (current_price - buy_price) * qty
        return gross_profit - buy_amt * ROUND_TRIP_COST

    # ========================================
    # 상태 복원
    # ========================================
    def _restore_from_db(self):
        warmup_until = self._now() + RESTART_WARMUP
        for h in TradeRepository.find_holdings():
            buy_price = float(h["buy_price"])
            self.holdings[h["stock_code"]] = {
                "trade_id": h["id"],
                "buy_price": buy_price,
                # 재시작 복원 시 DB의 buy_price는 이미 평단일 수 있다(분할 2차/
                # 추가매수 반영분). 원가를 복원할 방법이 없으므로 평단을 원가로
                # 간주한다 — 최종 방어선이 원가 기준보다 **얕아져** 보수적이다.
                "origin_price": buy_price,
                "buy_quantity": int(h["buy_quantity"]),
                "buy_time": h["buy_time"],
                "stock_name": h["stock_name"],
                "strategy_phase": h["strategy_phase"],
                "sub_strategy": h.get("sub_strategy"),
                "highest_price": buy_price,
                "ma20": None,  # 20MA 캐시 (미계산)
                "ma20_updated": None,  # 20MA 갱신 시각
                "warmup_until": warmup_until,
            }
        for w in WatchListRepository.find_by_date(self._now().date()):
            self.watch_list_today.add(w["stock_code"])
            self._watch_db_written.add(w["stock_code"])

        blocked, cooldowns, counts = self._restore_daily_risk_state()

        logger.info(
            "DB 복원: 보유 %d (1A=%d, 눌림=%d) / 워치 %d / 워밍업 %ds "
            "/ 손절차단 %d종목 / 쿨다운 %d종목 / 매수횟수기록 %d종목",
            len(self.holdings),
            self.count_holdings_by_strategy("1A"),
            self.count_holdings_by_strategy("1A_눌림"),
            len(self.watch_list_today),
            int(RESTART_WARMUP.total_seconds()),
            blocked, cooldowns, counts,
        )

    def _restore_daily_risk_state(self) -> tuple[int, int, int]:
        """당일 리스크 상태(손절차단/쿨다운/재매수횟수) DB 재구성 (2026-07-31).

        _stoploss_blocked/sold_at/_buy_count_today는 전부 메모리 전용 set/dict라
        재시작하면 통째로 비워졌다 — 그날 이미 손절한 종목이 재시작 직후 재매수
        차단 없이 그대로 다시 매수되는 실거래 사고로 발견됨(413630 씨피시스템,
        09:53 손실청산 -> 재시작 -> 10:09 재매수). holdings처럼 여기도 DB에서
        재구성해야 재시작이 리스크 관리 기록을 지우는 구멍이 없어진다.

        기준: 오늘자 trades 전체(보유+청산)를 한 번에 읽어
          - 매수 횟수: 행 하나당 1회(재매수 상한 카운트)
          - 손절 차단: status='closed' AND 순손익(profit_amount, 없으면
            profit_rate로 폴백) < 0 인 종목
          - 쿨다운: status='closed'인 행의 sell_time 중 가장 최근 값
        반환: (손절차단 종목수, 쿨다운 대상 종목수, 매수횟수 기록 종목수) — 로그용."""
        try:
            rows = TradeRepository.find_by_date(self._now().date())
        except Exception as e:
            logger.warning("당일 리스크 상태 DB 복원 실패(빈 상태로 시작): %s", e)
            return 0, 0, 0

        for r in rows:
            code = r.get("stock_code")
            if not code:
                continue
            self._buy_count_today[code] = self._buy_count_today.get(code, 0) + 1

            if r.get("status") != "closed":
                continue
            sell_time = r.get("sell_time")
            if sell_time and (code not in self.sold_at or sell_time > self.sold_at[code]):
                self.sold_at[code] = sell_time

            net = r.get("profit_amount")
            if net is None:
                pr = r.get("profit_rate")
                net = -1 if (pr is not None and float(pr) < 0) else 0
            if net is not None and float(net) < 0:
                self._stoploss_blocked.add(code)

        return len(self._stoploss_blocked), len(self.sold_at), len(self._buy_count_today)

    # ========================================
    # 주기 루프 (주기 호출)
    # ========================================
    def tick(self):
        now = self._now()

        # 되돌림 대기 계획 만료 회수 (2026-08-04).
        # HALT 반환보다 **위**에 둔다 — 지수 HALT로 루프가 멈춰도 계획이 남아
        # 슬롯을 영구 점유하면 안 된다. 만료 처리는 매수를 유발하지 않는다.
        try:
            self.expire_entry_plans()
        except Exception:
            logger.exception("되돌림 대기 계획 만료 처리 실패")

        # 지수 방어막 HALT면 루프 전체 정지
        if self._get_market_defense_mode() == "HALT":
            return

        cur_phase = self.get_current_phase()
        if cur_phase != self._last_phase:
            self._last_phase = cur_phase

        # 감시 종목 정리 (2026-08-01 전면 수정 — 치명적 회귀 해소)
        #
        # 기존엔 "10:30(PULLBACK_END) 이후 미보유 감시종목 전부 stop_watching"
        # 이었다. 이건 1B(10:30 종료)용 정리였는데, 1A가 같은 phase1b의
        # TradeFlowTracker를 쓰도록 바뀌면서 **1A의 체결틱 버퍼를 10초마다
        # 통째로 지우는** 구조가 됐다(stop_watching -> trade_flow.reset).
        # 1A 시간창은 14:50까지인데 10:30 이후 버퍼가 계속 비워지니
        # is_intensity_sustained가 항상 실패 -> 1A 창의 70%가 죽어 있었다
        # (재현 검증: 동일 틱 흐름에서 3초 거래대금이 1/6로 떨어짐).
        #
        # 새 규칙: 1A 창(14:50)까지는 후보/보유 종목의 감시를 유지하고,
        # '더 이상 후보도 보유도 아닌' 종목만 정리해서 메모리를 묶는다.
        self._cleanup_watched(now)

        self._track_soft_cap_full(now)
        self._update_dynamic_caps()
        self.check_timeouts()

    def _cleanup_watched(self, now):
        """phase1b 감시 목록 정리 (2026-08-01 신규).

        감시 목록은 1A의 데이터 수집 대상이다(체결틱 + 호가). 따라서
          - 보유 종목: 항상 유지 (동적 익절캡/손실반등 매도가 실시간 강도를 봄)
          - 오늘 후보(watch_list_today): 1A 창(PHASE1A_END)까지 유지
          - 그 외: 즉시 해제
        1A 창이 끝나면 후보도 해제해서 메모리를 정리한다.
        """
        if not self.phase1b:
            return
        in_window = now.time() < ENTRY_WINDOW_END
        for code in list(self.phase1b.watched):
            if code in self.holdings:
                continue
            if in_window and code in self.watch_list_today:
                continue
            self.phase1b.stop_watching(code)
            # 틱 버퍼(trade_flow)를 비우면서 강도 타이머만 남겨두면 데이터와
            # 상태가 어긋난다 — 다시 감시가 켜졌을 때 옛 타이머로 즉시
            # 무장되므로 반드시 같이 지운다 (2026-08-02).
            self.reset_tick_entry_state(code)

    # ========================================
    # Phase 판별 (09:00~14:50 그룹A 활성 여부)
    # ========================================
    def get_current_phase(self) -> Optional[int]:
        t = self._now().time()
        if GROUP_A_START <= t < PHASE1A_END:
            return 1
        return None

    def _ensure_base_capital(self):
        """기준자본 1회 기록 (주문가능 + 보유 매입원가). 재시작 시에도 근사 유지."""
        if self._base_capital is not None:
            return
        try:
            deposit = float(self.api.get_orderable_amount())
        except Exception:
            return
        holding_cost = sum(
            p["buy_price"] * p["buy_quantity"] for p in self.holdings.values()
        )
        self._base_capital = deposit + holding_cost
        logger.info(
            "MDD 기준자본 기록: %s원 (주문가능 %s + 보유원가 %s)",
            f"{self._base_capital:,.0f}",
            f"{deposit:,.0f}",
            f"{holding_cost:,.0f}",
        )

    def _risk_daily_reset(self):
        today = self._now().date()
        if today != self._risk_date:
            self._risk_date = today
            self._daily_realized = 0.0
            self._risk_tripped = False
            self._base_capital = None
            self._buy_count_today.clear()  # 재매수 상한도 하루 단위 (2026-07-30)

    def risk_can_trade(self) -> bool:
        """일손실 -3% 차단기. 트립되면 신규 매수 전면 금지(청산은 계속 작동)."""
        self._risk_daily_reset()
        self._ensure_base_capital()
        if self._risk_tripped:
            return False
        if self._base_capital and self._base_capital > 0:
            loss_rate = self._daily_realized / self._base_capital
            if loss_rate <= DAILY_LOSS_LIMIT:
                self._risk_tripped = True
                logger.warning(
                    "MDD 일손실 차단 발동: 실현 %s원 (%.2f%%) <= 한도 %.1f%%",
                    f"{self._daily_realized:,.0f}",
                    loss_rate * 100,
                    DAILY_LOSS_LIMIT * 100,
                )
                _notify(
                    f"🛑 MDD 일손실 차단 발동\n"
                    f"실현손익: {self._daily_realized:,.0f}원 ({loss_rate*100:.2f}%)\n"
                    f"기준자본 {self._base_capital:,.0f}원 대비 한도 {DAILY_LOSS_LIMIT*100:.1f}% 초과\n"
                    f"→ 오늘 신규 매수 전면 차단 (보유분 청산은 계속)"
                )
                return False
        return True

    def _refresh_market_rates(self):
        """코스피/코스닥 등락률 1분 캐시. 실패해도 기존값 유지(봇 안 멈춤)."""
        now = self._now()
        if (
            self._market_rate_at is not None
            and (now - self._market_rate_at).total_seconds() < 60
        ):
            return
        try:
            self._kospi_rate = self.api.get_index_change_rate("001")
        except Exception:
            pass  # 조회 실패 시 기존 캐시값 유지
        try:
            self._kosdaq_rate = self.api.get_index_change_rate("101")
        except Exception:
            pass
        self._market_rate_at = now

    def _adjusted_cfg(self, base_cfg):
        """지수 방어 모드(코스피/코스닥 중 나쁜 쪽) 반영해 threshold_ratio 조절한 cfg 복사본 반환.
        CAUTION/HALT 모두 타이트하게(HALT는 can_buy_more에서 이미 매수 차단되지만 이중 방어)."""
        mode = self._get_market_defense_mode()
        if mode == "NORMAL":
            return base_cfg
        new_ratio = max(0.5, min(1.0, base_cfg.threshold_ratio + 0.05))
        return _dc_replace(base_cfg, threshold_ratio=new_ratio)

    def _entry_block_reason(self) -> Optional[str]:
        """**슬롯과 무관하게** 신규매수를 전면 차단하는 사유. 없으면 None.
        (2026-08-04 신설 — 같은 규칙이 세 곳에 흩어져 생긴 결함을 한 점으로 모음)

        왜 따로 뽑았나: 예전엔 이 판정들이 can_buy_more 안에만 있어서, 호출부는
        "살 수 없다"는 사실만 알고 **이유가 슬롯인지 리스크 차단인지 구분하지
        못했다.** 그 결과 두 가지 실제 문제가 있었다.

          ① 우선순위 교체가 매도만 하는 반쪽 동작 — _try_1a_priority_upgrade는
             "슬롯이 꽉 찼다"는 신호를 받으면 보유분을 팔아 자리를 비운다.
             그런데 차단 사유가 지수 가드/MDD/HALT/WS격리면 자리를 비워도
             매수가 막혀 있어 **손실만 확정하고 자리는 그냥 빈다.**
             (08-03에 slot_replacement에서 똑같은 문제를 고쳤는데 이쪽 경로엔
              같은 방어가 없었다 — 규칙이 여러 곳에 흩어진 전형적 사고.)
          ② 진단 알림 오분류 — 가드로 하루 종일 못 사는 날에도 사유가
             "슬롯 부족"으로 기록돼, 장중에 원인을 판단할 수 없었다.

        판정 순서는 기존 can_buy_more와 동일하게 유지한다(리스크 -> HALT ->
        가드 -> 격리). 전부 캐시/메모리 판정이라 핫패스 비용이 없다
        (risk_can_trade의 기준자본은 1회만 REST, 지수는 60초 캐시).
        """
        if not self.risk_can_trade():
            return "MDD 일손실 차단 — 신규매수 중단"
        if self._get_market_defense_mode() == "HALT":
            return "지수 -5% 초과로 인한 전면 매매 중단"
        # 지수 하락 가드(11:00~) — 슬롯이 남아도 신규매수를 막는다.
        if self._is_index_guard_active():
            return f"지수 하락 가드({INDEX_GUARD_THRESHOLD:+.0f}%) — 신규매수 중단"
        if self._now() < self.quarantine_until:
            return "WS 재연결 격리 중 — 신규매수 중단"
        return None

    def can_buy_more(self, info: dict | None = None, sub_strategy: str | None = None) -> bool:
        if self._entry_block_reason():
            return False
        held = self.occupied_slots()
        # 오늘 성과가 나쁜(COLD) 전략은 공유 슬롯 마지막 칸을 다른 전략에
        # 양보한다 — 잘 안 되는 전략이 마지막 자리를 선점해 버리는 것을 막는
        # 우선순위 장치. (2026-07-31)
        soft_limit = MAX_HOLDINGS
        if sub_strategy:
            soft_limit = self.perf.shared_slot_limit(sub_strategy, MAX_HOLDINGS)
        if held < soft_limit:
            return True
        # 평상시 상한(6)을 넘어선 확장 슬롯(7~8)은 예외 경로 — info가 있고
        # 그 점수가 컷라인을 크게 웃도는 후보에게만 열린다. (2026-07-31)
        if held >= MAX_HOLDINGS_HARD:
            return False
        if held < MAX_HOLDINGS:
            return False  # COLD 양보로 막힌 칸은 확장 경로로 우회할 수 없음
        return self._can_use_expansion_slot(info, sub_strategy)

    def _can_use_expansion_slot(
        self, info: dict | None, sub_strategy: str | None = None
    ) -> bool:
        """확장 슬롯(7~8번째) 사용 자격 판정 (2026-07-31 사용자 지정).

        "평소 6개만 쓰되, 정말 좋은 종목이 포착됐는데 슬롯교체가 애매하면
        남은 슬롯을 쓴다"는 요구를 세 조건으로 구현한다:
          ① 점수가 자기 컷라인의 SLOT_EXPANSION_SCORE_MARGIN배 이상 — 전략마다
             만점 스케일이 달라(1A 12점 / Pullback 7점) 절대값 대신 컷라인 대비
             비율로 판정해야 전략 간 형평이 맞는다.
          ② 슬롯이 꽉 찬 상태가 SLOT_EXPANSION_WAIT_SEC 이상 지속 — 슬롯교체
             태스크가 60초 주기로 돌므로, 이 시간을 넘겼다는 건 교체할 만한
             정체 종목이 없었다는 뜻("슬롯교체가 애매한 경우")이다.
          ③ 점수 정보가 없는 경로(1B/1L 등 실시간 틱 진입)는 확장 대상 아님 —
             비교 기준이 없어 '정말 좋은 종목'을 판정할 수 없기 때문.
        """
        if not info:
            return False
        score = info.get("score")
        thr = info.get("score_threshold")
        if not score or not thr or thr <= 0:
            return False
        # 오늘 성과가 좋은(HOT) 전략은 마진을 완화해 확장 슬롯을 더 쉽게 쓴다
        # (2026-07-31) — 우선순위를 슬롯 개수가 아니라 '문턱'으로 주는 방식.
        margin = SLOT_EXPANSION_SCORE_MARGIN
        if sub_strategy:
            margin = self.perf.expansion_margin(sub_strategy, margin)
        if score < thr * margin:
            return False
        since = self._soft_cap_full_since
        if since is None:
            return False
        if (self._now() - since).total_seconds() < SLOT_EXPANSION_WAIT_SEC:
            return False
        logger.info(
            "확장 슬롯 사용 (보유 %d/%d -> 상한 %d, 전략 %s/%s): 점수 %.1f >= "
            "컷라인 %.1f x%.2f, 슬롯 만석 %.0f초 지속(교체 대상 없음)",
            len(self.holdings), MAX_HOLDINGS, MAX_HOLDINGS_HARD,
            sub_strategy or "?", self.perf.tier(sub_strategy) if sub_strategy else "-",
            score, thr, margin,
            (self._now() - since).total_seconds(),
        )
        return True

    def may_expand_slots(self) -> bool:
        """확장 슬롯이 열려있을 가능성이 있는 상태인지 (점수 무관, 값싼 사전확인).
        watchlist_reentry처럼 '슬롯 여유 없으면 REST 호출도 안 함'으로 조기
        반환하는 경로가, 확장 가능한 상황까지 싸잡아 막아버리지 않도록 하는 용도.
        실제 허용 여부는 후보별 점수를 보는 _can_use_expansion_slot이 결정한다."""
        held = self.occupied_slots()
        if held < MAX_HOLDINGS or held >= MAX_HOLDINGS_HARD:
            return False
        since = self._soft_cap_full_since
        if since is None:
            return False
        return (self._now() - since).total_seconds() >= SLOT_EXPANSION_WAIT_SEC

    def _track_soft_cap_full(self, now):
        """평상시 상한(6개)이 언제부터 꽉 차 있었는지 추적 — 확장 슬롯 판정용.
        tick()에서 주기 호출. 슬롯이 하나라도 비면 타이머를 리셋해서, 확장은
        '오래 만석이었다'가 확인된 경우에만 열린다."""
        if len(self.holdings) >= MAX_HOLDINGS:
            if self._soft_cap_full_since is None:
                self._soft_cap_full_since = now
        else:
            self._soft_cap_full_since = None

    def occupied_slots(self) -> int:
        """보유 + 매수 진행중(pending) 합계 — 오버부킹 방지 (2026-08-01).

        기존엔 len(self.holdings)만 셌다. 그런데 _execute_buy는 주문 REST가
        끝나야 holdings에 넣는데, 그 사이(429 재시도 시 2초 blocking sleep까지
        포함) 종목은 pending에만 있다. on_condition_hit과 watchlist_reentry는
        각각 별도의 asyncio.to_thread에서 도므로, 급등이 동시에 여러 종목에서
        터지면 두 스레드가 같은 '마지막 한 칸'을 동시에 통과해 상한을 넘겨
        매수할 수 있다 — 여러 종목이 한꺼번에 터지는 상황이 바로 우선순위가
        필요한 상황이라, 순위 로직을 넣기 전에 이것부터 막아야 한다.

        (2026-08-04) 되돌림 대기 중인 종목(_entry_plans)도 센다. 대기는 최대
        ENTRY_PULLBACK_TIMEOUT_SEC(120초)이고 그 동안 자리를 비워두면 되돌림이
        왔을 때 살 슬롯이 없다.
        """
        return len(set(self.holdings) | self.pending | set(self._entry_plans))

    def count_holdings_by_strategy(self, sub: str) -> int:
        """해당 전략의 점유 슬롯 수 (보유 + 매수 진행중).

        (2026-08-01) pending 매수분도 센다 — 위 occupied_slots와 같은 이유.
        _pending_strategy는 _execute_buy가 주문 직전에 기록하고 finally에서 지운다.
        """
        n = sum(1 for h in self.holdings.values() if h.get("sub_strategy") == sub)
        n += sum(
            1 for code, s in self._pending_strategy.items()
            if s == sub and code not in self.holdings
        )
        return n

    def phase1a_max_slots(self) -> int:
        """1A 전략별 슬롯 상한. (2026-08-01) Pullback 창이 15:10까지 늘어나
        '노는 슬롯' 전제가 사라져 시간대별 상향은 폐지하고 상수 하나로 통일했다.
        호출부 호환을 위해 메서드는 유지 — 나중에 다시 시간대별로 바꾸고 싶으면
        여기만 고치면 된다."""
        return PHASE1A_MAX_SLOTS

    def can_buy_phase1a(self, info: dict | None = None) -> bool:
        # 1A: 09:00~14:50 (evaluate_1a_leading_strength, 체결강도 단독)
        return (
            self.can_buy_more(info, "1A")
            and self.count_holdings_by_strategy("1A") < self.phase1a_max_slots()
            and GROUP_A_START <= self._now().time() < PHASE1A_END
        )

    def can_buy_pullback(self, info: dict | None = None) -> bool:
        # 눌림목: 09:00~14:50 (PULLBACK_START/END 참고). 1A와 시간창이 같지만
        # 슬롯은 별도(sub_strategy="1A_눌림"), 조건검색식 소스도 완전히 분리.
        return (
            self.can_buy_more(info, "1A_눌림")
            and self.count_holdings_by_strategy("1A_눌림") < PULLBACK_MAX_SLOTS
            and PULLBACK_START <= self._now().time() < PULLBACK_END
        )

    # ========================================
    # 진입 진단 (2026-08-01 신규)
    # ========================================
    # 사유 원문 -> 분류. 앞에서부터 먼저 걸리는 것을 쓴다.
    # (분류, 원문에 포함된 문자열들)
    _REJECT_RULES = (
        ("대량체결 부족", ("대량체결 부족",)),
        # (2026-08-02) check_burst의 예외 핸들러가 내는 사유.
        # 이건 '시장에 신호가 없다'가 아니라 **우리 코드가 터졌다**는 뜻이라
        # 반드시 분류해서 인프라 경고로 올린다. 규칙이 없으면 "기타"로 뭉개져,
        # 버스트 계산이 통째로 실패해도 진단 알림에는 아무것도 안 보인다
        # (틱 구동 진입의 발사 조건이 죽는 것이므로 매수가 0건이 된다).
        ("버스트 계산 실패(코드 이상)", ("버스트 계산 실패",)),
        ("체결틱 부족(강도판단불가)", ("체결틱 부족",)),
        # (2026-08-02) 틱 구동 진입의 1단계 — 강도 100이 요구시간
        # (TICK_STRENGTH_SUSTAIN_SEC)을 못 채운 상태.
        # 이게 대부분이면 '코드 정상, 신호가 아직 안 옴'이라는 뜻이다.
        # 여기 없으면 "기타"로 뭉개져 장중에 원인 판단이 불가능하다.
        # ⚠️ 라벨에 초 수를 박지 말 것 — 상수를 바꿔도 안 따라와서 진단 알림이
        #    거짓말을 하게 된다(실제로 3.0->1.5초 변경 때 "3초 미달"로 남았다).
        ("강도 미무장(요구시간 미달)", ("미무장",)),
        # (2026-08-04) 되돌림 대기 진입의 미체결 — 트리거는 걸렸는데 대기 시간
        # 안에 목표 되돌림이 안 왔다는 뜻이다. '신호가 없다'와 전혀 다른 상태라
        # 반드시 분리해야 한다: 이게 많으면 되돌림 폭이 과하거나 대기가 짧다는
        # 신호이므로 ENTRY_PULLBACK_TRANCHES/TIMEOUT을 조정할 근거가 된다.
        # ⚠️ 라벨에 수치를 박지 말 것(상수를 바꿔도 안 따라온다).
        ("되돌림 미도달(대기 만료)", ("되돌림 미도달",)),
        ("체결강도 미달", ("체결강도 미달", "체결강도 지속 미달")),
        ("시가급등 보류", ("시가대비",)),
        ("저유동성 보류", ("저유동성",)),
        ("지수 방어(HALT)", ("전면 매매 중단",)),
        # (2026-08-03) 지수 하락 가드(INDEX_GUARD_THRESHOLD, 11:00~). 이게
        # 대부분이면 "코드 정상, 지수가 나빠서 일부러 안 산다"는 뜻이다 —
        # 규칙이 없으면 "기타"로 뭉개져 매수 0건의 원인을 판단할 수 없다.
        # (라벨에 % 수치를 박지 않는다 — 상수를 -3 -> -5로 바꿔도 안 따라온다.)
        ("지수 하락 가드", ("지수 하락 가드",)),
        # (2026-08-04) 슬롯과 무관한 전면 차단 — _entry_block_reason 참고.
        ("MDD 일손실 차단", ("MDD 일손실 차단",)),
        ("WS 재연결 격리", ("WS 재연결 격리",)),
        ("데이터소스 없음", ("데이터 소스 없음",)),
        ("눌림 미충족", ("눌림 미성립", "반등 미확인")),
        ("VWAP 탈락", ("VWAP",)),
        ("점수 미달", ("점수 부족", "점수 미달")),
        ("슬롯 부족", ("슬롯 부족",)),
        ("재매수 차단", ("재매수", "쿨다운", "매도 차단", "손절 종목")),
        # [제거됨] ("조건식 지연(09:20)", ("조건식 지연",)) —
        # 조건검색식별 09:20 지연 게이트는 2026-08-01에 폐지됐다(OTHER_COND_START
        # 상수째 삭제). 이 사유 문자열은 더 이상 생성되지 않으므로 규칙도 뺀다.
        ("장시작 전 대기", ("장 시작 전",)),
        # (2026-08-05) 등락률 상한은 아래 "매수 컷오프"(15:10 하드컷오프 등)와
        # 성격이 완전히 다르므로 반드시 먼저 잡아 분리한다. 08-05 실측에서
        # 10:30 이후 탈락의 대부분이 이것이었다(2,222회, 대한광통신 2,110회).
        # 뭉뚱그리면 "왜 안 사는가"의 답이 통째로 사라진다.
        ("등락률 상한 초과", ("등락률 상한",)),
        ("매수 컷오프", ("컷오프", "상한",)),
    )
    # '코드/인프라 이상'을 의심해야 하는 분류 — 정상 필터링과 구분해서 경고한다.
    _REJECT_INFRA = (
        "체결틱 부족(강도판단불가)",
        "데이터소스 없음",
        "버스트 계산 실패(코드 이상)",   # (2026-08-02 추가)
    )

    @classmethod
    def _reject_category(cls, reason: str) -> str:
        r = reason or ""
        for label, keys in cls._REJECT_RULES:
            if any(k in r for k in keys):
                return label
        return "기타"

    def _note_reject(self, stock_code: str, reason: str):
        """후보가 이번 평가에서 매수되지 않은 사유를 기록 (진단 전용).

        핫패스에서 불리므로 문자열 분류 외에 아무 것도 하지 않는다. 락도 걸지
        않는다 — 여러 워커 스레드가 동시에 써도 dict 대입은 원자적이고,
        진단용 근사치라 정확도보다 오버헤드 0이 중요하다.
        """
        if not stock_code or not reason:
            return
        try:
            self._last_reject[stock_code] = (
                self._reject_category(reason), str(reason)[:120], self._now()
            )
        except Exception:
            pass

    # 놓친 기회 계층 — 위일수록 '아까운' 것. (표시라벨, 분류키, 설명)
    _MISS_TIERS = (
        ("🥇", "되돌림 미도달(대기 만료)", "신호 완벽, 가격만 안 옴"),
        ("🥈", "대량체결 부족", "무장 완료, 대금 미달"),
        ("🥉", "강도 미무장(요구시간 미달)", "강도 유지중, 시간 미달"),
        ("⛔", "등락률 상한 초과", "참고만 — 실측 성과 부진"),
    )

    def build_missed_opportunities(self, top_n: int = 3) -> str:
        """'놓친 기회' 알림 (2026-08-05 신규). main.task_missed_opportunities가 호출.

        기존 build_entry_diagnostics가 **사유별 종목 수**를 보여준다면, 이건
        **어떤 종목이 얼마나 아깝게 놓쳤는지**를 보여준다. 수동 판단용이다.

        계층이 핵심이다 — 08-05 실측에서 '등락률 상한 초과'가 탈락의 대부분
        (2,222회, 대한광통신 혼자 2,110회)이었는데 그건 아까운 게 아니라
        **의도적 배제**였고, 실제로 사봤자 6건 중 익절4/손절2였다. 반면
        '되돌림 미도달'은 무장·버스트·등락률을 전부 통과한 완벽한 신호라
        성격이 완전히 다르다. 이걸 한 덩어리로 보여주면 판단이 불가능하다.
        """
        now = self._now()
        lines = [f"🎯 놓친 기회 ({now.strftime('%H:%M')})"]
        buckets = {label: [] for _, label, _ in self._MISS_TIERS}
        for code, rec in list(self._last_reject.items()):
            try:
                cat, reason, ts = rec
            except Exception:
                continue
            if cat not in buckets:
                continue
            if (now - ts).total_seconds() > 600:   # 최근 10분만
                continue
            buckets[cat].append((code, reason, ts))

        any_shown = False
        for mark, label, desc in self._MISS_TIERS:
            items = sorted(buckets.get(label, []), key=lambda x: x[2], reverse=True)
            if not items:
                continue
            any_shown = True
            lines.append(f"\n{mark} {label} — {desc}")
            for code, reason, ts in items[:top_n]:
                name = self._stock_names.get(code, code)
                px = 0
                try:
                    px = self._fresh_tick_price(code, max_age_sec=120) or 0
                except Exception:
                    px = 0
                px_s = f"{px:,.0f}원" if px else "-"
                lines.append(f"  {name}({code}) {px_s} · {ts.strftime('%H:%M')}")
                lines.append(f"    {reason}")
        if not any_shown:
            lines.append("\n최근 10분간 아깝게 놓친 후보 없음")
        return "\n".join(lines)

    def build_entry_diagnostics(self) -> str:
        """장중 진입 진단 요약 (텔레그램용). main.task_entry_diagnostics가 호출.

        "조건검색엔 계속 잡히는데 왜 안 사는가"를 세 가지로 나눠 보여준다:
          1) 슬롯/시간 같은 구조적 이유인가
          2) 진입 필터가 정상적으로 거르는 중인가 (사유별 종목 수)
          3) 데이터가 안 들어와서 판단 자체를 못 하는가 (=코드/구독 이상 의심)
        """
        now = self._now()
        held = len(self.holdings)
        n_1a = self.count_holdings_by_strategy("1A")
        n_pb = self.count_holdings_by_strategy("1A_눌림")
        cands = [c for c in self.watch_list_today
                 if c not in self.holdings and c not in self.pending]

        lines = [
            f"📊 [진입 진단] {now.strftime('%H:%M')}",
            f"후보 {len(cands)}종목 | 보유 {held}/{MAX_HOLDINGS} "
            f"(1A {n_1a}/{self.phase1a_max_slots()}, 눌림 {n_pb}/{PULLBACK_MAX_SLOTS})",
        ]

        # 1) 매수 가능 여부 자체
        # ⚠️ (2026-08-04) 전면 차단 사유는 반드시 _entry_block_reason()에서 가져온다.
        # 예전엔 여기서 MDD/HALT/격리를 따로 나열했는데 **지수 하락 가드가 빠져
        # 있어서**, 가드로 하루 종일 못 사는 날에도 보유 0/6인 채로
        # "🔒 1A 슬롯 없음"이라고 표시됐다(원인을 정반대로 안내). 같은 규칙을
        # 여러 곳에 복제하면 반드시 한 곳이 뒤처진다 — 단일 출처로 통일한다.
        gates = []
        blocked = self._entry_block_reason()
        if blocked:
            gates.append(blocked.split(" —")[0])
        if now.time() >= ENTRY_HARD_CUTOFF:
            gates.append(f"{ENTRY_HARD_CUTOFF.strftime('%H:%M')} 하드컷오프")
        if gates:
            lines.append(f"⛔ 전면 차단: {', '.join(gates)}")
        elif not self.can_buy_phase1a():
            lines.append("🔒 1A 슬롯 없음 (슬롯이 비면 자동 재평가)")
        else:
            lines.append("🟢 1A 슬롯 여유 있음 — 트리거 대기 중")

        # 1-2) 틱 구동 단계별 통과 수 (2026-08-02 신규)
        # 진입이 [체결틱 -> 무장(강도3초) -> 버스트 -> 매수] 4단이므로,
        # 어느 단계에서 끊기는지 숫자 하나로 보이게 한다. 이게 없으면
        # "왜 안 사지"를 로그를 뒤져가며 추측해야 한다.
        st = self._tick_entry_stats
        lines.append(
            f"⚡ 틱 {self._trade_tick_total:,} → 무장 {st['armed']} "
            f"→ 버스트 {st['burst_ok']} → 매수 {st['bought']}"
        )

        # 2) 사유별 집계 (최근 10분 내 기록만 — 오래된 건 이미 상황이 바뀜)
        recent, counts = 0, {}
        for code in cands:
            rec = self._last_reject.get(code)
            if not rec:
                continue
            cat, _, ts = rec
            if (now - ts).total_seconds() > 600:
                continue
            recent += 1
            counts[cat] = counts.get(cat, 0) + 1
        if counts:
            lines.append("미체결 사유(최근 10분):")
            for cat, n in sorted(counts.items(), key=lambda kv: -kv[1])[:6]:
                lines.append(f"  {n:>3}종목  {cat}")
        elif cands:
            lines.append("⚠️ 후보는 있는데 최근 10분간 평가 기록이 없음 "
                         "— 재평가 루프 정지 의심")

        # 3) 인프라 이상 신호
        warns = []

        # 3-0) FID 228 미수신 — 이번 개편에서 **유일하게 실거래 미검증인 가정**.
        # 무장이 228 하나에 걸려 있어서, 이게 안 오면 매수가 구조적으로 0건이
        # 된다. "0B 자체가 안 옴"과 "0B는 오는데 228만 빔"을 구분해서 알린다 —
        # 전자는 WS 구독 문제, 후자는 FID 파싱/필드 문제로 대응이 완전히 다르다.
        if self._trade_tick_total == 0:
            if now.time() >= time(9, 3):
                warns.append(
                    "체결틱(0B) 자체가 0건 — WS 실시간 구독 확인 필요"
                )
        elif not self._fid228_seen:
            warns.append(
                f"🚨 체결틱 {self._trade_tick_total:,}건은 오는데 "
                f"**체결강도(FID 228)가 한 번도 안 옴** — 무장이 영구 불가라 "
                f"매수 0건이 됩니다. api/kiwoom_ws.py의 '228' 파싱과 "
                f"'🔑 0B 체결 raw 키' 로그를 확인하세요."
            )

        infra_n = sum(n for c, n in counts.items() if c in self._REJECT_INFRA)
        if infra_n:
            warns.append(f"체결 데이터 없음 {infra_n}종목 (0B 구독/WS 확인)")

        if self.phase1b and getattr(self.phase1b, "trade_flow", None):
            silent = [c for c in cands
                      if self.phase1b.is_watching(c)
                      and self.phase1b.trade_flow.tick_count(c, 120) == 0]
            if silent:
                warns.append(
                    f"감시중인데 체결틱 0인 종목 {len(silent)}개: "
                    f"{', '.join(silent[:5])}{'...' if len(silent) > 5 else ''}"
                )
            unwatched = [c for c in cands if not self.phase1b.is_watching(c)]
            if unwatched:
                warns.append(
                    f"후보인데 감시 미시작 {len(unwatched)}개 "
                    f"(1A 평가에 도달 못 함): {', '.join(unwatched[:5])}"
                    f"{'...' if len(unwatched) > 5 else ''}"
                )

        # 슬롯이 비어있는데 오래 매수가 없으면 파이프라인 이상 의심
        if not gates and self.can_buy_phase1a() and cands:
            since = self._last_buy_at
            idle_min = (now - since).total_seconds() / 60 if since else None
            if since is None and now.time() >= time(9, 30):
                warns.append("오늘 매수 0건 — 진입 경로 전체 점검 필요")
            elif idle_min is not None and idle_min >= 60:
                warns.append(f"슬롯 여유 상태로 {idle_min:.0f}분째 매수 없음")

        for w in warns:
            lines.append(f"⚠️ {w}")

        # 4) 성과 기반 문턱 조정 현황 (제안 B 효과 가시화)
        tiers = []
        for key in ("1A", "1A_눌림"):
            t = self.perf.tier(key)
            if t != "NEUTRAL":
                tiers.append(f"{key}={t}")
        for name in ("주도주상위", "돌파자동매매용", "눌림목자동"):
            t = self.perf.tier(COND_PERF_PREFIX + name)
            if t != "NEUTRAL":
                tiers.append(f"{name}={t}")
        if tiers:
            lines.append(f"성과 등급: {', '.join(tiers)}")

        return "\n".join(lines)

    def candidate_tier(self, stock_code: str) -> float:
        """종목 우선순위 지표 (2026-08-01 신규). 클수록 좋은 자리.

        tier = 거래대금 가속도 x 체결강도배수
          - 거래대금 가속도: 최근 30초 거래대금 / (최근 120초 평균 30초분).
            1.0 = 균일, 3.0 = 지금 3배로 몰리는 중.
          - 체결강도배수: 최근 30초 강도 / 100. 매수 우세면 1 초과.

        **두 항 모두 그 종목 자신의 최근 이력 대비 비율**이라는 게 핵심이다.
        절대 거래대금으로 줄을 세우면 대형주(돌파자동매매용)가 항상 이기고,
        조건검색이 굳이 찾아준 소형 급등주(주도주상위)는 영영 슬롯을 못 잡는다.
        자기 대비로 재면 두 조건검색식의 종목이 같은 잣대에서 비교되므로
        **조건검색식별 우선순위라는 개념 자체가 필요 없어진다.**

        비용: 이미 메모리에 있는 틱 버퍼만 읽는다 — REST 0콜, 대기 0초.
        그래서 매수 트리거 시점에 호출해도 진입이 단 1ms도 늦지 않는다.

        반환 0.0 = 판단 불가(틱 부족). 호출부는 이 경우 **남의 슬롯을 빼앗는
        것만 포기**하고, 빈 슬롯 매수는 정상 진행한다 — '모름'이 매수를
        막아버리면 우선순위를 도입한 대가로 매매를 잃는 셈이 된다.
        """
        if not (self.phase1b and getattr(self.phase1b, "trade_flow", None)):
            return 0.0
        tf = self.phase1b.trade_flow
        try:
            if tf.tick_count(stock_code, PHASE1A_TIER_LONG_SEC) < PHASE1A_TIER_MIN_TICKS:
                return 0.0
            accel = tf.value_acceleration(
                stock_code, PHASE1A_TIER_SHORT_SEC, PHASE1A_TIER_LONG_SEC
            )
            if accel <= 0:
                return 0.0
            strength = tf.compute_strength(
                stock_code, PHASE1A_TIER_SHORT_SEC, min_ticks=PHASE1A_TIER_MIN_TICKS
            )
            if strength <= 0:
                return 0.0
            # [제안 A] 신호 세기 가중 — 단일 대량체결이 터진 자리를 우대한다.
            max_single = tf.max_single_trade_value(stock_code, PHASE1A_TIER_SHORT_SEC)
            if max_single >= PHASE1A_SINGLE_TRADE_VALUE:
                signal_mult = PHASE1A_TIER_SINGLE_MULT
            elif max_single >= PHASE1A_BURST_TRADE_VALUE:
                signal_mult = PHASE1A_TIER_BURST_MULT
            else:
                signal_mult = 1.0
            return accel * (strength / 100.0) * signal_mult
        except Exception:
            logger.exception("[%s] tier 계산 실패 -> 판단 불가(0)", stock_code)
            return 0.0

    def _try_1a_priority_upgrade(self, candidate_code: str, candidate_tier: float) -> bool:
        """슬롯이 꽉 찬 순간에만 도는 '종목 우선순위' 교체 (2026-08-01 전면 재설계).

        설계 의도 — 조건검색식 우선순위가 아니라 **종목 우선순위**를, 그것도
        **진입 지연 0으로** 구현한다. 핵심은 세 가지다:

        ① 이 함수는 슬롯이 꽉 찼을 때만 호출된다. 실측상 슬롯 사용률이 10%라
           대부분의 트리거는 여기 오지도 않고 곧장 매수된다 — 급등 포착 속도가
           우선순위 도입 때문에 느려지는 일은 구조적으로 없다.
        ② 후보를 모아 정렬하지 않는다. tier는 이미 틱 버퍼에 계산 재료가 다
           들어있어 조회만 하면 되므로(REST 0콜), 호출돼도 즉시 끝난다.
        ③ 비교 기준이 **자기 대비 비율**(candidate_tier)이라 소형 급등주와
           대형주가 공평하게 겨룬다.

        안전장치:
          - 교체 대상은 "아직 결과가 안 난 자리"(순손익 ±PHASE1A_PRIORITY_FLAT_BAND)
            로 제한 — 오르고 있는 포지션을 순간 스파이크로 빼앗지 않는다.
          - tier를 모르는(0.0) 후보는 교체를 시도하지 않는다.
          - 최소보유 시간 미달 포지션은 제외(사자마자 되파는 수수료 낭비 방지).
        기존 09:00~09:10 제한은 해제했다 — 슬롯 만석 자체가 이미 강한 게이트라
        시간으로 또 막을 이유가 없고, 오히려 10:30 이후 좋은 자리를 놓쳤다.

        반환 True = 자리를 하나 비웠음(호출부가 can_buy_phase1a를 재확인해 매수).
        """
        if candidate_tier <= 0:
            return False
        # (2026-08-04) 자리를 비워도 살 수 없는 상태면 **아무것도 팔지 않는다.**
        # 호출부는 can_buy_*가 False라는 것만 보고 이 함수를 부르는데, 그
        # False가 슬롯이 아니라 지수 가드/MDD/HALT/WS격리 때문일 수 있다.
        # 그 경우 여기서 팔면 매도만 일어나고 대체 매수는 막혀 있어 손실만
        # 확정된다(08-03에 slot_replacement에서 고친 것과 같은 결함).
        blocked = self._entry_block_reason()
        if blocked:
            logger.debug("[%s] 우선순위 교체 보류 — %s", candidate_code, blocked)
            return False
        now_dt = self._now()
        if not (GROUP_A_START <= now_dt.time() < PHASE1A_END):
            return False

        best_code, best_tier, best_price = None, None, None
        for code, pos in self.holdings.items():
            if pos.get("sub_strategy") != "1A":
                continue
            if code in self.pending or code in self.sell_blocked:
                continue
            buy_time = pos.get("buy_time")
            if buy_time is None:
                continue
            if (now_dt - buy_time).total_seconds() < PHASE1A_PRIORITY_MIN_HOLD_SEC:
                continue

            # 결과가 이미 난 자리(오르거나 밀린 자리)는 건드리지 않는다.
            price = self._fresh_tick_price(code)
            if not price:
                continue  # 실시간가를 모르면 판단 보류 (REST까지 쓰진 않는다)
            if abs(self._net_rate(pos.get("buy_price") or 0, price)) > PHASE1A_PRIORITY_FLAT_BAND:
                continue

            tier = self.candidate_tier(code)
            if best_tier is None or tier < best_tier:
                best_code, best_tier, best_price = code, tier, price

        if best_code is None:
            return False
        if candidate_tier < max(best_tier, 0.0) * PHASE1A_PRIORITY_MARGIN:
            return False

        logger.info(
            "[%s] 1A 종목 우선순위 교체 — 후보 tier %.2f >= 최약보유 %s tier %.2f x%.1f "
            "(정체 구간이라 교체 가능) -> 매도 후 신규매수 시도",
            candidate_code, candidate_tier, best_code, best_tier,
            PHASE1A_PRIORITY_MARGIN,
        )
        self._execute_sell(
            best_code, best_price,
            f"1A 우선순위 교체 (후보 {candidate_code} tier {candidate_tier:.2f} "
            f">= 보유 tier {best_tier:.2f} x{PHASE1A_PRIORITY_MARGIN:.1f})",
        )
        return True

    # [2026-08-02 제거] can_buy_phase1b / can_buy_leading — 1B/1L 전략 삭제.

    # ========================================
    # 쿨다운 / 차단
    # ========================================
    def _is_rebuy_blocked(self, stock_code: str) -> tuple[bool, str]:
        if stock_code in self.sell_blocked:
            return True, "매도 차단 (영구실패)"
        if stock_code in self._stoploss_blocked:
            return True, "손절 종목 당일 재매수 금지"
        cnt = self._buy_count_today.get(stock_code, 0)
        if cnt >= MAX_BUYS_PER_STOCK:
            return True, (
                f"재매수 상한 초과 (당일 {cnt}회 매수 = 최초 1회 + 재매수 "
                f"{MAX_BUYS_PER_STOCK - 1}회 소진)"
            )
        if stock_code in self.sold_at:
            elapsed = self._now() - self.sold_at[stock_code]
            if elapsed < REBUY_COOLDOWN:
                remaining = REBUY_COOLDOWN - elapsed
                return True, f"쿨다운 (잔여 {int(remaining.total_seconds())}초)"
        return False, ""

    # ========================================
    # 진입
    # ========================================
    def on_condition_hit(
        self,
        stock_code: str,
        stock_name: str,
        is_surge: bool = False,
        cond_name: str = "알수없음",
    ):
        # [추가] 신호가 들어왔을 때 조건명(cond_name)을 포함해 로그 출력
        logger.info(f"📈 편입 신호: {stock_code} ({stock_name}) - 조건: {cond_name}")

        if stock_code in self.holdings or stock_code in self.pending:
            return

        # ⚠️ 기록(이름/조건명)은 시간 게이트보다 **먼저** 한다 (2026-08-01 수정).
        # 기존엔 get_current_phase()가 None이면(=09:00 이전) 여기 도달하기 전에
        # return 해서, 스케줄러를 08:59로 앞당긴 뒤로는 기동 스냅샷 종목이
        # 이름·조건명·워치리스트 어디에도 남지 않고 통째로 사라졌다.
        # 실시간 편입(type='02')까지 유실되고 있던 상태(kiwoom_ws 수정 전)라,
        # 08:59 기동 + 이 게이트 = 하루 종일 조건검색 종목 0건이 될 수 있었다.
        self._stock_names[stock_code] = stock_name
        # 이미 실제 조건명이 기록돼 있으면 "기타"/"알수없음" 같은 부실한 값으로
        # 덮어쓰지 않음 (2026-07-30). 실시간 WS 편입 이벤트(_on_signal)가 cond_seq를
        # 못 읽어 "기타"로 넘어오는 경우가 있는데, 이게 초기 스냅샷이 이미 정확히
        # 기록해둔 "주도주상위+..." 같은 값을 덮어써버리면 OTHER_COND_START(09:20)
        # 게이트가 주도주상위 종목까지 잘못 지연시킴 — 오늘 실전에서 이 때문에
        # SK이터닉스 등 9종목이 09:01~09:20 사이 18분간 평가 자체가 멈췄던 것 확인.
        # (2026-07-31) 돌파자동매매용처럼 "주도주상위"가 아닌 조건식이 먼저 걸린
        # 종목에 나중에 주도주상위 신호가 와도, 기존 first-write-wins 로직이라
        # cond_name이 영영 갱신 안 돼 09:20까지 잘못 지연됐음(주도주상위+돌파
        # 자동매매용 콜라보 사용 시작하며 발견) — "주도주상위"가 새로 포함되면
        # 예외적으로 승격시켜 병합한다.
        existing_cond = self._cond_names.get(stock_code)
        if not existing_cond or existing_cond in ("기타", "알수없음"):
            self._cond_names[stock_code] = cond_name
        elif cond_name and cond_name not in ("기타", "알수없음"):
            # (2026-08-02 수정) 예전엔 **주도주상위가 나중에 온 경우에만**
            # 병합했다. 그래서 주도주상위가 먼저 걸리고 눌림목자동이 나중에
            # 온 종목은 영영 "주도주상위" 단독으로 남아, 중복 편입 종목의
            # 10:30 전략 전환(DUAL_SOURCE_PULLBACK_FROM)이 절반만 작동했다.
            # 이제 방향과 무관하게 새 조건식이면 병합한다 — resolve_strategy가
            # 정확한 라우팅을 하려면 실제로 걸린 조건식이 **전부** 있어야 한다.
            parts = [p for p in existing_cond.split("+") if p]
            for part in cond_name.split("+"):
                if part and part not in parts:
                    parts.append(part)
            self._cond_names[stock_code] = "+".join(parts)

        # 거래대금 폭발 이력(explosion_scorer) 준비는 여기서 더 이상 안 함 —
        # 종가베팅 스캐너(main.py task_closing_bet_scanner, 14:50)에서만 쓰이는
        # 데이터인데 조건검색 걸릴 때마다(하루 수십 회) 미리 계산해두느라
        # REST 호출이 과다해지던 문제(429 다발)가 있어서, 실제 필요한 시점인
        # 14:50 스캔 때 그 시점 후보 종목들만 대상으로 계산하도록 이관함.
        # (2026-07-28: 조건검색에 N봉 신고가+거래량 필터를 사용자가 직접 추가해서
        # 1차 필터링이 이미 상류에서 되고 있는 것도 이관 결정의 근거)

        blocked, reason = self._is_rebuy_blocked(stock_code)
        if blocked:
            logger.info("[%s] %s 매수 차단: %s", stock_code, stock_name, reason)
            return

        try:
            now_t = self._now().time()

            # 장 시작 전(08:59 기동 등)에는 평가만 미루고 후보로는 남긴다
            # (2026-08-01). watch_list_today에 들어가면 09:00부터
            # task_watchlist_reentry(15초 주기)가 자동으로 재평가한다 —
            # '버리는' 게 아니라 '미루는' 것이 핵심.
            if now_t < GROUP_A_START:
                self.watch_list_today.add(stock_code)
                # ⚠️ 장 시작 전에도 **감시는 반드시 켠다** (2026-08-02 수정).
                # 예전엔 여기서 그냥 return 해서 08:59 기동 스냅샷 종목들이
                # 09:00 이후 첫 watchlist_reentry(15초 주기)가 돌 때까지
                # 체결틱을 한 개도 못 쌓았다. 무장(강도 연속 유지)은 틱이
                # 쌓여야 시작되므로, **개장 직후 가장 중요한 최대 15초**를
                # 통째로 날리는 구조였다(그 15초는 하루 중 거래가 가장
                # 폭발하는 구간이다). 매수는 여전히 09:00부터만 일어난다 —
                # 여기서 켜는 건 데이터 수집뿐이다.
                self.prearm_candidate(stock_code)
                self._note_reject(
                    stock_code,
                    f"장 시작 전 편입 — {GROUP_A_START.strftime('%H:%M')}부터 평가",
                )
                logger.info(
                    "[%s] %s 장 시작 전 편입 — %s부터 평가 대기 "
                    "(후보 등록 + 체결틱 수집 시작)",
                    stock_code, stock_name, GROUP_A_START.strftime("%H:%M"),
                )
                return
            # 1A(14:50)와 Pullback(15:10) 중 늦은 쪽까지는 평가를 계속한다
            # (2026-08-01) — PHASE1A_END로 끊으면 Pullback 마지막 20분이 죽는다.
            if now_t >= ENTRY_WINDOW_END:
                return

            # ⚠️ 감시 시작(pre-arm)을 분봉 조회보다 **먼저** 한다 (2026-08-02).
            # 예전엔 분봉이 15개 미만이면 여기서 return 해서, 그 종목은
            # 체결틱 수집조차 시작되지 않았다 — 즉 신규 상장주나 거래가
            # 뜸한 종목은 무장이 원천적으로 불가능했다. 틱 구동 진입은
            # 분봉이 전혀 필요 없으므로 분봉 실패가 진입을 막으면 안 된다.
            self.prearm_candidate(stock_code)

            candles = self._get_merged_candles(stock_code, interval=1, count=15)
            if not candles or len(candles) < VOLUME_LOOKBACK + 1:
                logger.warning(
                    "[%s] 분봉 부족 (%d개) — 시가 캐시만 생략하고 틱 경로는 계속",
                    stock_code, len(candles) if candles else 0
                )
                # 분봉이 없어도 실시간 체결가가 있으면 그대로 평가로 넘어간다.
                px = self._fresh_tick_price(stock_code)
                if not px:
                    return
                self._evaluate_1a_pullback_entry(
                    stock_code, stock_name, 1, None, int(px),
                    self._opening_prices.get(stock_code, 0.0), now_t
                )
                return

            current_price = int(candles[0].get("close", 0))
            # 당일 시가 — candles는 **내림차순**(최신->과거)이라 기존의
            # candles[-1]["open"]은 '가장 오래된 봉의 시가'였고, 개장 직후엔
            # API가 전일 봉까지 채워 주므로 실제로는 **전일 시가**였다
            # (07-30 로그 실측: 09:01 시점 candles[-1] = 20260729 15:09 봉).
            # 그 값으로 "시가대비 +5% 매수보류"를 재던 탓에 사실상
            # '전일종가 대비 +5%'가 되어 개장 초반 주도주가 전부 잘렸다.
            open_price = self._today_open(candles)
            if open_price > 0:
                self._opening_prices.setdefault(stock_code, open_price)

            self._evaluate_1a_pullback_entry(
                stock_code, stock_name, 1, candles, current_price, open_price, now_t
            )

        except Exception as e:
            logger.exception("[%s] on_condition_hit 실패: %s", stock_code, e)
            SystemEventRepository.log("STRATEGY_ERROR", f"{stock_code}: {e}", "ERROR")
            _notify(f"전략 에러\n{stock_code}: {e}")

    def _evaluate_1a_pullback_entry(
        self, stock_code, stock_name, phase, candles, current_price, open_price, now_t
    ) -> bool:
        # candles=None 허용 (2026-08-01) — 새 1A는 순수 틱 계산이라 분봉이
        # 전혀 필요 없다. 재평가 루프(watchlist_reentry, 15초 주기)가 후보마다
        # 분봉을 긁으면 429 예산이 그대로 녹는다(후보 40종목이면 한 사이클에
        # REST 40콜 = 자체 상한 분당 100콜의 절반 이상). Pullback 분기에
        # 도달했을 때만 지연 로딩한다.
        """1A + Pullback 평가/매수 시도 (슬롯 없으면 watch_list에만 기록).
        on_condition_hit(최초 편입 시점)과 watchlist_reentry(슬롯 재확보 시 재평가)
        양쪽에서 공유하는 로직 — 2026-07-28 분리(슬롯 꽉 찼을 때 1A/Pullback 후보가
        재평가 없이 영구히 방치되던 문제 수정, core/watchlist_reentry.py 참고).
        반환: 매수 실행했으면 True."""
        # watchlist_reentry 경로는 on_condition_hit과 달리 호출 전에 재매수 차단을
        # 확인하지 않아서, 손실차단/쿨다운 중인 종목이 슬롯 재확보 시 바로 재매수될
        # 수 있었음 — 공유 진입점인 여기서 한 번 더 확인. (2026-07-29)
        blocked, reason = self._is_rebuy_blocked(stock_code)
        if blocked:
            logger.info("[%s] %s 매수 차단: %s", stock_code, stock_name, reason)
            self._note_reject(stock_code, reason)
            return False

        # (2026-08-01) 조건검색식별 09:20 지연 게이트 제거 — 근거는
        # 위 OTHER_COND_START 자리의 주석 참고. 이제 모든 조건검색식이
        # 각자의 전략 시간창(1A 09:00~14:50 / Pullback 09:20~15:10)에서
        # 편입 즉시 평가된다.
        cond_name = self._cond_names.get(stock_code, "")

        # ── 전략 라우팅 (2026-08-01 사용자 지정) ────────────────────────
        # 한 종목은 언제나 **한 전략만** 평가한다(오락가락 방지).
        #   눌림목자동 단독      -> Pullback 전용
        #   주도주상위/돌파 단독 -> 1A 전용
        #   중복(둘 다)          -> 10:30 이전 1A / 이후 Pullback
        # 전제가 정반대인 두 검색식(눌림목자동=당일고가 되돌림 /
        # 주도주상위·돌파=상승 모멘텀)을 각자 맞는 전략에 연결하되, 둘 다에
        # 걸린 종목은 시간대에 따라 유리한 쪽(오전 모멘텀/오후 되돌림)이 갖는다.
        is_pullback_source = self.resolve_strategy(cond_name, now_t) == "1A_눌림"

        # ══════════════════════════════════════════════════════════════
        # 틱 구동 진입으로 전면 전환 (2026-08-02, 사용자 지정)
        # ══════════════════════════════════════════════════════════════
        # 1A와 Pullback이 **같은 트리거**를 쓴다: 체결강도(FID 228) 100 이상
        # 연속 유지(TICK_STRENGTH_SUSTAIN_SEC) + 대량체결 버스트. 차이는 유니버스에 이미
        # 들어있고, "지금 매수세가 실제로 들어오는가"라는 진입 순간의 판단은
        # 두 전략이 동일하기 때문이다. 전략별 차이는 이 함수 밖에서 유지된다 —
        # 슬롯/등락률 상한(1A 16% / 눌림 10%)/익절 캡/시간창.
        #
        # [Pullback의 분봉·점수·VWAP 경로를 걷어낸 이유]
        # 눌림 판정(3분봉 30이평 근접, 고점대비 -3%, 급등이력, 유동성 100억+)은
        # 전부 HTS 조건검색식이 이미 하고 넘겨준다. 코드가 1분봉으로 그걸 다시
        # 재검증하면 (a) 시간축이 안 맞아 실거래에서 26종목 전부 탈락했고
        # (b) 1분봉 종가를 기다리느라 구조적으로 최대 60초가 늦었다.
        # evaluate_pullback / _apply_vwap_filter / evaluate_1a_leading_strength는
        # 삭제하지 않고 그대로 둔다(호출부만 교체 — 되돌릴 수 있게).
        #
        # [이 시점에 매수가 되는 일은 드물다 — 정상이다]
        # 최초 편입 순간엔 체결틱이 아직 0개라 무장(강도 연속 유지)이 성립할 수 없다.
        # 여기서 하는 일의 본질은 **pre-arm**(감시 시작 + 캐시 예열)이고,
        # 실제 진입은 on_trade의 _maybe_tick_entry가 이어받는다. 이미 감시 중인
        # 종목이 재편입된 경우엔 틱이 쌓여 있으므로 여기서 바로 발화할 수 있다.
        sub_strategy = "1A_눌림" if is_pullback_source else "1A"
        in_window = (
            (PULLBACK_START <= now_t < PULLBACK_END) if is_pullback_source
            else (GROUP_A_START <= now_t < PHASE1A_END)
        )
        if not in_window:
            return False

        # pre-arm — 편입 즉시 '살 준비'를 끝내둔다(감시 시작 + 전일종가/시가
        # 캐시 예열). 트리거가 걸린 뒤에 준비하면 그만큼 늦게 산다.
        self.prearm_candidate(stock_code, current_price, candles)

        ok, info = self.evaluate_tick_entry(
            stock_code, sub_strategy, current_price,
            open_price=open_price or self._opening_prices.get(stock_code, 0.0),
            cond_name=cond_name, now_dt=self._now(),
        )
        self._record_watch_list(stock_code, stock_name, phase, info, cond_name)

        if not ok:
            self._note_reject(stock_code, info.get("reason", ""))
            return False

        # ── 종목 우선순위 (2026-08-01 설계 유지) ──────────────────────
        # 슬롯에 여유가 있으면 순위를 아예 보지 않고 즉시 매수한다(딜레이 0).
        # 꽉 찬 순간에만 tier를 조회해(메모리 연산, REST 0콜) 가장 약하면서
        # 아직 결과가 안 난 자리와 겨룬다.
        if sub_strategy == "1A":
            slots_full = (
                self.count_holdings_by_strategy("1A") >= self.phase1a_max_slots()
                or self.occupied_slots() >= MAX_HOLDINGS
            )
            if slots_full:
                self._try_1a_priority_upgrade(
                    stock_code, self.candidate_tier(stock_code)
                )
            can_buy = self.can_buy_phase1a(info)
            slot_msg = (
                f"슬롯 부족 (1A {self.count_holdings_by_strategy('1A')}"
                f"/{self.phase1a_max_slots()}, 전체 {self.occupied_slots()}/{MAX_HOLDINGS})"
            )
        else:
            can_buy = self.can_buy_pullback(info)
            slot_msg = (
                f"슬롯 부족 (눌림 {self.count_holdings_by_strategy('1A_눌림')}"
                f"/{PULLBACK_MAX_SLOTS}, 전체 {self.occupied_slots()}/{MAX_HOLDINGS})"
            )

        if not can_buy:
            # 슬롯이 아니라 전면 차단(지수 가드/MDD/HALT/격리)일 수 있다 —
            # 사유를 그대로 적어야 진단 알림이 원인을 구분한다 (2026-08-04).
            self._note_reject(stock_code, self._entry_block_reason() or slot_msg)
            return False

        # ── 되돌림 대기 계획이 살아 있으면 그쪽에 양보한다 (2026-08-04 수정) ──
        # 이 경로(on_condition_hit / watchlist_reentry 폴링)는 틱 경로와 별개로
        # 돌면서 _execute_buy를 직접 부른다. 되돌림 대기를 틱 경로에만 붙였더니
        # **계획이 열린 직후 이 폴링이 즉시 매수해버려 대기가 통째로 무력화**됐다.
        # 08-04 실거래로 확인: 036930은 트리거 133,100원에 계획(목표 132,434)을
        # 걸어놓고 46초 뒤 폴링이 133,600원에 샀다 — 기다린 것보다 **더 비싸게**
        # 산 것이고, 계획은 0/2 트랜치로 시간초과됐다. 004710도 동일 패턴.
        if stock_code in self._entry_plans:
            self._note_reject(stock_code, "되돌림 대기 중(계획 우선)")
            return False

        # 틱 경로가 아직 계획을 못 연 상태에서 여기로 먼저 들어올 수도 있다.
        # 그 경우에도 즉시 사지 않고 동일하게 대기 계획을 연다 — 진입 방식이
        # 경로에 따라 달라지면 사후 분석에서 원인 분리가 불가능해진다.
        if ENTRY_PULLBACK_ENABLED and ENTRY_PULLBACK_TRANCHES:
            px = info.get("current_price") or current_price
            if px and px > 0:
                self._open_entry_plan(
                    stock_code, stock_name, phase, info, sub_strategy,
                    self._cond_names.get(stock_code, ""), trigger_price=px,
                )
                return False

        self._execute_buy(stock_code, stock_name, phase, info, sub_strategy=sub_strategy)
        return True

    # ========================================
    # 실시간 콜백
    # ========================================
    def on_trade(self, parsed_trade: dict, now: float = None):
        code = parsed_trade.get("stock_code")
        if not code:
            return

        # FID 228 수신 감시 (2026-08-02) — 진입 로직 전체가 이 값에 걸려 있어서
        # "0B는 오는데 228만 비어있다"를 즉시 구분할 수 있어야 한다.
        # set.add는 amortized O(1)이라 핫패스 비용이 사실상 없다.
        self._trade_tick_total += 1
        _s = parsed_trade.get("strength")
        if _s:
            try:
                if float(_s) > 0:
                    self._fid228_seen.add(code)
            except (TypeError, ValueError):
                pass

        # ⚠️ 체결틱 적재는 **가장 먼저** 한다 (2026-08-01 수정).
        # 기존엔 보유 종목이면 on_price_update 후 곧바로 return 해서
        # trade_flow.add_tick까지 도달하지 못했다 — 그래서 매수하는 순간부터
        # 그 종목의 틱 버퍼가 얼어붙고, 10초만 지나면 compute_strength가
        # 중립값(100)만 반환했다. 그 결과 동적 익절캡 상향/조기확정,
        # 동적캡 즉시매도, 손실반등 하이브리드 매도가 전부 '판단 불가'로
        # 빠져 사실상 작동하지 않았다(07-31에 매수 직후 66초 안에만 발동한
        # 이유도 이것 — 매수 전에 쌓아둔 틱이 남아있던 구간뿐이었다).
        if self.phase1b and self.phase1b.is_watching(code):
            try:
                self.phase1b.trade_flow.add_tick(
                    code,
                    parsed_trade.get("price", 0),
                    parsed_trade.get("side", "neutral"),
                    parsed_trade.get("volume", 0),
                    now=now,
                )
            except Exception:
                logger.exception("[%s] 체결틱 적재 실패", code)

        if code in self.holdings:
            price = parsed_trade.get("price")
            if price:
                self.on_price_update(code, price)
            # 분할매수 2차가 남아 있으면 여기서 끝내면 안 된다 (2026-08-04).
            # 1차 트랜치가 체결되는 순간 종목은 holdings에 들어가는데, 그대로
            # return하면 더 깊은 되돌림이 와도 2차가 영영 체결되지 않는다.
            # (청산 판정은 위 on_price_update가 이미 수행했다.)
            if code in self._entry_plans:
                try:
                    self._try_fill_entry_plan(code, price, now=now)
                except Exception:
                    logger.exception("[%s] 분할매수 2차 처리 실패", code)
            return

        # ── 틱 구동 진입 평가 (2026-08-02 신설) ────────────────────────
        # 이 한 줄이 이번 개편의 핵심이다. 예전엔 진입 평가가 편입 시점 1회 +
        # 15초 주기 폴링(task_watchlist_reentry)뿐이라, "체결강도 100 이상
        # 3초 유지"라는 3초짜리 신호를 15초 간격으로 들여다보고 있었다
        # (평균 7.5초 지연, 짧게 스치는 신호는 아예 관측 불가).
        # 여기서 평가하면 조건이 차는 **그 틱에서** 발화한다 — 판정은 전부
        # 메모리 연산이라 REST 0콜이고, 대부분의 틱은 강도 타이머 갱신(O(1))
        # 후 즉시 반환된다.
        try:
            if self._maybe_tick_entry(code, parsed_trade, now=now):
                return
        except Exception:
            # 진입 평가 실패가 틱 처리 자체를 죽이면 안 된다(모든 종목의
            # 가격/강도 추적이 같이 멈춘다).
            logger.exception("[%s] 틱 진입 평가 예외", code)

        # [2026-08-02 제거] 1L 진입 블록 / 1B 하락 트리거 / _maybe_report_1l_diag.
        # 1L은 2026-07-31부터 `if False:`로, 1B는 2026-08-01부터
        # PHASE1B_ENABLED=False로 죽어 있었고 되살릴 계획이 없어 삭제했다.
        # on_trade는 이제 '틱 적재 -> 보유분 가격갱신 -> 틱 진입 평가'만 한다.
        # 복구가 필요하면 커밋 900757c 참고.

    def on_orderbook(self, parsed_orderbook: dict, now: float = None):
        """호가창(0D) 수신 — 매도 1~3호가 잔량을 최신 상태로 유지한다.

        (2026-08-01 재활성화) 07-31에 WallDetector(매도벽 FSM)를 걷어내면서
        이 콜백이 통째로 `return`이 되어 OrderbookTracker가 **한 번도 갱신되지
        않는** 상태였다. 이제 1A 하이브리드 주문(호가가 두툼하면 시장가, 텅
        비었으면 지정가)이 이 데이터를 쓰므로 다시 적재한다.
        — 적재만 한다. 진입 판정(WallDetector/FSM)은 여전히 하지 않는다:
          호가 잔량 이력은 어떤 공급자로도 과거 검증이 불가능하고
          (detect_multiplier 등은 도입 이후 한 번도 튜닝된 적 없는 placeholder),
          FSM 자체가 지연의 큰 축이었기 때문(413630 사례: FSM에서만 19분).
        """
        code = parsed_orderbook.get("stock_code")
        if not code:
            return
        if not (self.phase1b and getattr(self.phase1b, "orderbook", None)):
            return
        if not self.phase1b.is_watching(code):
            return
        try:
            self.phase1b.orderbook.update(code, parsed_orderbook, now=now)
        except Exception:
            logger.exception("[%s] 호가 적재 실패", code)


    # ========================================
    # 진입 평가 (점수 기반 — scoring.py 위임)
    # ========================================
    def evaluate_phase1(self, candles, stock_code):
        return score_phase1(
            candles,
            self._volume_ratio(candles),
            self._current_strength(stock_code),
            self.score_cfg,
        )

    # ==========================================
    # 지수 방어막 로직
    # ==========================================
    def _get_market_defense_mode(self) -> str:
        """
        지수 방어 모드 확인 (코스피+코스닥 중 더 나쁜 쪽 기준, worst-of-two)
        반환: "NORMAL" (-3% 이내), "CAUTION" (-3% ~ -5%), "HALT" (-5% 초과)
        모드가 바뀔 때만 텔레그램 알림 (매 호출마다 알리면 스팸이라 전환 시점에만).
        """
        if not MARKET_DEFENSE_ENABLED:
            return "NORMAL"

        self._refresh_market_rates()
        worst = min(self._kospi_rate, self._kosdaq_rate)

        if worst <= -5.0:
            mode = "HALT"
        elif worst <= -3.0:
            mode = "CAUTION"
        else:
            mode = "NORMAL"

        if mode != self._last_market_mode:
            rate_str = f"코스피 {self._kospi_rate:+.2f}% / 코스닥 {self._kosdaq_rate:+.2f}%"
            if mode == "HALT":
                logger.warning(f"🛑 마켓 크래시 발동! {rate_str} - 전면 매매 중단")
                _notify(f"🛑 지수 급락으로 신규매수 전면 차단\n{rate_str}\n(보유분 청산은 계속 작동)")
            elif mode == "CAUTION":
                logger.info(f"⚠️ 지수 경보 발동! {rate_str} - 강세 조건 강화")
                _notify(f"⚠️ 지수 경보 — 진입조건 강화\n{rate_str}")
            else:
                logger.info(f"✅ 지수 방어 모드 해제 (NORMAL 복귀) {rate_str}")
                _notify(f"✅ 지수 정상화 — 방어 모드 해제\n{rate_str}")
            self._last_market_mode = mode

        return mode

    def _is_severe_crash(self) -> bool:
        """지수(코스피/코스닥 중 더 나쁜 쪽)가 SEVERE_CRASH_THRESHOLD 이하로
        급락했는지 여부. MARKET_DEFENSE_ENABLED와 무관하게 항상 동작 — 별개의
        독립 안전장치(2026-07-28). 모드 전환 시에만 텔레그램 알림."""
        self._refresh_market_rates()
        worst = min(self._kospi_rate, self._kosdaq_rate)
        is_crash = worst <= SEVERE_CRASH_THRESHOLD

        if is_crash != self._last_severe_crash_state:
            rate_str = f"코스피 {self._kospi_rate:+.2f}% / 코스닥 {self._kosdaq_rate:+.2f}%"
            if is_crash:
                logger.warning(f"🔻 지수 급락 대응 모드 진입! {rate_str}")
                _notify(
                    f"🔻 지수 급락 대응 모드 진입\n{rate_str}\n"
                    f"익절 flat {SEVERE_CRASH_TAKE_PROFIT*100:.1f}%로 통일(트레일링 해제, 손절 -3% 유지)\n"
                    f"{SEVERE_CRASH_ENTRY_CUTOFF.strftime('%H:%M')} 이후 신규매수 중단 (보유분은 수동판단)"
                )
            else:
                logger.info(f"✅ 지수 급락 대응 모드 해제 {rate_str}")
                _notify(f"✅ 지수 정상화 — 급락 대응 모드 해제\n{rate_str}")
            self._last_severe_crash_state = is_crash

        return is_crash

    def _is_index_guard_active(self, now_dt: datetime = None) -> bool:
        """지수 하락 가드 발동 여부 (2026-08-03 신규, 사용자 지정).

        조건: **INDEX_GUARD_FROM(11:00) 이후**이고, 코스피/코스닥 중
        **하나라도** INDEX_GUARD_THRESHOLD 이하.

        ⚠️ 임계값은 2026-08-03 저녁에 -3% -> **-5%**로 조정돼 SEVERE_CRASH와
        정확히 같은 값이다(정합성 테스트로 못박아 둠). 둘은 같은 지수 수준에서
        동시에 켜지지만 하는 일이 다르다 — SEVERE_CRASH는 익절 캡을 1.5%로
        조이고, 이쪽은 신규매수 차단과 보유분 정리 시각을 정한다.
        한쪽 임계만 고치면 동작이 어긋나므로 반드시 같이 바꿀 것.

        지수 조회는 _refresh_market_rates()의 60초 캐시를 재사용하므로 REST
        추가 부담이 없다. 조회 실패 시 캐시된 직전 값이 쓰이고, 초기값은
        0.0이라 **데이터가 없으면 발동하지 않는다**(보수적 = 매매를 막지 않음).
        """
        if not INDEX_GUARD_ENABLED:
            return False
        now_dt = now_dt or self._now()
        if now_dt.time() < INDEX_GUARD_FROM:
            return False
        self._refresh_market_rates()
        worst = min(self._kospi_rate, self._kosdaq_rate)
        active = worst <= INDEX_GUARD_THRESHOLD

        if active != self._last_index_guard_state:
            rate_str = (
                f"코스피 {self._kospi_rate:+.2f}% / 코스닥 {self._kosdaq_rate:+.2f}%"
            )
            if active:
                logger.warning("🛡 지수 하락 가드 발동! %s", rate_str)
                _notify(
                    f"🛡 지수 하락 가드 발동 ({INDEX_GUARD_THRESHOLD:+.0f}% 이하)\n"
                    f"{rate_str}\n"
                    f"· 신규매수 즉시 중단\n"
                    f"· {INDEX_GUARD_BREAKEVEN_UNTIL.strftime('%H:%M')}까지 "
                    f"본전(순 0%) 이상인 보유분은 청산\n"
                    f"· 그때도 손실인 보유분은 "
                    f"{INDEX_GUARD_FORCE_CLOSE.strftime('%H:%M')} 강제청산"
                )
            else:
                logger.info("✅ 지수 하락 가드 해제 %s", rate_str)
                _notify(f"✅ 지수 회복 — 하락 가드 해제\n{rate_str}")
            self._last_index_guard_state = active

        return active

    # ════════════════════════════════════════════════════════════════
    # 틱 구동 진입 (2026-08-02 신설) — 무장(강도 N초 연속, N=TICK_STRENGTH_SUSTAIN_SEC) -> 발사(버스트)
    # ════════════════════════════════════════════════════════════════
    def burst_time_multiplier(self, now_dt: datetime = None) -> float:
        """현재 시각의 대량체결 임계값 계수. TICK_BURST_TIME_MULT 참고.

        장중 거래량 U자 곡선을 반영해 점심 구간의 절대 임계값을 낮춘다 —
        안 낮추면 오후가 통째로 죽는다(같은 3천만원도 시각에 따라 난이도가
        완전히 다르기 때문). 자기 정규화 경로(③)에는 적용하지 않는다.
        """
        now_t = (now_dt or self._now()).time()
        mult = TICK_BURST_TIME_MULT[0][1]
        for (hh, mm), m in TICK_BURST_TIME_MULT:
            if now_t >= time(hh, mm):
                mult = m
            else:
                break
        return mult

    def prearm_candidate(self, stock_code: str, current_price: float = 0.0,
                         candles: list = None) -> None:
        """편입 즉시 '살 준비'를 끝내둔다 (2026-08-02 신설, pre-arm).

        트리거가 걸린 뒤에 준비를 시작하면 그 준비 시간만큼 늦게 산다.
        버스트는 몇 초 만에 지나가므로 준비는 전부 미리 해둔다:

          ① 체결틱/호가 수집 시작(start_watching) — 이게 없으면 강도 타이머가
             아예 안 돌아 무장 자체가 불가능하다. 가장 중요하다.
          ② 전일종가 캐시 예열 — 등락률 상한(1A 16%/눌림 10%) 체크에 쓰이는데,
             캐시가 비어 있으면 **주문 직전에** REST(ka10001)를 부른다.
             하필 가장 급한 순간에 0.6초 스로틀 + 429면 2초 blocking이 붙는다.
          ③ 당일 시가 캐시 예열 — 1A "시가대비 +5% 매수보류" 판정용.
             틱 경로는 분봉을 받지 않으므로 여기서 안 채우면 그 필터가
             조용히 꺼진다.

        REST를 부르는 건 ②③뿐이고 둘 다 종목당 하루 1회다(값이 하루 불변).
        편입은 장중에 흩어져 발생하므로 이 호출이 429를 몰아치게 하지 않는다.
        어떤 실패도 밖으로 던지지 않는다 — 준비 실패가 감시 시작을 막으면 안 된다.
        """
        try:
            if self.phase1b and not self.phase1b.is_watching(stock_code):
                self.phase1b.start_watching(stock_code)
        except Exception:
            logger.exception("[%s] pre-arm 감시 시작 실패", stock_code)

        px = current_price or self._fresh_tick_price(stock_code) or 0
        if px and stock_code not in self._prev_closes:
            try:
                self._get_prev_close(stock_code, px)
            except Exception:
                logger.warning("[%s] pre-arm 전일종가 예열 실패", stock_code)

        if candles and stock_code not in self._opening_prices:
            try:
                op = self._today_open(candles)
                if op > 0:
                    self._opening_prices.setdefault(stock_code, op)
            except Exception:
                pass

    def update_strength_timer(
        self, stock_code: str, strength: float, now: float = None
    ) -> float:
        """키움 체결강도(FID 228)로 '연속 유지 시간'을 갱신하고 초를 반환.

        임계값 이상이면 최초 시각을 기록해두고, 한 번이라도 밑으로 떨어지면
        리셋한다 — 윈도우 평균이 아니라 **연속**이라 사용자 정의("100 이상
        3초 이상 유지")와 정확히 일치한다.

        strength가 0/None이면 '값 없음'으로 보고 타이머를 건드리지 않는다.
        228이 빈 값으로 오는 틱이 섞여도 무장이 억울하게 풀리지 않게 하기
        위함이다(리셋은 '실제로 100 밑으로 떨어진' 경우로 한정).
        """
        now = now if now is not None else _time_mod.time()
        if not strength or strength <= 0:
            return self._strength_sustained_sec(stock_code, now)
        if strength >= TICK_STRENGTH_MIN:
            if stock_code not in self._strength_since:
                self._strength_since[stock_code] = now
        else:
            self._strength_since.pop(stock_code, None)
            self._armed_at.pop(stock_code, None)
        return self._strength_sustained_sec(stock_code, now)

    def is_armed_now(self, stock_code: str, now: float = None) -> bool:
        """지금 이 종목이 **무장 상태**인가 — 버스트만 오면 즉시 매수될 자리인가.
        (2026-08-03 신규, 슬롯 교체의 대체후보 검증용)

        왜 필요한가: 슬롯 교체는 후보를 `_watch_scores`(과거 평가 시점에 저장된
        점수)로 고른다. 그런데 08-02에 진입이 **무장(FID228) + 버스트**로 바뀌면서
        "점수 높은 후보"가 더 이상 "지금 살 수 있는 종목"을 뜻하지 않게 됐다.
        08-03 실사례: 슬롯 교체 3건이 전부 950160을 근거로 팔았는데 그 종목은
        **하루 종일 한 번도 매수되지 않았다**(무장은 9회 했지만 버스트가 없었고,
        그 무장마저 11:06~11:23인데 교체는 12:00·12:02·13:07이라 시각도 안 겹쳤다).
        결과: 235,860원을 실현손실로 확정하고 자리는 그냥 비워뒀다.

        ⚠️ `_armed_at`에 키가 있는지만 보면 안 된다. 이 dict는 **그 종목의 다음
        틱이 들어와야** 만료 정리가 된다(_maybe_tick_entry의 TTL 분기). 즉 틱이
        끊기면 낡은 무장 기록이 그대로 남는다 — 08-02에 청산 후 강도 타이머가
        잔류해 무장 단계를 통째로 우회하던 사고와 같은 구조다. 그래서
        ① TTL 경과 여부와 ② **최근 틱이 실제로 들어오고 있는지**를 함께 본다.
        """
        if not TICK_ENTRY_ENABLED:
            return False
        now = now if now is not None else _time_mod.time()
        armed_at = self._armed_at.get(stock_code)
        if armed_at is None:
            return False
        if now - armed_at > TICK_ARM_TTL_SEC:
            return False          # 무장한 지 오래 — 이미 지나간 자리
        # 틱이 끊긴 종목의 '무장 잔재'를 걸러낸다. 틱이 없으면 강도 판정 자체가
        # 갱신되지 않으므로 무장 상태라고 볼 근거가 없다.
        try:
            tf = self.phase1b.trade_flow if self.phase1b else None
            if tf is None or tf.tick_count(stock_code, window_sec=TICK_ARM_TTL_SEC,
                                           now=now) <= 0:
                return False
        except Exception:
            return False
        # 지금도 강도가 요구시간만큼 유지되고 있는가(무장 조건 자체를 재확인)
        return self._strength_sustained_sec(stock_code, now) >= TICK_STRENGTH_SUSTAIN_SEC

    def _strength_sustained_sec(self, stock_code: str, now: float) -> float:
        since = self._strength_since.get(stock_code)
        if since is None:
            return 0.0
        return max(0.0, now - since)

    def reset_tick_entry_state(self, stock_code: str) -> None:
        """틱 진입 상태(강도 타이머/무장/쿨다운)를 완전히 지운다.

        **매도 직후와 감시 해제 시 반드시 불러야 한다.** 안 부르면
        `_strength_since`에 매수 전의 옛 타임스탬프가 그대로 남아, 그 종목이
        재매수 가능해진 뒤 첫 틱에서 `now - since`가 수 분~수 시간으로 계산돼
        **연속 유지 확인을 건너뛰고 즉시 무장**된다. 그 상태로 버스트가 하나 오면
        진입 조건의 절반(무장)이 사실상 없는 채로 매수가 나간다.

        재매수 차단(_is_rebuy_blocked)이 손실청산·쿨다운·횟수는 막아주지만,
        **익절 후 3분 쿨다운이 지난 종목**은 그 그물을 정상적으로 통과하므로
        여기서 지우지 않으면 실제로 뚫린다.

        stop_watching(trade_flow.reset)과 짝을 이룬다 — 틱 버퍼는 비웠는데
        타이머만 살아있는 불일치 상태를 만들지 않기 위함이다.
        """
        self._strength_since.pop(stock_code, None)
        self._armed_at.pop(stock_code, None)
        self._tick_entry_last.pop(stock_code, None)
        # 되돌림 대기 계획도 같이 지운다 (2026-08-04) — 청산·감시해제된 종목의
        # 계획이 남아 있으면 슬롯을 계속 점유하고, 나중에 되돌림이 닿으면
        # 재매수차단을 우회해 매수가 나갈 수 있다.
        self._entry_plans.pop(stock_code, None)

    def check_burst(self, stock_code: str, now: float = None,
                    now_dt: datetime = None) -> tuple[bool, dict]:
        """대량체결 버스트 3경로(OR) 판정. (통과여부, 상세) 반환.

          ① 3천만원 x 시간계수 이상 단일체결이 2건 이상 (5초 창)
          ② 1억원   x 시간계수 이상 단일체결이 1건 이상
          ③ max(1천만, 그 종목 평균 1틱 x20) 이상이 2건 이상  <- 자기 정규화

        ①②는 시각에 따라 문턱이 내려가고(점심 완화), ③은 분모가 함께
        줄어들어 자동으로 같은 난이도를 유지한다. 서로 다른 방식이라
        한쪽이 빗나가도 다른 쪽이 받는다.

        전부 같은 틱 버퍼만 읽으므로 REST 0콜 / 대기 0초다.
        """
        now = now if now is not None else _time_mod.time()
        tf = self.phase1b.trade_flow if (self.phase1b and self.phase1b.trade_flow) else None
        if tf is None:
            return False, {"reason": "체결강도 데이터 소스 없음(phase1b 미연결)"}

        tmul = self.burst_time_multiplier(now_dt)
        burst_min = PHASE1A_BURST_TRADE_VALUE * tmul
        single_min = PHASE1A_SINGLE_TRADE_VALUE * tmul

        try:
            burst_count = tf.count_large_trades(
                stock_code, window_sec=TICK_BURST_WINDOW_SEC,
                min_value=burst_min, now=now,
            )
            max_single = tf.max_single_trade_value(
                stock_code, window_sec=TICK_BURST_WINDOW_SEC, now=now
            )
            # 버스트 창(최근 5초)은 평균에서 **제외**한다 — 지금 터지는
            # 대량체결이 분모에 섞이면 체결이 클수록 문턱도 같이 올라가
            # 정작 큰 버스트가 탈락한다(격리 테스트에서 실제로 재현됨).
            # 여기서 재는 건 '버스트 직전까지의 평상시 체결 크기'다.
            avg_tick = tf.avg_trade_value(
                stock_code, window_sec=TICK_BURST_REL_WINDOW_SEC, now=now,
                exclude_recent_sec=TICK_BURST_WINDOW_SEC,
            )
        except Exception:
            logger.exception("[%s] 버스트 계산 실패 — 매수 보류", stock_code)
            return False, {"reason": "버스트 계산 실패"}

        # 경로 ③ — 평균 1틱 표본이 부족하면(avg_tick=0) 상대 판정을 포기하고
        # 절대 경로만 쓴다. '모름'이 매수를 막지도, 열어주지도 않게 한다.
        rel_min = 0.0
        rel_count = 0
        if avg_tick > 0:
            rel_min = max(TICK_BURST_REL_FLOOR, avg_tick * TICK_BURST_REL_MULT)
            try:
                rel_count = tf.count_large_trades(
                    stock_code, window_sec=TICK_BURST_WINDOW_SEC,
                    min_value=rel_min, now=now,
                )
            except Exception:
                rel_count = 0

        path_abs = burst_count >= PHASE1A_BURST_TRADE_COUNT
        path_single = max_single >= single_min
        path_rel = avg_tick > 0 and rel_count >= TICK_BURST_REL_COUNT

        detail = {
            "burst_count": burst_count,
            "max_single_trade": max_single,
            "avg_tick_value": avg_tick,
            "rel_count": rel_count,
            "rel_min": rel_min,
            "time_mult": tmul,
            "burst_min": burst_min,
            "single_min": single_min,
        }
        if path_abs:
            detail["burst_path"] = "절대"
            detail["trigger"] = (
                f"{burst_min/10000:,.0f}만원+ 체결 {burst_count}건"
                f"(x{tmul:.2f})"
            )
        elif path_single:
            detail["burst_path"] = "단일"
            detail["trigger"] = f"단일체결 {max_single/100_000_000:.2f}억"
        elif path_rel:
            detail["burst_path"] = "상대"
            detail["trigger"] = (
                f"평균1틱 {avg_tick/10000:,.0f}만원의 "
                f"{TICK_BURST_REL_MULT:.0f}배+ 체결 {rel_count}건"
            )
        else:
            detail["reason"] = (
                f"대량체결 부족 (최근 {TICK_BURST_WINDOW_SEC:.0f}초: "
                f"{burst_min/10000:,.0f}만원+ {burst_count}/{PHASE1A_BURST_TRADE_COUNT}건, "
                f"최대단일 {max_single/10000:,.0f}만원/{single_min/10000:,.0f}만원, "
                f"상대 {rel_count}/{TICK_BURST_REL_COUNT}건)"
            )
            return False, detail
        return True, detail

    def evaluate_tick_entry(
        self, stock_code: str, sub_strategy: str, current_price: float,
        open_price: float = 0.0, cond_name: str = "",
        now: float = None, now_dt: datetime = None,
    ) -> tuple[bool, dict]:
        """틱 구동 진입 평가 — 1A/Pullback 공통.

        [설계] 조건검색식이 '어떤 종목인가'를 전부 판정하고(3분봉 30이평
        근접·눌림폭·급등이력·유동성 100억+), 코드는 '지금이 그 순간인가'만
        본다. 그래서 코드가 확인하는 건 **체결강도와 거래대금 둘뿐**이다.

        1A와 Pullback이 같은 트리거를 쓰는 이유: 차이는 조건검색식(유니버스)에
        이미 들어있고, 진입 순간의 판단("매수세가 실제로 들어오는가")은 두
        전략이 동일하기 때문이다. 전략별 차이는 이 함수 밖에서 유지된다 —
        슬롯/등락률 상한(1A 16% / 눌림 10%)/익절 캡/시간창.

        게이트 순서(위에서 걸리면 즉시 탈락):
          1) 무장: 체결강도(FID 228) 100 이상 연속 유지  <- 호출부에서 이미 확인
          2) 1A 한정, 당일 시가 대비 +5% 이상이면 매수 보류
          3) 지수 HALT 차단
          4) 발사: 대량체결 버스트 3경로 OR
        """
        now = now if now is not None else _time_mod.time()
        sustained = self._strength_sustained_sec(stock_code, now)

        # 무장 확인은 여기서도 한다 — _maybe_tick_entry가 이미 걸렀지만,
        # on_condition_hit/watchlist_reentry 등 다른 경로가 이 함수를 직접
        # 부를 수 있어서 자체적으로 닫아둔다. 이게 없으면 "강도 연속 유지"가
        # 그 경로들에서 조용히 생략된다(진입 조건의 절반이 사라지는 구멍).
        if sustained < TICK_STRENGTH_SUSTAIN_SEC:
            return False, {
                "current_price": current_price,
                "strength_sustained_sec": round(sustained, 2),
                "reason": (
                    f"체결강도 미무장 ({TICK_STRENGTH_MIN:.0f} 이상 "
                    f"{sustained:.1f}/{TICK_STRENGTH_SUSTAIN_SEC:.0f}초 연속)"
                ),
            }

        # 시가대비 급등 매수보류 — 1A 전용(눌림목은 애초에 되돌림을 사는
        # 전략이라 '시가 대비 많이 올랐다'가 탈락 사유가 될 수 없다).
        if sub_strategy == "1A" and open_price > 0:
            surge_from_open = (current_price - open_price) / open_price * 100
            if surge_from_open >= PHASE1A_LEADING_OPEN_SURGE_CAP:
                return False, {
                    "current_price": current_price,
                    "reason": (
                        f"시가대비 +{surge_from_open:.1f}% "
                        f">= {PHASE1A_LEADING_OPEN_SURGE_CAP:.0f}% — 눌림 가능성으로 매수 보류"
                    ),
                }

        if self._get_market_defense_mode() == "HALT":
            return False, {
                "current_price": current_price,
                "reason": "지수 -5% 초과로 인한 전면 매매 중단",
            }

        ok, detail = self.check_burst(stock_code, now=now, now_dt=now_dt)
        info = dict(detail)
        info["current_price"] = current_price
        info["strength_sustained_sec"] = round(sustained, 2)
        if not ok:
            return False, info

        # score/score_threshold는 확장슬롯·슬롯교체가 전략 공통으로 읽는 필드.
        # 틱 경로엔 점수 개념이 없으므로 '유지시간/요구시간' 비율을 싣는다 —
        # 스케일이 달라도 컷라인 대비 비율로 비교되므로 형평이 맞는다.
        info["score"] = round(sustained, 2)
        info["score_threshold"] = TICK_STRENGTH_SUSTAIN_SEC
        info["entry_mode"] = "tick_driven"
        label = "1A" if sub_strategy == "1A" else "눌림"
        info["reason"] = (
            f"{label} 틱즉시진입 (강도 {TICK_STRENGTH_MIN:.0f}+ "
            f"{sustained:.1f}초 연속, {detail.get('trigger', '')})"
        )
        return True, info

    def _maybe_tick_entry(self, stock_code: str, parsed_trade: dict,
                          now: float = None) -> bool:
        """체결 틱마다 호출되는 진입 평가 진입점. 매수했으면 True.

        비용 설계 — 대부분의 틱은 아래 ①~③에서 O(1)로 끝난다:
          ① 보유/주문중/후보아님 -> 즉시 반환
          ② 강도 타이머 갱신(O(1)) 후, 무장 미달이면 반환  <- 틱의 대부분
          ③ 무장 이후에만 쿨다운을 걸고 전체 게이트를 돈다
        무장 전에 쿨다운을 걸면 3초가 차는 순간을 놓칠 수 있으므로 순서가 중요하다.
        """
        if not TICK_ENTRY_ENABLED:
            return False
        now = now if now is not None else _time_mod.time()
        self._tick_entry_stats["ticks"] += 1

        # ── ⓪ 되돌림 대기 계획 처리 (2026-08-04) ──────────────────
        # **아래 ① 게이트보다 먼저** 봐야 한다. 1차 트랜치가 체결되면 그 종목은
        # holdings에 들어가는데, ①이 먼저 걸리면 2차 트랜치가 영영 체결되지 않는다.
        if stock_code in self._entry_plans:
            px = parsed_trade.get("price") or self._fresh_tick_price(stock_code)
            return self._try_fill_entry_plan(stock_code, px, now=now)

        # ── ① 살 수 없는 상태면 즉시 종료 ─────────────────────────
        if stock_code in self.holdings or stock_code in self.pending:
            return False
        # 조건검색으로 편입된 종목만 대상 — 편입되지 않은 종목의 틱은
        # 애초에 구독하지도 않지만, 보유 종목 청산 후 남은 구독 등으로
        # 흘러들어올 수 있어 여기서 한 번 더 막는다.
        cond_name = self._cond_names.get(stock_code)
        if cond_name is None:
            return False

        # 감시가 안 켜져 있으면 여기서 켠다 — 자가 치유 (2026-08-02).
        # 무장은 FID 228만 보므로 감시 여부와 무관하게 진행되는데, 정작
        # 버스트 판정은 trade_flow 버퍼를 읽는다. 감시가 꺼져 있으면 버퍼가
        # 비어 **영원히 무장만 되고 발사는 안 되는** 상태가 된다(pre-arm이
        # 어떤 이유로든 누락되면 그 종목은 조용히 매매에서 빠진다).
        if self.phase1b and not self.phase1b.is_watching(stock_code):
            self.phase1b.start_watching(stock_code)

        # ── ② 무장: 강도 연속 유지 (여기까지가 틱의 대부분) ────────
        sustained = self.update_strength_timer(
            stock_code, parsed_trade.get("strength") or 0.0, now=now
        )
        if sustained < TICK_STRENGTH_SUSTAIN_SEC:
            return False

        if stock_code not in self._armed_at:
            self._armed_at[stock_code] = now
            self._tick_entry_stats["armed"] += 1
            logger.info(
                "[%s] 🔫 무장 — 체결강도 %.0f 이상 %.1f초 연속",
                stock_code, TICK_STRENGTH_MIN, sustained,
            )
        elif now - self._armed_at[stock_code] > TICK_ARM_TTL_SEC:
            # 무장한 지 오래됐는데 버스트가 안 온다 = 이미 지나간 자리일
            # 가능성이 크다. 타이머째 리셋해서 새 신호를 기다린다.
            self._strength_since.pop(stock_code, None)
            self._armed_at.pop(stock_code, None)
            return False

        # ── ③ 쿨다운 (무장 이후에만) ──────────────────────────────
        if TICK_ENTRY_COOLDOWN_SEC > 0:
            last = self._tick_entry_last.get(stock_code, 0.0)
            if now - last < TICK_ENTRY_COOLDOWN_SEC:
                return False
        self._tick_entry_last[stock_code] = now

        now_dt = self._now()
        now_t = now_dt.time()

        # 전략 라우팅 — on_condition_hit과 동일하게 resolve_strategy 하나만 본다.
        sub_strategy = self.resolve_strategy(cond_name, now_t)
        if sub_strategy == "1A":
            if not (GROUP_A_START <= now_t < PHASE1A_END):
                return False
        else:
            if not (PULLBACK_START <= now_t < PULLBACK_END):
                return False

        # 재매수 차단(손실청산/쿨다운/횟수상한)은 비싼 게이트 전에 확인한다.
        blocked, why = self._is_rebuy_blocked(stock_code)
        if blocked:
            self._note_reject(stock_code, why)
            return False

        current_price = parsed_trade.get("price") or self._fresh_tick_price(stock_code)
        if not current_price or current_price <= 0:
            return False

        ok, info = self.evaluate_tick_entry(
            stock_code, sub_strategy, current_price,
            open_price=self._opening_prices.get(stock_code, 0.0),
            cond_name=cond_name, now=now, now_dt=now_dt,
        )
        if not ok:
            self._note_reject(stock_code, info.get("reason", ""))
            return False
        self._tick_entry_stats["burst_ok"] += 1

        stock_name = self._stock_names.get(stock_code, stock_code)
        phase = self.get_current_phase()

        # 슬롯 확인~pending 등록을 직렬화 — on_trade는 to_thread로 실행돼
        # 여러 종목의 틱이 동시에 이 지점에 도달할 수 있다. 락이 없으면
        # 마지막 슬롯 하나를 둘이 통과하는 오버부킹이 난다.
        with self._tick_entry_lock:
            if stock_code in self.holdings or stock_code in self.pending:
                return False
            can_buy = (
                self.can_buy_phase1a(info) if sub_strategy == "1A"
                else self.can_buy_pullback(info)
            )
            if not can_buy:
                # 슬롯이 꽉 찬 순간에만 종목 우선순위를 본다(REST 0콜).
                if sub_strategy == "1A":
                    self._try_1a_priority_upgrade(
                        stock_code, self.candidate_tier(stock_code)
                    )
                    can_buy = self.can_buy_phase1a(info)
                if not can_buy:
                    # 차단 사유가 슬롯이 아닐 수 있다(지수 가드/MDD/HALT/격리).
                    # 그대로 "슬롯 부족"으로 적으면 진단 알림이 원인을 통째로
                    # 오분류해, 장중에 "왜 안 사는가"를 판단할 수 없게 된다.
                    self._note_reject(
                        stock_code,
                        self._entry_block_reason()
                        or (
                            f"슬롯 부족 ({sub_strategy} "
                            f"{self.count_holdings_by_strategy(sub_strategy)}, "
                            f"전체 {self.occupied_slots()}/{MAX_HOLDINGS})"
                        ),
                    )
                    return False
            self.pending.add(stock_code)
            self._pending_strategy[stock_code] = sub_strategy

        # pending을 **잡은 채로** _execute_buy를 부른다. 넘기기 직전에 풀면
        # 그 틈에 다른 스레드가 같은 마지막 슬롯을 통과할 수 있다(on_trade는
        # to_thread로 실행돼 여러 종목의 틱이 동시에 이 지점에 온다).
        try:
            self._record_watch_list(stock_code, stock_name, phase, info, cond_name)
            logger.info(
                "[%s] %s ⚡ 틱 진입 트리거 [%s] — %s",
                stock_code, stock_name, sub_strategy, info.get("reason", ""),
            )
            # (2026-08-04) 트리거 시점은 국소 고점이다(실측 6/6이 60초 내 되돌림).
            # 즉시 사지 않고 되돌림 대기 계획을 건다. 슬롯은 계획이 잡고 있으므로
            # finally에서 pending을 놓아도 안전하다 — occupied_slots()가
            # _entry_plans를 함께 센다.
            if ENTRY_PULLBACK_ENABLED and ENTRY_PULLBACK_TRANCHES:
                self._open_entry_plan(
                    stock_code, stock_name, phase, info, sub_strategy,
                    cond_name, trigger_price=current_price, now=now,
                )
                return False
            self._execute_buy(
                stock_code, stock_name, phase, info, sub_strategy=sub_strategy
            )
            bought = stock_code in self.holdings
            if bought:
                self._tick_entry_stats["bought"] += 1
            return bought
        except Exception:
            logger.exception("[%s] 틱 진입 매수 실패", stock_code)
            return False
        finally:
            # _execute_buy도 자체 finally에서 pending을 지우지만, **거기 도달하기
            # 전에 early-return 하는 경로가 여럿 있다**(15:10 하드컷오프,
            # 등락률 상한 초과, 조건검색-전략 불일치, 수량 0...). 그 경우
            # 우리가 미리 넣은 pending이 영구히 남아 occupied_slots()가 그
            # 자리를 계속 점유된 것으로 세고, 그 종목은 다시는 매수되지 않는다.
            # 여기서 반드시 회수한다(이미 지워졌으면 discard는 무해).
            self.pending.discard(stock_code)
            self._pending_strategy.pop(stock_code, None)

    # ========================================
    # 되돌림 대기 분할매수 (2026-08-04)
    # ========================================
    def _open_entry_plan(self, stock_code, stock_name, phase, info, sub_strategy,
                         cond_name, trigger_price, now=None):
        """트리거 시점에 '되돌림 대기' 계획을 건다(즉시 매수하지 않는다)."""
        if stock_code in self._entry_plans or stock_code in self.holdings:
            return

        # 살 수 없는 종목에 계획을 걸면 그 슬롯이 ENTRY_PULLBACK_TIMEOUT_SEC
        # 동안 묶인다(구버전은 _execute_buy 안에서 즉시 걸러져 pending이 바로
        # 회수됐다). 진입 자체를 막는 값싼 게이트는 **계획 생성 전에** 본다.
        entry_cap = self._entry_change_cap(sub_strategy)
        try:
            prev_close = self._get_prev_close(stock_code, trigger_price)
        except Exception:
            prev_close = None
        if prev_close:
            change_pct = (trigger_price - prev_close) / prev_close * 100
            if change_pct > entry_cap:
                self._note_reject(
                    stock_code,
                    f"등락률 상한 초과 (전일종가대비 +{change_pct:.1f}% > +{entry_cap:.0f}%)",
                )
                logger.info(
                    "[%s] %s 되돌림 대기 생략: 전일종가대비 +%.1f%% (상한 +%.0f%%)",
                    stock_code, stock_name, change_pct, entry_cap,
                )
                return

        now = now if now is not None else _time_mod.time()
        targets = []
        for depth, frac in ENTRY_PULLBACK_TRANCHES:
            targets.append({
                "price": trigger_price * (1.0 - depth),
                "frac": frac,
                "depth": depth,
                "filled": False,
            })
        self._entry_plans[stock_code] = {
            "trigger_price": trigger_price,
            "targets": targets,
            "deadline": now + ENTRY_PULLBACK_TIMEOUT_SEC,
            "sub_strategy": sub_strategy,
            "info": dict(info),
            "cond_name": cond_name,
            "phase": phase,
            "stock_name": stock_name,
        }
        logger.info(
            "[%s] %s ⏳ 되돌림 대기 진입 — 트리거 %s원 / 목표 %s / %.0f초 내",
            stock_code, stock_name, f"{trigger_price:,.0f}",
            " · ".join(
                f"-{t['depth']*100:.1f}%={t['price']:,.0f}({t['frac']*100:.0f}%)"
                for t in targets
            ),
            ENTRY_PULLBACK_TIMEOUT_SEC,
        )

    def _try_fill_entry_plan(self, stock_code, price, now=None) -> bool:
        """체결 틱마다 호출 — 목표가에 닿은 트랜치를 집행한다.

        되돌림이 깊으면 한 틱에 두 트랜치가 같이 체결될 수 있다(정상).
        """
        plan = self._entry_plans.get(stock_code)
        if not plan or not price or price <= 0:
            return False
        now = now if now is not None else _time_mod.time()

        if now >= plan["deadline"]:
            self._close_entry_plan(stock_code, "시간초과")
            return False

        filled_any = False
        for t in plan["targets"]:
            if t["filled"] or price > t["price"]:
                continue
            t["filled"] = True
            already = stock_code in self.holdings
            info = dict(plan["info"])
            info["current_price"] = price
            try:
                self._execute_buy(
                    stock_code, plan["stock_name"], plan["phase"], info,
                    sub_strategy=plan["sub_strategy"],
                    size_frac=t["frac"], add_to_position=already,
                )
            except Exception:
                logger.exception("[%s] 분할매수 트랜치 체결 실패", stock_code)
            if stock_code in self.holdings:
                filled_any = True
                self._tick_entry_stats["bought"] += 1
            elif not already:
                # 1차가 거부됐다(_execute_buy의 내부 게이트: 하드컷오프, 전략
                # 불일치, 수량 0, 주문 실패...). 계획을 유지하면 살 수도 없는
                # 종목이 슬롯을 타임아웃까지 붙잡는다 — 즉시 회수한다.
                self._close_entry_plan(stock_code, "1차 매수 거부")
                return False

        if all(t["filled"] for t in plan["targets"]):
            self._close_entry_plan(stock_code, "전량 체결")
            return filled_any

        # ── 상승 이탈 즉시진입 (2026-08-05 신규) ───────────────────────
        # 되돌림을 기다리는데 오히려 트리거가 +ENTRY_BREAKOUT_PCT를 넘으면
        # "되돌림이 안 온다"는 관측이 성립한 것이다. 남은 트랜치를 전량 집행한다.
        # 위 되돌림 루프를 **먼저** 돌린 뒤에 본다 — 한 틱의 가격은 하나뿐이라
        # 실제로 둘이 동시에 성립할 수는 없지만, 더 좋은 가격(하락)을 우선한다는
        # 의도를 코드 순서로 못박아 둔다.
        if not ENTRY_BREAKOUT_ENABLED or plan.get("breakout_done"):
            return filled_any
        trigger_price = plan["trigger_price"]
        if price < trigger_price * (1.0 + ENTRY_BREAKOUT_PCT):
            return filled_any

        remain = [t for t in plan["targets"] if not t["filled"]]
        if not remain:
            return filled_any
        plan["breakout_done"] = True

        # 가격이 올랐으므로 등락률 상한을 **다시** 본다. 계획 생성 시점엔
        # 통과했어도 지금은 넘었을 수 있다(그대로 사면 상한이 무의미해진다).
        try:
            prev_close = self._get_prev_close(stock_code, price)
        except Exception:
            prev_close = None
        if prev_close:
            cap = self._entry_change_cap(plan["sub_strategy"])
            change_pct = (price - prev_close) / prev_close * 100
            if change_pct > cap:
                self._note_reject(
                    stock_code,
                    f"등락률 상한 초과 (전일종가대비 +{change_pct:.1f}% > +{cap:.0f}%)",
                )
                logger.info(
                    "[%s] %s 상승 이탈했으나 등락률 상한 초과로 미집행 "
                    "(전일종가대비 +%.1f%% > +%.0f%%)",
                    stock_code, plan["stock_name"], change_pct, cap,
                )
                self._close_entry_plan(stock_code, "상승 이탈(등락률 초과)")
                return filled_any

        frac = sum(t["frac"] for t in remain)
        for t in remain:
            t["filled"] = True
        already = stock_code in self.holdings
        info = dict(plan["info"])
        info["current_price"] = price
        info["entry_note"] = (
            f"되돌림 포기 — 상승 이탈(+{ENTRY_BREAKOUT_PCT*100:.1f}%)"
        )
        logger.info(
            "[%s] %s ⚡ 되돌림 포기 — 상승 이탈 (트리거 %s원 -> %s원, +%.2f%%) "
            "잔여 %.0f%% 즉시 집행",
            stock_code, plan["stock_name"], f"{trigger_price:,.0f}", f"{price:,.0f}",
            (price - trigger_price) / trigger_price * 100, frac * 100,
        )
        try:
            self._execute_buy(
                stock_code, plan["stock_name"], plan["phase"], info,
                sub_strategy=plan["sub_strategy"],
                size_frac=frac, add_to_position=already,
            )
        except Exception:
            logger.exception("[%s] 상승 이탈 즉시진입 실패", stock_code)
        if stock_code in self.holdings:
            filled_any = True
            self._tick_entry_stats["bought"] += 1
        self._close_entry_plan(stock_code, "상승 이탈 전량 체결")
        return filled_any

    def _close_entry_plan(self, stock_code, why=""):
        plan = self._entry_plans.pop(stock_code, None)
        if not plan:
            return
        done = sum(1 for t in plan["targets"] if t["filled"])
        total = len(plan["targets"])
        if done == 0:
            # 되돌림이 안 와서 한 주도 못 샀다 — 놓친 것이므로 진단에 남긴다.
            self._note_reject(
                stock_code,
                f"되돌림 미도달 ({ENTRY_PULLBACK_TIMEOUT_SEC:.0f}초 내 "
                f"-{ENTRY_PULLBACK_TRANCHES[0][0]*100:.1f}% 미달)",
            )
        logger.info(
            "[%s] ⏳ 되돌림 대기 종료(%s) — %d/%d 트랜치 체결",
            stock_code, why, done, total,
        )

    def expire_entry_plans(self, now=None):
        """틱이 끊긴 종목의 계획을 회수한다 — tick()에서 주기 호출.

        _try_fill_entry_plan은 **그 종목의 틱이 와야** 돌기 때문에, 체결이
        멈춘 종목의 계획은 여기서 정리하지 않으면 슬롯을 영구 점유한다.
        """
        now = now if now is not None else _time_mod.time()
        for code in [c for c, p in self._entry_plans.items() if now >= p["deadline"]]:
            self._close_entry_plan(code, "시간초과")

    def evaluate_1a_leading_strength(
        self, stock_code: str, current_price: float,
        open_price: float = 0.0, cond_name: str = "",
    ) -> tuple[bool, dict]:
        """⚠️ [삭제 예정 / DEPRECATED — 2026-08-03 확인]

        **라이브에서 호출되지 않는다.** 08-02에 진입이 틱 구동
        (_maybe_tick_entry -> evaluate_tick_entry)으로 전면 전환되면서 호출부가
        교체됐고, 지금 이 함수를 부르는 건 테스트뿐이다.
        실제 1A 진입 조건을 고치려면 evaluate_tick_entry / _maybe_tick_entry를
        보라. 여기 있는 PHASE1A_LEADING_SUSTAIN_SEC(3초)는 매매에 영향이 없다.
        삭제하지 않는 이유는 CLAUDE.md 규칙 2(파일/코드 보존)와, 옛 방식으로
        되돌릴 때의 참고용이다.

        ── 이하 원래 설명 (2026-08-01 시점) ──
        1A 즉시진입 평가 — 체결강도(3초) + 대량체결 버스트.

        [2026-08-01 개편, 사용자 지정] 게이트 순서(위에서 걸리면 즉시 탈락):
          0) 감시 시작(체결틱/호가 수집) — 최초 호출부터 데이터를 모은다
          1) 주도주상위 한정, **당일 시가** 대비 +5% 이상이면 매수 보류
          2) 지수 HALT 차단
          3) 대량체결 버스트: 최근 3초에
               3천만원+ 단일체결 3건 이상  OR  1억원+ 단일체결 1건 이상
          4) 체결틱 3개 이상 (없으면 강도 '판단 불가'로 탈락 — 중립값 통과 방지)
          5) 3초 가중 체결강도 >= 100 x 동적배수(CAUTION/COLD일 때만 상향)
        통과 시 info에 score/score_threshold(=강도/임계값)를 실어 확장 슬롯과
        슬롯 교체가 다른 전략과 같은 축(컷라인 대비 비율)에서 비교되게 한다.

        ── 아래는 2026-07-31 도입 당시 배경(유지) ────────────────────

        도입 당시엔 주도주상위 소스 전용이었으나, 같은 논리(조건검색식이
        이미 강한 종목만 걸러 넘겨주므로 우리 쪽 추가 필터가 중복검증으로
        지연만 유발한다)를 돌파자동매매용까지 확장해 이제 소스 구분 없이
        1A 전체가 이 경로 하나로 통일됨(눌림목자동 단독 소스만 예외, Pullback
        직행). evaluate_new_intensity_strategy(거래량증가지속+2분강도지속+
        점수)는 더 이상 호출되지 않지만 삭제하지 않고 아래에 그대로 둠.

        배경: 413630 실사례 — 조건검색 편입 처리는 34초로 빨랐지만, 이후
        1A/Pullback/1L 3개 전략의 자체 게이트에 20분(09:23~09:43)이 걸려서야
        1B 경로로 겨우 매수됐다(그마저 로컬 눌림패턴이 안 맞아 1A/Pullback은
        끝내 통과 못 함).

        그래서 이 경로는 체결강도 하나만, 짧게(1분) 확인해서 즉시매수한다:
          - 거래량증가지속 제외: 시가부터 수직급등하는 종목이 많아 "3봉
            연속 증가"라는 완만한 패턴 자체가 안 맞는 경우가 많음.
          - 테마 요구사항 제외: 테마 리더십 축은 1L이 담당하던 것 — 1L을
            아예 주석처리했으므로(on_trade 참고) 이제 중복 우려 자체가
            없어짐, 순수 체결강도 하나로 판단.
          - 체결강도 가산점(구 intensity_bonus, 점수에 얹던 방식) 제거: 점수
            시스템 자체를 안 쓰므로 얹을 자리가 없음 — 대신 `_execute_buy`가
            sub_strategy 무관 항상 `entry_strength`를 기록하고, 기존 동적캡
            (on_price_update의 TP_UPGRADE_TRIGGER, _update_dynamic_caps의
            강도+거래량 동시하락 즉시매도)이 1L만 제외하고 전부에 이미 적용
            되므로 새 코드 없이 그대로 이관된다.

        phase1b 감시를 여기서 직접 켠다 — 기존 1A는 Pullback 블록이 나중에
        start_watching을 걸어줘야만 체결 틱이 쌓이는 구조적 공백이 있어서
        (최초 평가는 틱 0개라 is_intensity_sustained가 항상 False) 최초
        편입 시점엔 통과가 원천 불가능했다(오늘 세션에서 발견). 여기서는
        그 공백 없이 최초 호출부터 바로 틱을 모으기 시작한다."""
        if self.phase1b and not self.phase1b.is_watching(stock_code):
            self.phase1b.start_watching(stock_code)

        # 시가대비 급등 매수보류 — 시가 대비 이미 가파르게 오른 종목은 눌림
        # (되돌림) 가능성이 커서 보수적으로 접근한다는 취지(2026-07-31 도입).
        # (2026-08-01 사용자 지정) 주도주상위 전용이던 것을 **1A 전 경로**로 확대.
        # 조건명을 안 따지는 이유: 1A는 이제 주도주상위/돌파자동매매용만 타므로
        # 사실상 "둘 다 적용"과 같고, cond_name이 "기타"로 뭉개진 경우에도
        # 필터가 조용히 꺼지지 않는다(조건명으로 분기하면 그 구멍이 생긴다).
        # 감시(start_watching)는 그대로 유지해서 되돌림 이후 재평가될 기회는
        # 남겨둔다(watchlist_reentry가 계속 재시도).
        if open_price > 0:
            surge_from_open = (current_price - open_price) / open_price * 100
            if surge_from_open >= PHASE1A_LEADING_OPEN_SURGE_CAP:
                return False, {
                    "current_price": current_price,
                    "reason": (
                        f"시가대비 +{surge_from_open:.1f}% "
                        f">= {PHASE1A_LEADING_OPEN_SURGE_CAP:.0f}% — 눌림 가능성으로 매수 보류"
                    ),
                }

        market_mode = self._get_market_defense_mode()
        if market_mode == "HALT":
            return False, {
                "current_price": current_price,
                "reason": "지수 -5% 초과로 인한 전면 매매 중단",
            }

        if not (self.phase1b and self.phase1b.trade_flow):
            return False, {
                "current_price": current_price,
                "reason": "체결강도 데이터 소스 없음(phase1b 미연결)",
            }

        # ── 대량체결 버스트 필터 (2026-08-01 사용자 지정) ──────────────
        # 기존 "60초 누적 거래대금 3천만원"을 대체. 누적은 잔챙이 체결이 길게
        # 쌓여도 채워져서 "지금 큰 손이 때리는가"를 구분 못 했다. 3초 창에서
        # 아래 둘 중 하나(OR)를 요구한다:
        #   ① 3천만원 이상 단일 체결이 3건 이상
        #   ② 1억원 이상 단일 체결이 1건이라도
        # 예외가 나도 매수로 새지 않도록 실패 시 0으로 두고 그대로 탈락시킨다.
        tf = self.phase1b.trade_flow
        try:
            burst_count = tf.count_large_trades(
                stock_code,
                window_sec=PHASE1A_LEADING_SUSTAIN_SEC,
                min_value=PHASE1A_BURST_TRADE_VALUE,
            )
            max_single = tf.max_single_trade_value(
                stock_code, window_sec=PHASE1A_LEADING_SUSTAIN_SEC
            )
            trade_value = tf.get_trade_value(
                stock_code, window_sec=PHASE1A_LEADING_SUSTAIN_SEC
            )
        except Exception:
            logger.exception("[%s] 1A 대량체결 계산 실패 — 매수 보류", stock_code)
            burst_count, max_single, trade_value = 0, 0.0, 0.0

        burst_ok = burst_count >= PHASE1A_BURST_TRADE_COUNT
        single_ok = max_single >= PHASE1A_SINGLE_TRADE_VALUE
        if not (burst_ok or single_ok):
            return False, {
                "current_price": current_price,
                "trade_value": trade_value,
                "burst_count": burst_count,
                "max_single_trade": max_single,
                "reason": (
                    f"대량체결 부족 (최근 {PHASE1A_LEADING_SUSTAIN_SEC}초: "
                    f"{PHASE1A_BURST_TRADE_VALUE/10000:,.0f}만원+ 체결 {burst_count}건"
                    f"/{PHASE1A_BURST_TRADE_COUNT}건, 최대단일 {max_single/10000:,.0f}만원"
                    f"/{PHASE1A_SINGLE_TRADE_VALUE/10000:,.0f}만원)"
                ),
            }

        # ── 체결강도 (3초 윈도우) ──────────────────────────────────
        # 틱 수를 직접 확인한 뒤 강도를 본다. compute_strength는 틱이 부족하면
        # 중립값(100.0)을 반환하는데 임계값도 100이라 "100 < 100 = False"로
        # **통과**해버린다 — 데이터가 없을수록 쉽게 뚫리는 구조라, 여기서는
        # 그 우연에 기대지 않고 틱 부족을 명시적으로 탈락시킨다.
        try:
            tick_n = tf.tick_count(stock_code, window_sec=PHASE1A_LEADING_SUSTAIN_SEC)
        except Exception:
            tick_n = 0
        if tick_n < PHASE1A_STRENGTH_MIN_TICKS:
            return False, {
                "current_price": current_price,
                "burst_count": burst_count,
                "max_single_trade": max_single,
                "reason": (
                    f"체결틱 부족 (최근 {PHASE1A_LEADING_SUSTAIN_SEC}초 {tick_n}틱 "
                    f"< 최소 {PHASE1A_STRENGTH_MIN_TICKS}틱) — 강도 판단 불가"
                ),
            }

        try:
            current_strength = tf.compute_strength(
                stock_code,
                window_sec=PHASE1A_LEADING_SUSTAIN_SEC,
                min_ticks=PHASE1A_STRENGTH_MIN_TICKS,
            )
        except Exception:
            logger.exception("[%s] 1A 체결강도 계산 실패 — 매수 보류", stock_code)
            current_strength = 0.0

        # 동적 강도 임계값 (2026-07-31 사용자 지정) — 고정 100은 "수치 호환성이
        # 안 맞을 때"(시장 전체가 흔들리거나 1A 자체가 오늘 잘 안 될 때) 그대로
        # 두면 너무 헐거워질 수 있어서, 새로 만들지 않고 이미 검증/구축된 두
        # 신호를 max()로 묶어 필요할 때만 위로 올린다(내리는 방향은 없음 —
        # 100을 바닥으로 고정, 진입을 원래보다 쉽게 만들 근거는 없다고 판단):
        #   ① 지수 방어 CAUTION — 시장 전체가 불안하면 "강해 보이는" 종목도
        #      신뢰도가 떨어진다는 게 옛 1A 점수시스템(PHASE1A_SCORE_CAUTION_BONUS)
        #      때부터의 전제. 같은 논리를 강도 임계값에도 그대로 적용.
        #   ② core/strategy_performance.py의 cutline_multiplier("1A") — 이미
        #      점수 컷라인용으로 만들어둔 축소추정 기반 HOT/COLD 조정을 재사용.
        #      COLD(오늘 1A 성과 나쁨)면 배수>1이 나와 임계값이 오르고, HOT이면
        #      <1이 나오지만 max(1.0, ...)로 묶어서 100 밑으로는 안 내려간다.
        #   ③ [제안 B, 2026-08-01] 같은 축소추정을 **조건검색식별로도** 적용.
        #      오늘 그 검색식이 물어다 준 종목들의 성과가 나쁘면(COLD) 배수가
        #      1을 넘어 임계값이 올라가고, 좋으면 1 미만이 나오지만 아래 max()가
        #      100을 바닥으로 잡아 진입이 원래보다 쉬워지지는 않는다.
        #      우선순위(줄 세우기)가 아니라 문턱 조정이라 진입 지연이 0이다.
        perf_mult = self.perf.cutline_multiplier("1A")
        cond_mult = self.perf.cutline_multiplier(self.cond_perf_key(cond_name))
        caution_mult = PHASE1A_LEADING_CAUTION_MULTIPLIER if market_mode == "CAUTION" else 1.0
        strength_mult = max(1.0, perf_mult, cond_mult, caution_mult)
        effective_strength_min = PHASE1A_LEADING_STRENGTH_MIN * strength_mult

        # 3초 창 전체를 하나의 시간가중 윈도우로 평가한다 (2026-08-01).
        # 기존 is_intensity_sustained(60초 구간을 10초 간격 샘플링)는 창이
        # 3초로 줄면 샘플이 1개뿐이라 의미가 없고, 무엇보다 틱이 없는 구간에
        # 중립값(100)을 채워 임계값 100을 그냥 통과시키는 성질이 있었다.
        # 여기서는 위에서 틱 수를 이미 확인했으므로 강도 비교만 하면 된다 —
        # 3초 가중 윈도우라 순간 스파이크 1틱으로는 통과할 수 없다.
        if current_strength < effective_strength_min:
            return False, {
                "current_price": current_price,
                "current_strength": current_strength,
                "strength_threshold": effective_strength_min,
                "score": current_strength,
                "score_threshold": effective_strength_min,
                "burst_count": burst_count,
                "max_single_trade": max_single,
                "reason": (
                    f"체결강도 미달 ({current_strength:.0f} < {effective_strength_min:.0f}"
                    f" = 기본 {PHASE1A_LEADING_STRENGTH_MIN:.0f} x{strength_mult:.2f}, "
                    f"{PHASE1A_LEADING_SUSTAIN_SEC}초 {tick_n}틱)"
                ),
            }

        trigger = (
            f"대량체결 {burst_count}건" if burst_ok
            else f"단일체결 {max_single/100_000_000:.2f}억"
        )
        return True, {
            "current_price": current_price,
            "current_strength": current_strength,
            "strength_threshold": effective_strength_min,
            # score/score_threshold는 확장슬롯(_can_use_expansion_slot)·슬롯교체가
            # 전략 공통으로 읽는 필드다 (2026-08-01 추가). 이게 없어서 1A는
            # 확장 슬롯을 영구히 못 쓰고 슬롯교체 대체후보 자격도 없었다.
            # 1A엔 점수 개념이 없으므로 체결강도/임계값을 그대로 싣는다 —
            # 스케일이 전략마다 달라도 '컷라인 대비 비율'로 비교하므로 형평이 맞는다.
            "score": current_strength,
            "score_threshold": effective_strength_min,
            "burst_count": burst_count,
            "max_single_trade": max_single,
            "trade_value": trade_value,
            "entry_mode": "1a_leading_strength",
            "reason": (
                f"1A 즉시진입 (강도 {current_strength:.0f}>={effective_strength_min:.0f} "
                f"/{PHASE1A_LEADING_SUSTAIN_SEC}초 {tick_n}틱, {trigger})"
            ),
        }

    def evaluate_new_intensity_strategy(
        self,
        stock_code: str,
        candles: list,
        current_price: int,
        open_price: int,
        now_t=None,
    ) -> tuple[bool, dict]:
        """체결강도 지속 & 거래량증가지속 기반의 1A 평가 로직 (지수 방어막 포함).
        10:30부터는 점수 커트라인을 상향(PHASE1A_SCORE_TIGHT)해서 더 빡빡하게.

        [주석으로 보류, 2026-07-31] 1A 라우팅이 evaluate_1a_leading_strength
        (체결강도 단독)로 전면 대체되면서 현재 어디서도 호출되지 않음. 삭제하지
        않고 남겨둠 — 심플화가 기대만큼 안 되면 _evaluate_1a_pullback_entry의
        라우팅을 이 함수 호출로 되돌리면 됨."""
        now = now_t if now_t is not None else self._now().time()

        # [최우선] 지수 방어막 확인
        market_mode = self._get_market_defense_mode()
        if market_mode == "HALT":
            return False, {"reason": "지수 -5% 초과로 인한 전면 매매 중단", "score": 0.0}

        # 1. 거래량증가지속 필터 (30봉신고가 대신, 2026-07-27 교체)
        # 개장 초반(대략 09:01~09:04)엔 오늘 분봉이 streak+1(4)개도 안 쌓여서
        # _get_merged_candles가 전일 마지막 분봉으로 채워 넣는데, 그러면 "어제
        # 장마감 무렵 거래량 vs 오늘 개장 1~2분"이라는 의미없는 비교가 되어
        # 매번 탈락함 (2026-07-29 실전 확인 — 오늘 조건검색 21종목 전부 이
        # 이유로 탈락, 1A가 하루 종일 0건). 전일 데이터는 섞지 않고 오늘
        # 분봉만으로 판단, 아직 부족하면 탈락이 아니라 보류(다음 재평가 때
        # 다시 시도 — watchlist_reentry가 슬롯 빌 때마다 재호출함).
        today_str = self._now().strftime("%Y%m%d")
        today_only = [c for c in candles if c.get("time_str", "").startswith(today_str)]
        if len(today_only) < 4:
            return False, {"reason": "오늘 분봉 부족(개장 초반) - 거래량 판정 보류", "score": 0.0}
        if not is_volume_increasing_streak(today_only):
            return False, {"reason": "거래량 증가 지속 아님", "score": 0.0}

        # 2. 시간대별 체결강도 지속 필터
        is_pass = False
        if now < PHASE1A_TIGHTEN_TIME:
            if not open_price or open_price <= 0:
                return False, {"reason": "시작가 없음", "score": 0.0}

            change_pct = (current_price - open_price) / open_price * 100

            if change_pct <= 5.0:
                is_pass = self.phase1b.trade_flow.is_intensity_sustained(stock_code, 95, 60)
            elif change_pct <= 8.0:
                is_pass = self.phase1b.trade_flow.is_intensity_sustained(stock_code, 120, 60)
            else:
                is_pass = self.phase1b.trade_flow.is_intensity_sustained(stock_code, 160, 60)
        else:
            is_pass = self.phase1b.trade_flow.is_intensity_sustained(stock_code, 105, 120)

        if not is_pass:
            return False, {"reason": "체결강도 지속 미달", "score": 0.0}

        # 3. 점수 계산 (기존 score 시스템 활용) — evaluate_phase1 자체의 ok는
        # 안 씀(2026-07-30 수정). self.score_cfg.threshold_ratio(0.75, 12점 만점
        # 9.0점)가 바로 아래 5번의 진짜 시간대별 커트라인(오전 6.5/10:30이후 8.5)
        # 보다 항상 더 높아서, ok로 먼저 거르면 "10:30부터 빡빡하게"라는 설계가
        # 하루 종일 죽은 코드가 됨(9.0을 넘겨야 여기까지 오는데 9.0은 6.5·8.5
        # 둘 다보다 크므로). base_score는 점수만 뽑아 쓰고 최종 판정은 5번의
        # required_score 하나로 통일.
        _, info = self.evaluate_phase1(candles, stock_code)

        base_score = info.get("score", 5.0)

        # 4. 체결강도 가산점 계산
        try:
            current_intensity = self.phase1b.trade_flow.compute_strength(stock_code, window_sec=10)
        except Exception:
            current_intensity = 100

        intensity_bonus = min(current_intensity / 100 * 1.0, 3.0)
        final_score = base_score + intensity_bonus

        # 5. 시간대(10:30 기준) + 지수 상태(CAUTION)에 따른 동적 커트라인
        base_required = (
            PHASE1A_SCORE_TIGHT if now >= PHASE1A_TIGHTEN_TIME else PHASE1A_SCORE_NORMAL
        )
        required_score = base_required + (
            PHASE1A_SCORE_CAUTION_BONUS if market_mode == "CAUTION" else 0.0
        )
        # 장중 전략 성과에 따른 자동 조정 (2026-07-31) — 오늘 1A가 잘 되고 있으면
        # 컷라인을 낮춰 슬롯을 더 가져가고, 안 되면 높여 스스로 물러난다.
        perf_mult = self.perf.cutline_multiplier("1A")
        required_score *= perf_mult

        # score_threshold를 함께 실어야 확장 슬롯 판정(_can_use_expansion_slot)이
        # 1A에도 적용된다 — 없으면 Pullback만 확장 슬롯을 쓸 수 있어 형평이 깨짐.
        if final_score >= required_score:
            return True, {
                "reason": f"1A 통과 (강도:{current_intensity:.0f}, 모드:{market_mode})",
                "score": final_score,
                "score_threshold": required_score,
                "perf_multiplier": perf_mult,
            }
        else:
            return False, {
                "reason": f"최종 점수 부족 ({final_score:.1f}/{required_score:.1f})",
                "score": final_score,
                "score_threshold": required_score,
                "perf_multiplier": perf_mult,
            }

    def evaluate_pullback(self, candles, stock_code, obv_mom: float = 0.0,
                          skip_setup_check: bool = False):
        # 주의: 인자명 obv_mom은 일부러 obv_momentum(모듈 임포트된 함수명)과
        # 다르게 지음 — 같은 이름을 지역변수/인자로 쓰면 함수 스코프 내에서
        # obv_momentum이 지역변수로 취급돼 호출부(_evaluate_1a_pullback_entry)의
        # obv_momentum(...) 호출이 UnboundLocalError로 깨짐.
        cfg = self._adjusted_cfg(self.pullback_score_cfg)
        # 장중 전략 성과 반영 (2026-07-31) — Pullback 전용 컷라인(threshold_abs)에
        # 배수를 적용. threshold_abs를 안 쓰는 설정이면 비율 쪽에 적용한다.
        perf_mult = self.perf.cutline_multiplier("1A_눌림")
        if perf_mult != 1.0:
            if cfg.threshold_abs is not None:
                cfg = _dc_replace(cfg, threshold_abs=cfg.threshold_abs * perf_mult)
            else:
                cfg = _dc_replace(cfg, threshold_ratio=cfg.threshold_ratio * perf_mult)
        return score_pullback(
            candles,
            self._volume_ratio(candles),
            self._current_strength(stock_code),
            cfg,
            obv_momentum=obv_mom,
            skip_setup_check=skip_setup_check,
        )

    def _apply_vwap_filter(
        self, stock_code: str, strat_name: str, current_price: float, info: dict,
        today_candles: list | None = None,
    ) -> bool:
        """눌림목(pullback) 전용 VWAP AND 필터. 다른 전략은 항상 통과.
        반환 True = 매수 진행, False = VWAP 탈락으로 매수 보류.
        주의: VWAP은 당일 09:00~현재 누적이라야 정확함. 전일 데이터가
        섞이는 _get_merged_candles는 절대 쓰지 않고, get_minute_candles를
        직접 호출해서 당일 데이터만 사용함.
        today_candles: 호출부가 이미 당일 전용 캔들을 갖고 있으면(예: OBV
        점수 계산에 이미 씀) 넘겨서 REST 재호출 방지, 없으면 새로 조회."""
        if strat_name != "pullback":
            return True
        try:
            vwap_candles = (
                today_candles if today_candles is not None
                else self.api.get_minute_candles(stock_code, interval=1, count=400)
            )
            vwap = calc_vwap(vwap_candles)
        except Exception as e:
            logger.warning("[%s] VWAP 계산 실패, 필터 스킵: %s", stock_code, e)
            return True  # 계산 실패 시 필터로 막지 않음 (기존 로직 유지)

        volume_ratio = 1.0
        try:
            volume_ratio = self._volume_ratio(vwap_candles)
        except Exception:
            pass

        result = self.vwap_strategy.evaluate(
            {
                "price": current_price,
                "vwap": vwap,
                "candles": vwap_candles,
                "volume_ratio": volume_ratio,
            }
        )
        info["vwap"] = vwap
        info["vwap_score"] = result["score"]
        info["vwap_confidence"] = result.get("confidence")
        info["vwap_gates"] = result.get("gates")

        if not result["bullish"]:
            logger.info(
                "[%s] pullback 조건 OK but VWAP 필터 탈락 "
                "(price=%.0f vwap=%.0f gap=%.2f%% score=%s conf=%s gates=%s)",
                stock_code,
                current_price,
                vwap,
                result.get("gap_pct", 0.0),
                result["score"],
                result.get("confidence"),
                result.get("gates"),
            )
            return False

        return True

    def _current_strength(self, stock_code):
        # 체결강도 조회. phase1b 없거나 실패/데이터 없으면 중립값 100 반환.
        if stock_code and self.phase1b and getattr(self.phase1b, "trade_flow", None):
            try:
                return self.phase1b.trade_flow.compute_strength(
                    stock_code, window_sec=10
                )
            except Exception:
                pass
        return 100.0

    @staticmethod
    def _volume_ratio(candles: list[dict]) -> float:
        cur_vol = candles[0]["volume"]
        prev = candles[1 : 1 + VOLUME_LOOKBACK]
        if not prev:
            return 0.0
        avg = sum(c["volume"] for c in prev) / len(prev)
        return cur_vol / avg if avg > 0 else 0.0

        # ========================================

    # 매수 실행
    # ========================================
    @staticmethod
    def tier_size_multiplier(tier: float) -> float:
        """tier -> 매수금액 배수 (2026-08-01, 제안 C).

        tier 1.0 이하 = 1.0배(기존과 동일), tier PHASE1A_SIZE_TIER_FULL 이상 =
        PHASE1A_SIZE_MAX_MULT배. 그 사이는 선형.

        **위로만 움직인다.** 아래로도 열면 평범한 후보의 매수 수량이 0주가 되어
        조용히 매매를 잃는 부작용이 생기고, 지금은 자본의 2.4%만 쓰는 단계라
        줄일 이유가 없다. 상한이 고정이라 tier가 아무리 커도(가속도가 폭발해도)
        금액이 폭주하지 않는다 — 이 함수가 유일한 확대 경로다.
        """
        try:
            t = float(tier)
        except (TypeError, ValueError):
            return 1.0
        if t <= 1.0:
            return 1.0
        span = max(PHASE1A_SIZE_TIER_FULL - 1.0, 1e-9)
        ratio = min((t - 1.0) / span, 1.0)
        return 1.0 + ratio * (PHASE1A_SIZE_MAX_MULT - 1.0)

    def _resolve_position_amount(
        self, stock_code: str, sub_strategy: str, tier: float = 0.0
    ) -> tuple[int, Optional[dict]]:
        base = POSITION_AMOUNT
        opt_info = None
        if self.optimizer is not None:
            try:
                info = self.optimizer.calculate_position_amount(stock_code, sub_strategy)
                amount = int(info.get("amount", 0))
                if amount > 0:
                    base, opt_info = amount, info
            except Exception:
                logger.exception(f"[{stock_code}] 비중 계산 실패, fallback")

        # [제안 C] tier 가중 — 같은 슬롯 하나라도 신호가 강한 자리에 더 태운다.
        tier_mult = self.tier_size_multiplier(tier)
        if tier_mult > 1.0:
            boosted = int(base * tier_mult)
            logger.info(
                "[%s] tier 가중 매수금액: %s원 x%.2f -> %s원 (tier %.2f)",
                stock_code, f"{base:,}", tier_mult, f"{boosted:,}", tier,
            )
            base = boosted
            if opt_info is not None:
                # 알림/로그에 최종 비중이 그대로 드러나도록 합성 배수를 실어준다.
                opt_info = dict(opt_info)
                opt_info["final_weight"] = opt_info.get("final_weight", 1.0) * tier_mult
        return base, opt_info

    def _get_opening_price(self, stock_code: str) -> Optional[float]:
        """당일 시가 조회 — on_condition_hit에서 이미 캐시했으면 재사용,
        없으면(1B/1L처럼 조건검색을 거치지 않고 실시간 틱으로 바로 들어온 경우
        캐시가 없을 수 있음) REST로 1회 조회 후 캐시. 실패 시 None(상한 체크 스킵)."""
        cached = self._opening_prices.get(stock_code)
        if cached:
            return cached
        try:
            candles = self.api.get_minute_candles(stock_code, interval=1, count=400)
            today = self._now().strftime("%Y%m%d")
            today_candles = [c for c in candles if c.get("time_str", "").startswith(today)]
            if not today_candles:
                return None
            open_price = float(min(today_candles, key=lambda c: c["time_str"])["open"])
            if open_price > 0:
                self._opening_prices[stock_code] = open_price
                return open_price
        except Exception as e:
            logger.warning("[%s] 시가 조회 실패, 등락률 상한 체크 스킵: %s", stock_code, e)
        return None

    def _get_prev_close(self, stock_code: str, current_price: float) -> Optional[float]:
        """전일종가 조회/캐시 (2026-07-31, 매수 등락률 상한 체크용).

        전일종가는 하루 내내 불변이므로 종목당 1회만 REST 호출하고 캐시한다.
        기존 get_stock_change_rate(ka10001, 이미 있는 메서드)는 등락률(%)만
        주므로, 지금 아는 current_price로 역산해서 전일종가 값 자체를 저장한다
        — 그래야 이후엔 API 재호출 없이 실시간 current_price만으로 등락률을
        즉시 계산할 수 있다(분봉 400개를 통째로 받아오던 예전 방식보다 REST
        부담이 훨씬 적음 — 이 계정은 이미 429가 하루 2천 건대로 포화 상태)."""
        cached = self._prev_closes.get(stock_code)
        if cached:
            return cached
        try:
            change_pct = self.api.get_stock_change_rate(stock_code)
            if not current_price or change_pct is None:
                return None
            prev_close = current_price / (1 + change_pct / 100)
            if prev_close > 0:
                self._prev_closes[stock_code] = prev_close
                return prev_close
        except Exception as e:
            logger.warning("[%s] 전일종가 조회 실패, 등락률 상한 체크 스킵: %s", stock_code, e)
        return None

    def _resolve_order_style(self, stock_code: str, current_price: float) -> tuple[str, int, str]:
        """호가창 두께로 지정가/시장가를 고른다 (2026-08-01 사용자 지정).

        매도 1~PHASE1A_ASK_DEPTH_LEVELS 호가의 잔량 '금액'을 보고:
          >= PHASE1A_ASK_DEPTH_MIN : 받아줄 물량이 충분 -> 시장가 (즉시체결)
          <  PHASE1A_ASK_DEPTH_MIN : 텅 빈 호가창 -> 지정가 (훑고 올라가는 것 방지)
          호가 스냅샷 없음/예외    : 지정가 (보수적 기본값)

        반환: (style, ref_price, 사유문자열)
          - 시장가: ref_price = 매도1호가('예상 체결가'로 기록용).
          - 지정가: ref_price = **매도N호가**(N=PHASE1A_ASK_DEPTH_LEVELS).
            (2026-08-01 변경) 예전엔 0을 줘서 order_manager가 '현재가+1틱'으로
            주문했는데, 호가창이 비었다는 건 매도1호가가 현재가보다 여러 틱 위에
            있을 가능성이 크다는 뜻이라 +1틱으로는 **아예 안 걸릴 수** 있었다.
            미체결이면 봇은 산 줄 알고 슬롯을 점유한 채 잘못된 매수가로 손익을
            계산하다가 45초 뒤 reconcile이 정리한다. 매도N호가로 걸면
            '슬리피지 상한이 정해진 즉시체결'이 되어 미체결도 막고 시장가처럼
            위로 훑고 올라가지도 않는다.
          - 호가 정보가 아예 없으면 0 -> 기존 '현재가+1틱' 폴백.

        절대 예외를 밖으로 던지지 않는다 — 호가 판정 실패가 매수 자체를
        막거나 크래시로 번지면 안 되므로, 어떤 실패든 '지정가'로 안전하게 수렴한다.
        """
        try:
            ob = getattr(self.phase1b, "orderbook", None) if self.phase1b else None
            if ob is None:
                return "limit", 0, "호가 트래커 없음 -> 지정가(현재가+1틱)"
            depth_value = ob.get_ask_depth_value(
                stock_code, levels=PHASE1A_ASK_DEPTH_LEVELS
            )
            if depth_value is None:
                return "limit", 0, "호가 스냅샷 없음 -> 지정가(현재가+1틱)"
            if depth_value >= PHASE1A_ASK_DEPTH_MIN:
                ask1 = ob.get_ask_price(stock_code, 1) or 0
                return "market", int(ask1), (
                    f"매도1~{PHASE1A_ASK_DEPTH_LEVELS}호가 잔량 "
                    f"{depth_value/10000:,.0f}만원 >= {PHASE1A_ASK_DEPTH_MIN/10000:,.0f}만원 "
                    f"-> 시장가"
                )
            askn = ob.get_ask_price(stock_code, PHASE1A_ASK_DEPTH_LEVELS) or 0
            return "limit", int(askn), (
                f"매도1~{PHASE1A_ASK_DEPTH_LEVELS}호가 잔량 "
                f"{depth_value/10000:,.0f}만원 < {PHASE1A_ASK_DEPTH_MIN/10000:,.0f}만원 "
                f"(빈 호가창) -> 지정가 "
                + (f"매도{PHASE1A_ASK_DEPTH_LEVELS}호가 {askn:,}원" if askn else "현재가+1틱")
            )
        except Exception:
            logger.exception("[%s] 호가 두께 판정 실패 -> 지정가로 진행", stock_code)
            return "limit", 0, "호가 판정 예외 -> 지정가(현재가+1틱)"

    def _fresh_tick_price(self, stock_code: str, max_age_sec: float = 10.0):
        """최근 max_age_sec 안에 체결이 있었을 때만 최신 체결가를 반환.

        (2026-08-01) 매수 단가 기준을 분봉 종가(최대 1분 지연) 대신 실시간
        체결가로 올리기 위한 헬퍼. 오래된 틱을 '현재가'로 잘못 쓰지 않도록
        반드시 신선도를 함께 확인한다 — 그냥 get_latest_price만 쓰면 몇 분 전
        가격이 그대로 나올 수 있다(감시만 켜두고 체결이 끊긴 종목).
        """
        if not (self.phase1b and getattr(self.phase1b, "trade_flow", None)):
            return None
        try:
            if self.phase1b.trade_flow.tick_count(stock_code, max_age_sec) <= 0:
                return None
            px = self.phase1b.trade_flow.get_latest_price(stock_code)
            return px if px and px > 0 else None
        except Exception:
            return None

    def _execute_buy(self, stock_code, stock_name, phase, info, sub_strategy,
                     size_frac: float = 1.0, add_to_position: bool = False):
        """매수 실행.

        size_frac: 이번에 살 비중(분할매수 트랜치). 1.0이면 기존과 동일.
        add_to_position: True면 **이미 보유 중인 종목에 추가매수**해서 평단가를
            갱신한다(분할매수 2차). False인데 이미 보유 중이면 호출부 실수이므로
            아무것도 하지 않는다 — 예전 코드는 holdings[code]를 통째로 덮어써서
            1차 매수분의 수량·평단가가 조용히 사라졌다.
        """
        current_price = info["current_price"]
        # 실시간 체결가가 있으면 그걸 기준가로 쓴다 (2026-08-01) — info의
        # current_price는 1분봉 종가라 최대 1분 지연이고, 그 값으로 수량/
        # 등락률상한/매수단가를 계산하면 빠르게 움직이는 종목에서 손익 판정이
        # 처음부터 어긋난다("매수가가 한참 위에서 된다"의 한 축).
        fresh_px = self._fresh_tick_price(stock_code)
        if fresh_px:
            if current_price and abs(fresh_px - current_price) / current_price > 0.10:
                # 10% 넘게 벌어지면 둘 중 하나가 이상한 값 — 보수적으로 분봉값 유지
                logger.warning(
                    "[%s] 실시간가(%s)와 분봉가(%s) 괴리 10%% 초과 — 분봉값 사용",
                    stock_code, f"{fresh_px:,}", f"{current_price:,}",
                )
            else:
                current_price = fresh_px

        if not current_price or current_price <= 0:
            logger.warning("[%s] %s 기준가 없음 -> 매수 취소", stock_code, stock_name)
            return

        if self._now().time() >= ENTRY_HARD_CUTOFF:
            logger.info(
                "[%s] %s 매수 차단: %s 이후 신규매수 하드 컷오프 [%s]",
                stock_code, stock_name, ENTRY_HARD_CUTOFF.strftime("%H:%M"), sub_strategy,
            )
            return

        if self._is_severe_crash() and self._now().time() >= SEVERE_CRASH_ENTRY_CUTOFF:
            logger.info(
                "[%s] %s 매수 차단: 지수 급락 대응 — %s 이후 신규매수 중단 [%s]",
                stock_code, stock_name, SEVERE_CRASH_ENTRY_CUTOFF.strftime("%H:%M"), sub_strategy,
            )
            return

        # 지수 하락 가드(INDEX_GUARD_FROM 이후) — 발동 중이면 신규매수를 전면 중단한다.
        # (2026-08-03) can_buy_more에도 같은 체크를 넣었지만, 주문 직전에도
        # 한 번 더 막는다 — 다른 경로가 추가돼도 절대 새지 않게 하는 하드가드다.
        if self._is_index_guard_active():
            self._note_reject(
                stock_code,
                f"지수 하락 가드({INDEX_GUARD_THRESHOLD:+.0f}%) — 신규매수 중단",
            )
            logger.info(
                "[%s] %s 매수 차단: 지수 하락 가드(%.0f%% 이하) 발동 중 [%s]",
                stock_code, stock_name, INDEX_GUARD_THRESHOLD, sub_strategy,
            )
            return

        cond_name_now = self._cond_names.get(stock_code, "")

        # 조건검색식 <-> 전략 결합 가드 (2026-08-01 사용자 지정).
        # 라우팅에서 이미 배타적으로 갈리지만, 다른 경로가 추가되거나 cond_name이
        # 뒤늦게 병합돼도 절대 새지 않도록 주문 직전에 한 번 더 막는다.
        # **단독 소스만** 막는다 — 중복 종목은 시간대에 따라 두 전략을 오가는 게
        # 정상이므로(오전 1A / 오후 Pullback) 여기서 막으면 안 된다.
        if sub_strategy in ("1A", "1A_눌림"):
            has_1a_src, has_pb_src = self.source_flags(cond_name_now)
            wrong = (
                (has_pb_src and not has_1a_src and sub_strategy != "1A_눌림")
                or (has_1a_src and not has_pb_src and sub_strategy == "1A_눌림")
            )
            if wrong:
                logger.info(
                    "[%s] %s 매수 차단: 조건검색식(%s)과 전략(%s) 불일치 "
                    "— 단독 소스는 전용 전략으로만 매수",
                    stock_code, stock_name, cond_name_now or "?", sub_strategy,
                )
                self._note_reject(
                    stock_code, f"조건검색식-전략 불일치 ({cond_name_now}/{sub_strategy})"
                )
                return

        entry_cap = self._entry_change_cap(sub_strategy)
        prev_close = self._get_prev_close(stock_code, current_price)
        if prev_close:
            change_pct = (current_price - prev_close) / prev_close * 100
            if change_pct > entry_cap:
                logger.info(
                    "[%s] %s 매수 차단: 전일종가대비 +%.1f%% (상한 +%.0f%%) [%s]",
                    stock_code, stock_name, change_pct, entry_cap, sub_strategy,
                )
                self._note_reject(
                    stock_code,
                    f"등락률 상한 초과 (전일종가대비 +{change_pct:.1f}% > +{entry_cap:.0f}%)",
                )
                return

        sc = info.get("score")
        if sc is not None:
            logger.info(
                "[%s] %s 매수평가 통과 | score=%.2f/%.2f | %s",
                stock_code,
                stock_name,
                sc,
                info.get("score_threshold", 0),
                info.get("score_breakdown", ""),
            )

        # tier는 매수금액 가중(제안 C)과 포지션 기록(사후 검증)에 둘 다 쓰이므로
        # 여기서 한 번만 계산해 재사용한다 — 메모리 연산이라 비용은 없지만
        # 두 번 부르면 값이 미세하게 달라져 로그와 기록이 어긋난다.
        entry_tier = self.candidate_tier(stock_code)
        position_amount, opt_info = self._resolve_position_amount(
            stock_code, sub_strategy, tier=entry_tier
        )
        # 분할매수 트랜치 — 전체 금액의 일부만 집행한다 (2026-08-04).
        if size_frac != 1.0:
            position_amount = position_amount * size_frac
        quantity = int(position_amount // current_price)
        if quantity < 1:
            logger.warning("[%s] %s 수량 0 -> skip", stock_code, stock_name)
            return
        if add_to_position and stock_code not in self.holdings:
            # 1차가 실패했거나 이미 청산된 뒤 2차가 도착한 경우 —
            # 신규 진입으로 취급하면 계획에 없던 매수가 된다.
            logger.info("[%s] 분할 2차인데 보유 없음 -> skip", stock_code)
            return
        if not add_to_position and stock_code in self.holdings:
            logger.warning("[%s] 이미 보유 중인데 신규매수 호출 -> skip", stock_code)
            return

        if opt_info:
            logger.info(
                "[%s] 동적 비중 %.2fx -> %s원",
                stock_code,
                opt_info.get("final_weight", 1.0),
                f"{position_amount:,}",
            )

        self.pending.add(stock_code)
        self._pending_strategy[stock_code] = sub_strategy
        try:
            ma_val = info.get("ma5") or 0
            # 틱 구동 진입(2026-08-02)은 1A/Pullback 공통이라 sub_strategy보다
            # **먼저** 분기한다 — 아래 sub_strategy 분기에 걸리면 실제로는 쓰지
            # 않는 옛 전략 설명(MA5 눌림목 / 거래량증가지속)이 DB에 기록돼
            # 사후 분석이 통째로 어긋난다.
            if info.get("entry_mode") == "tick_driven":
                entry_reason = (
                    f"{info.get('reason', '틱 진입')} "
                    f"| 경로={info.get('burst_path', '?')} "
                    f"| 시간계수 x{info.get('time_mult', 1.0):.2f} "
                    f"(현재가 {current_price:,})"
                )
            elif sub_strategy == "1A_눌림":
                entry_reason = (
                    f"눌림목 반등 | MA5={ma_val:,.0f} "
                    f"| vol x{info.get('volume_ratio', 0):.2f} (현재가 {current_price:,})"
                )
            elif info.get("entry_mode") == "1a_leading_strength":
                # 1A - 체결강도 단독 즉시진입(2026-07-31, evaluate_1a_leading_strength)
                entry_reason = (
                    f"1A 체결강도 즉시진입(강도만) | 강도={info.get('current_strength', 0):.0f} "
                    f"(현재가 {current_price:,})"
                )
            else:
                # 1A (거래량증가지속+체결강도지속+점수, 주도주상위 이외 소스)
                entry_reason = (
                    f"1A 거래량증가지속+체결강도지속 | score={info.get('score', 0):.2f} "
                    f"| vol x{info.get('volume_ratio', 0):.2f} (현재가 {current_price:,})"
                )
            if opt_info:
                entry_reason += f" | 비중x{opt_info.get('final_weight', 1.0):.2f}"

            if "vwap" in info:
                vwap = info["vwap"]
                gap_pct = ((current_price - vwap) / vwap * 100) if vwap > 0 else 0.0
                entry_reason += f" | VWAP {vwap:,.0f} (gap {gap_pct:+.2f}%, {info.get('vwap_score', 0)}점)"
                conf = info.get("vwap_confidence")
                if conf is not None:
                    entry_reason += f" | conf {conf:.2f}"
                gates = info.get("vwap_gates")
                if gates:
                    gate_str = ",".join(
                        f"{k}{'O' if v else 'X'}" for k, v in gates.items()
                    )
                    entry_reason += f" | gates[{gate_str}]"

            # 조건검색식 이름 프리픽스 (2026-07-06)
            cond_name = self._cond_names.get(stock_code, "알수없음")
            display_reason = entry_reason  # 텔레그램용 — cond_name 프리픽스 전 원문
            entry_reason = f"[{cond_name}] {entry_reason}"

            # ── 하이브리드 주문 (2026-08-01 사용자 지정) ────────────────
            # 호가창이 두툼하면 시장가(즉시체결), 텅 비었으면 지정가.
            # 판정이 실패하면 무조건 지정가로 수렴하므로 여기서 예외로
            # 매수가 통째로 깨지는 일은 없다(_resolve_order_style 참고).
            order_style, ask1, style_reason = self._resolve_order_style(
                stock_code, current_price
            )
            logger.info("[%s] 주문방식 판정: %s", stock_code, style_reason)
            result = self.order_manager.buy(
                stock_code,
                quantity,
                # 지정가 경로: 매도N호가가 있으면 그 가격으로(슬리피지 상한이
                # 정해진 즉시체결), 없으면 0 -> 기존 '현재가+1틱' 폴백.
                price=(ask1 if order_style == "limit" else 0),
                order_style=order_style,
                ref_price=ask1 or int(current_price),
            )

            # 시장가 실패 시 지정가 1회 폴백 (2026-08-01).
            # 이 계정은 모의투자이고, 지금까지 실제로 낸 주문은 전부
            # trde_tp="0"(지정가)뿐이라 모의 서버가 trde_tp="3"(시장가)을
            # 받아주는지 실거래로 확인된 적이 없다. 새 주문 방식 때문에
            # 매수 자체를 놓치는 일이 없도록, 시장가가 거부되면 즉시
            # 검증된 지정가 경로로 한 번 더 시도한다.
            if order_style == "market" and (not result or not result.get("success")):
                logger.warning(
                    "[%s] 시장가 주문 실패(%s) -> 지정가로 1회 폴백",
                    stock_code, (result or {}).get("error", "unknown"),
                )
                order_style = "limit"
                result = self.order_manager.buy(
                    stock_code, quantity, price=0, order_style="limit",
                )

            if not result or not result.get("success"):
                err = (result or {}).get("error", "unknown")
                logger.error("[%s] 매수 실패: %s", stock_code, err)
                SystemEventRepository.log(
                    "ORDER_FAIL", f"BUY {stock_code}: {err}", "ERROR"
                )
                _notify(
                    f"매수 실패\n{stock_code} {stock_name}\n사유: {err}", target="order"
                )
                return

            # 체결 기준가 — 지정가면 주문가, 시장가면 매도1호가(예상 체결가).
            # order_manager가 실제로 쓴 값을 그대로 받아야 손절/익절 판정이
            # 실제 체결가와 최소한으로 어긋난다 (2026-08-01).
            fill_price = int(result.get("price") or current_price)
            if fill_price <= 0:
                fill_price = int(current_price)
            entry_reason += f" | {order_style}"
            # trades.entry_reason은 VARCHAR(255) — 넘치면 insert가 통째로 실패해
            # trade_id가 없어지고 매도 DB 갱신까지 끊긴다(2026-07-27 실제 사고).
            # 길이를 안전하게 잘라서 그 클래스의 사고를 원천 차단한다.
            entry_reason = entry_reason[:250]

            # ── 분할매수 2차: 기존 포지션에 합산 (2026-08-04) ──
            # 새 trades 행을 만들지 않고 기존 행의 수량·평단가를 갱신한다.
            # 행 하나 = 한 왕복이라는 규약을 유지해야 손익 집계가 어긋나지 않는다.
            if add_to_position:
                prev = self.holdings.get(stock_code)
                if not prev:
                    logger.warning("[%s] 2차 체결했으나 포지션 소실 -> 보정 불가", stock_code)
                    return
                prev_qty = int(prev.get("qty", prev.get("buy_quantity")) or 0)
                new_qty = prev_qty + quantity
                new_avg = (
                    (prev["buy_price"] * prev_qty + fill_price * quantity) / new_qty
                    if new_qty else fill_price
                )
                prev["buy_price"] = new_avg
                prev["buy_quantity"] = new_qty
                prev["qty"] = new_qty
                prev["tranches_filled"] = int(prev.get("tranches_filled", 1)) + 1
                # 저점/고점 추적 기준도 새 평단가에 맞춰 재설정하지 않는다 —
                # 이 값들은 '가격' 이력이지 손익 기준이 아니다.
                if prev.get("trade_id") is not None:
                    try:
                        TradeRepository.update(prev["trade_id"], {
                            "buy_price": new_avg,
                            "buy_quantity": new_qty,
                            "buy_amount": new_avg * new_qty,
                        })
                    except Exception as e:
                        logger.exception(
                            "[%s] 분할 2차 DB 갱신 실패 (포지션은 정상): %s", stock_code, e
                        )
                logger.info(
                    "BUY(분할 %d차) [%s] %s %d주 @ %s원 -> 평단 %s원 / 총 %d주",
                    prev["tranches_filled"], stock_code, stock_name, quantity,
                    f"{fill_price:,}", f"{new_avg:,.0f}", new_qty,
                )
                SystemEventRepository.log(
                    "BUY_ADD",
                    f"{stock_code} {stock_name} +{quantity}주 @ {fill_price:,}원 "
                    f"-> 평단 {new_avg:,.0f}원 총 {new_qty}주",
                    "INFO",
                )
                _notify(
                    f"분할 매수 {prev['tranches_filled']}차 [{sub_strategy}]\n"
                    f"종목: {stock_name} ({stock_code})\n"
                    f"수량: +{quantity}주 @ {fill_price:,}원\n"
                    f"평단: {new_avg:,.0f}원 / 총 {new_qty}주",
                    target="order",
                )
                self._last_buy_at = self._now()
                return

            # 매수 주문은 이미 체결됨 — DB 기록이 실패해도 포지션 추적(self.holdings)은
            # 반드시 이어져야 하므로 insert_buy 예외가 위로 전파되지 않게 막는다.
            try:
                trade_id = TradeRepository.insert_buy(
                    stock_code=stock_code,
                    stock_name=stock_name,
                    buy_price=fill_price,
                    buy_quantity=quantity,
                    strategy_phase=phase,
                    sub_strategy=sub_strategy,
                    entry_reason=entry_reason,
                )
            except Exception as e:
                trade_id = None
                logger.exception("[%s] 매수 DB 기록 실패 (포지션은 정상 보유): %s", stock_code, e)
                SystemEventRepository.log(
                    "DB_LOG_FAIL", f"insert_buy {stock_code}: {e}", "ERROR"
                )

            strength_val = self._current_strength(stock_code)

            self.holdings[stock_code] = {
                "trade_id": trade_id,
                "buy_price": fill_price,
                # 최초 진입가. add_to_position(분할 2차/추가매수)이 buy_price를
                # 평단으로 덮어써도 이 값은 유지된다 — 추가매수 후 최종 방어선
                # (RESCUE_ADD_FINAL_STOP)의 기준이 '원가'이기 때문이다.
                "origin_price": fill_price,
                "buy_quantity": quantity,
                # qty = 현재 잔량. 부분매도(2026-08-04)가 이 값을 줄인다.
                # buy_quantity는 '총 매수량'으로 남겨 손익 기준을 유지한다.
                "qty": quantity,
                "tranches_filled": 1,
                "buy_time": self._now(),
                "stock_name": stock_name,
                "strategy_phase": phase,
                "sub_strategy": sub_strategy,
                "highest_price": fill_price,
                "lowest_price": fill_price,
                "ma20": None,
                "ma20_updated": None,
                "trigger": info.get("trigger"),
                "opening_price": info.get("opening_price", 0.0),
                "position_weight": (opt_info or {}).get("final_weight", 1.0),
                "warmup_until": self._now() + BUY_WARMUP,
                # entry_score도 _watch_scores와 같은 '컷라인 대비 비율' 스케일로
                # 통일 (2026-08-01) — 슬롯교체가 이 값과 후보 점수를 직접
                # 비교하는데, 한쪽만 원점수면 전략 간 비교가 무의미해진다.
                "entry_score": self._score_ratio(info),
                "entry_strength": strength_val,
                # 진입 시점 종목 tier — 사후 분석용(이 tier가 실제 성과를
                # 예측했는지 며칠 쌓아 검증할 것). 교체 판정은 '진입 tier'가
                # 아니라 항상 '현재 tier'로 한다.
                "entry_tier": entry_tier,
                # 조건검색식 성과 축 키 (제안 B) — 청산 시 이 키로 성과를 기록해야
                # "어느 검색식이 오늘 잘 물어다 주는가"가 축적된다.
                "cond_key": self.cond_perf_key(cond_name),
                "order_style": order_style,
            }

            self.sold_at.pop(stock_code, None)
            self._buy_success_count += 1
            self._last_buy_at = self._now()      # 진단용(매수 공백 감지)
            self._last_reject.pop(stock_code, None)
            # 당일 매수 횟수 누적 (익절 후 재매수 상한 판정용, 2026-07-30)
            self._buy_count_today[stock_code] = (
                self._buy_count_today.get(stock_code, 0) + 1
            )

            logger.info(
                "BUY [%s] %s %d주 @ %s원 (%s) = %s원 | 워밍업 %ds",
                stock_code,
                stock_name,
                quantity,
                f"{current_price:,}",
                sub_strategy,
                f"{current_price * quantity:,}",
                int(BUY_WARMUP.total_seconds()),
            )
            SystemEventRepository.log(
                "BUY",
                f"{stock_code} {stock_name} {quantity}주 @ {current_price:,}원 [{sub_strategy}]",
                "INFO",
            )
            weight_str = f" (비중 {opt_info['final_weight']:.2f}x)" if opt_info else ""
            if sc is not None:
                # 1A/Pullback: 점수 기반 진입 — 실제 점수/커트라인/항목별 breakdown 표시
                basis_str = (
                    f"판단근거: 점수 {sc:.2f}/{info.get('score_threshold', 0):.2f} "
                    f"({info.get('score_breakdown', '')}) | 체결강도 {strength_val:.0f}%"
                )
            else:
                # 1B/1L: 점수가 아니라 FSM 상태·체결강도 지속 기반 진입
                basis_str = f"판단근거: 체결강도 {strength_val:.0f}%"
            _notify(
                f"매수 체결 [{sub_strategy}]\n종목: {stock_name} ({stock_code})\n"
                f"수량: {quantity}주 @ {current_price:,}원{weight_str}\n"
                f"금액: {current_price * quantity:,}원\n"
                f"조건검색식: {cond_name}\n"
                f"매수이유: {display_reason}\n"
                f"{basis_str}",
                target="order",
            )
            self._mark_watch_bought(stock_code)
        finally:
            self.pending.discard(stock_code)
            self._pending_strategy.pop(stock_code, None)

    # ========================================
    # 워치리스트
    # ========================================
    def _record_watch_list(self, stock_code, stock_name, phase, info, cond_name=""):
        # 후보 점수는 **컷라인 대비 비율**로 저장한다 (2026-08-01 변경).
        # 슬롯교체(core/slot_replacement.py)는 "후보점수 >= 정체종목점수 x1.2"로
        # 비교하는데, 전략마다 점수 스케일이 완전히 달라서(1A는 체결강도 0~300,
        # Pullback은 0~9점) 원점수를 그대로 비교하면 항상 1A가 이긴다.
        # 비율(1.0 = 자기 컷라인 정확히 충족)로 통일하면 전략이 달라도
        # "자기 기준을 얼마나 넘겼나"라는 같은 축에서 비교된다.
        if info.get("score") is not None:
            self._watch_scores[stock_code] = self._score_ratio(info)
        # 재평가 후보 등록은 DB 기록과 분리 — DB에 이미 썼는지는
        # _watch_db_written으로 판단한다(2026-08-01). 예전엔 둘 다
        # watch_list_today로 판단해서, 지연평가 경로가 먼저 넣어둔 종목은
        # DB 행이 영영 안 남았다(백테스트/틱아카이브 유니버스에서 누락).
        self.watch_list_today.add(stock_code)
        if stock_code in self._watch_db_written:
            return
        try:
            extra = {}
            for k in ("ma5", "current_price", "volume_ratio"):
                if k in info:
                    extra[k] = info[k]
            if "surge_rate" in info:
                extra["surge_rate"] = info["surge_rate"] * 100
            if "reason" in info:
                extra["reason_not_bought"] = info["reason"]
            # 어떤 조건검색식이 이 종목을 편입시켰는지 매수 여부와 무관하게
            # 보존 (2026-07-31) — 기존엔 trades.entry_reason에만 "[조건명] ..."
            # 프리픽스로 남아서 매수 안 된 후보는 출처가 영구 소실됐고, 그 결과
            # 일일 백테스트가 조건검색식별 진입 로직 차이(눌림목자동 skip_setup_check
            # 등)를 전혀 재현할 수 없었다. 최초 평가 시점 값의 스냅샷이며, 이후
            # self._cond_names가 승격 병합돼도 이미 기록된 이 행은 갱신되지 않는다.
            if cond_name:
                extra["cond_name"] = cond_name
            WatchListRepository.add(
                stock_code=stock_code, stock_name=stock_name, phase=phase, **extra
            )
            self._watch_db_written.add(stock_code)
        except Exception as e:
            logger.warning("[%s] 워치리스트 DB 기록 실패(후보 등록은 유지): %s", stock_code, e)

    def _mark_watch_bought(self, stock_code: str):
        try:
            for w in WatchListRepository.find_by_date(self._now().date()):
                if w["stock_code"] == stock_code and not w.get("is_bought"):
                    WatchListRepository.mark_bought(w["id"])
                    break
        except Exception as e:
            logger.warning("[%s] mark_bought 실패: %s", stock_code, e)

    # ========================================
    # 청산 (5/22 개편: 손절 -2.5% / 익절캡 +2.5% / 20MA 이탈 / 시간정리)
    # ========================================
    def on_price_update(self, stock_code: str, current_price: float):
        pos = self.holdings.get(stock_code)
        if not pos or not current_price:
            return
        if stock_code in self.sell_blocked:
            return

        buy_price = pos["buy_price"]
        if not buy_price:
            return

        if current_price > pos["highest_price"]:
            pos["highest_price"] = current_price

        # 저점 추적 — 손실 반등 하이브리드 매도가 "저점 대비 얼마나 올라왔나"를
        # 판단하는 기준선 (2026-07-31). 매수가로 초기화해서, 매수 후 한 번도
        # 밀리지 않은 종목은 저점=매수가가 되어 반등 판정이 성립하지 않는다.
        low = pos.get("lowest_price")
        if low is None or current_price < low:
            pos["lowest_price"] = current_price

        gross_rate = (current_price - buy_price) / buy_price if buy_price > 0 else 0.0
        net_rate = gross_rate - ROUND_TRIP_COST
        exit_reason = None

        # ⚠️ 손절은 워밍업과 무관하게 **항상** 감시한다 (2026-08-03 수정).
        # 기존엔 아래 워밍업 return이 이 판정보다 **위**에 있어서, 매수 직후
        # 60초 동안은 얼마가 빠지든 아무 대응이 없었다(가격 폴백 태스크도
        # 결국 이 함수를 부르므로 우회 경로도 없었다). 워밍업의 목적은
        # '체결강도·거래량처럼 매수 직후 흔들리는 지표로 성급히 판단하지
        # 않는 것'이지, **가격 기반 하드 손절까지 멈추는 것이 아니다.**
        # 급락은 매수 직후일수록 위험한데 정확히 그 구간이 무방비였다.
        if gross_rate <= STOP_LOSS_RATE:
            # ── 손절 대신 추가매수 (2026-08-05) ────────────────────────
            # 원가는 추가매수로 평단이 바뀌어도 유지된다 — 최종 방어선(-6%)의
            # 기준이기 때문이다. buy_price는 add_to_position이 평단으로 덮는다.
            origin = float(pos.get("origin_price") or buy_price or 0)
            if pos.get("rescue_added"):
                # 이미 한 번 구조한 포지션 — 원가 -6%가 무조건 청산선이다.
                if origin > 0 and current_price <= origin * (1.0 - RESCUE_ADD_FINAL_STOP):
                    self._execute_sell(
                        stock_code, current_price,
                        f"추가매수 후 최종손절 "
                        f"(원가대비 {(current_price - origin) / origin * 100:.2f}%, "
                        f"평단대비 {gross_rate*100:.2f}%)",
                    )
                    return
                # -6% 전이면 손절을 보류한다. **return 하지 않고** 아래
                # 지수가드/강제청산 등 나머지 청산 경로는 그대로 태운다 —
                # 여기서 빠져나가면 가드가 켜진 날 이 포지션만 무방비가 된다.
            else:
                decision = self._rescue_gate(stock_code, pos, current_price, origin)
                if decision == "added":
                    return
                if decision == "observing":
                    # 매도 보류 — 관찰 창 안이다. 하한 이탈/만료는 _rescue_gate가
                    # 다음 틱에 'sell'로 바꿔준다. 틱이 끊겨도 30초 가격 폴백
                    # (task_holdings_price_fallback)이 이 함수를 다시 부른다.
                    return
                self._execute_sell(
                    stock_code, current_price,
                    f"손절 가격{gross_rate*100:.2f}% (순 {net_rate*100:.2f}%)",
                )
                return

        # ── 지수 하락 가드 청산 (2026-08-03 사용자 지정) ──────────────
        # 손절 바로 다음에 둔다 — 지수가 무너지는 날은 개별 종목의 익절캡/
        # 정체정리보다 '리스크 오프'가 우선이다. 손절보다는 뒤다(더 급한 건 손절).
        # 워밍업보다도 앞이다: 가드는 가격 기반 판정이라 강도/거래량처럼
        # 매수 직후 흔들리는 지표에 의존하지 않는다.
        if self._is_index_guard_active():
            now_t = self._now().time()
            if now_t < INDEX_GUARD_BREAKEVEN_UNTIL:
                # 1단계: 본전(순 0%) 이상이면 정리. 손실 중인 건 아직 안 판다 —
                # 지수 급락 중 저점 매도가 되므로 회복 기회를 준다.
                if net_rate >= 0:
                    self._execute_sell(
                        stock_code, current_price,
                        f"지수 가드 본전청산 (순 {net_rate*100:+.2f}%, "
                        f"{INDEX_GUARD_BREAKEVEN_UNTIL.strftime('%H:%M')} 이전)",
                    )
                    return
            elif now_t >= INDEX_GUARD_FORCE_CLOSE:
                # 2단계: 회복 기회를 다 주고도 남은 보유분은 손익 무관 강제청산.
                # 정규 강제청산(15:10)보다 앞당겨 지수 약세일 때 오버나이트
                # 리스크를 줄인다.
                self._execute_sell(
                    stock_code, current_price,
                    f"지수 가드 강제청산 "
                    f"({INDEX_GUARD_FORCE_CLOSE.strftime('%H:%M')}, "
                    f"순 {net_rate*100:+.2f}%)",
                )
                return

        warmup_until = pos.get("warmup_until")
        if warmup_until and self._now() < warmup_until:
            return

        # 1-b) 본전스톱 (2026-08-03) — 순 +1.0%를 한 번이라도 찍은 포지션은
        # 그 뒤 본전 아래로 내려오면 청산한다. '조기확정'이 하던 하방 보호를
        # 이쪽이 대신 맡고, 상단은 캡까지 열어둔다.
        # 무장은 아래 익절 분기에서 하지 않고 여기서 직접 한다 — 지수급락
        # 모드로 빠져 익절 분기를 건너뛰어도 하방 보호는 살아있어야 한다.
        if BREAKEVEN_STOP_ENABLED and exit_reason is None:
            if not pos.get("breakeven_armed") and net_rate >= BREAKEVEN_TRIGGER:
                pos["breakeven_armed"] = True
                pos["breakeven_peak"] = net_rate
                logger.info(
                    "[%s] %s 🛡 본전스톱 무장 (순 +%.2f%% 도달 — 이제 손실 없음)",
                    stock_code, pos.get("stock_name", ""), net_rate * 100,
                )
            elif pos.get("breakeven_armed"):
                if net_rate > pos.get("breakeven_peak", 0.0):
                    pos["breakeven_peak"] = net_rate
                if net_rate <= BREAKEVEN_FLOOR:
                    exit_reason = (
                        f"본전스톱 (고점 순+{pos.get('breakeven_peak', 0.0)*100:.2f}% "
                        f"-> 현재 순{net_rate*100:+.2f}%)"
                    )

        # 1-c) 분할매도 잔량 트레일 (2026-08-04) — 동적캡 1차(50%)가 나간
        # 포지션만 대상. 폭이 PARTIAL_EXIT_TRAIL(3%)로 넓은 이유는 '고점 도달 전
        # 되돌림'을 실측했더니 매드업 2.03% / 037070 3.90%였기 때문이다 —
        # 이보다 좁으면 본 상승 전에 털린다(08-03에 -0.5~1.0% 트레일이 현행보다
        # 나빴던 원인). 고점은 계속 올라가므로 오르는 동안엔 절대 발동하지 않는다.
        if (
            exit_reason is None
            and pos.get("partial_exited")
            and PARTIAL_EXIT_TRAIL > 0
        ):
            peak = max(
                float(pos.get("trail_peak") or 0.0),
                float(pos.get("highest_price") or 0.0),
                float(current_price),
            )
            pos["trail_peak"] = peak
            if peak > 0 and (peak - current_price) / peak >= PARTIAL_EXIT_TRAIL:
                exit_reason = (
                    f"분할 잔량 트레일 (고점 {peak:,.0f} 대비 "
                    f"-{(peak - current_price) / peak * 100:.2f}%, 순 {net_rate*100:+.2f}%)"
                )

        # 2) 익절 — 전 전략 flat 익절캡. (2026-08-02) 트레일링 분기는 1L
        # 전용이었고 1L 삭제로 도달 불가가 되어 함께 제거했다.
        # 지수 급락(-5%↓) 대응 모드에서는 캡 대신 flat SEVERE_CRASH_TAKE_PROFIT로
        # 통일(빠른 익절 확정). (2026-07-28)
        if exit_reason is None:
            if self._is_severe_crash():
                if net_rate >= SEVERE_CRASH_TAKE_PROFIT:
                    exit_reason = (
                        f"익절(지수급락 대응) 순+{net_rate*100:.2f}% (가격 +{gross_rate*100:.2f}%)"
                    )
            else:
                cap, cap_label = self._take_profit_cap(pos)

                # 동적 상향 갈림길 — 순 +1.0% 도달 시점에 체결강도로 판단
                # (2026-07-31). 가격 트리거이므로 틱이 들어오는 여기서 처리하고,
                # 거래량 확인이 필요한 '즉시매도'는 _update_dynamic_caps에서 담당.
                if pos.get("tp_cap") is None and net_rate >= TP_UPGRADE_TRIGGER:
                    rising = self._is_strength_rising_vs_entry(pos, stock_code)
                    # 주도테마 부합 가산점 (2026-07-31 사용자 지정) — 매수 "전"
                    # 조건이 아니라 매수 "후" 판단으로 전환. 1L이 하던 "주도테마
                    # 소속이어야 매수"라는 사전 게이트는 없앴지만(1L 자체 주석
                    # 처리), 매수 이후 시점에 마침 주도테마에 부합해 있으면
                    # 그것도 강도상승과 동등한 '가산점'으로 취급해 동적캡을
                    # 올린다 — 강도가 애매(None/False)해도 주도테마면 구제됨.
                    is_leading = bool(
                        self.theme_mgr and self.theme_mgr.is_leading_theme_stock(stock_code)
                    )
                    if rising is True or is_leading:
                        reasons = []
                        if rising is True:
                            reasons.append("강도상향")
                        if is_leading:
                            reasons.append("주도테마")
                        label = "+".join(reasons)
                        pos["tp_cap"] = TP_CAP_UPGRADED_MAX
                        pos["tp_cap_label"] = label
                        pos["tp_cap_upgraded"] = True   # 동적캡 즉시매도 대상 표식
                        cap, cap_label = TP_CAP_UPGRADED_MAX, label
                        logger.info(
                            "[%s] %s 익절캡 상향 -> %.1f%% (순+%.2f%% 도달, 사유=%s, "
                            "체결강도 기준 %.0f -> 현재 %.0f, 테마=%s)",
                            stock_code, pos.get("stock_name", ""),
                            TP_CAP_UPGRADED_MAX * 100, net_rate * 100, label,
                            self._strength_baseline(pos) or 0,
                            self._current_strength(stock_code),
                            self.theme_mgr.code_to_theme.get(stock_code, "-")
                            if self.theme_mgr else "-",
                        )
                    # (2026-08-03) rising is False에서 '익절 조기확정'으로 즉시
                    # 매도하던 분기를 제거했다. 08-03 실거래 2건이 전부 매도 후
                    # 더 올랐고(+12.0% / +3.4%), 강도 미상승 판정 자체도 기준값이
                    # 진입 순간의 스파이크라 신뢰도가 낮았다(_strength_baseline
                    # 주석 참고). 이제 이 지점은 위의 본전스톱이 담당한다 —
                    # 하방은 본전에서 막고, 상단은 기본 캡까지 열어둔다.

                if exit_reason is None and net_rate >= cap:
                    exit_reason = (
                        f"익절 캡({cap_label} {cap*100:.1f}%) 순+{net_rate*100:.2f}% "
                        f"(가격 +{gross_rate*100:.2f}%)"
                    )

        # 3) 정체 정리 — 30분을 다 기다리지 않고 15분에 한 번 끊는다 (2026-08-01).
        # 실측(07-28~31, 73건): '시간정리 30분' 7건이 슬롯·분의 25%를 먹고 평균
        # -0.78%였고, ±0.5% 이내로 끝난 무의미 청산 14건이 185분(22%)을 점유했다.
        # 반면 돈을 번 청산(익절+트레일링)은 슬롯·분의 19%만 썼다 — 슬롯의
        # 기회비용을 생각하면 '아무 방향도 못 잡은 자리'를 오래 들고 있을 이유가
        # 없다. 30분 컷은 최후 방어선으로 그대로 유지한다.
        #
        # ⚠️ (2026-08-03 변경) 이 두 청산은 **슬롯이 꽉 찼을 때만** 발동한다.
        # 근거: 둘 다 존재 이유가 '슬롯 기회비용'이다 — 자리를 비워 더 나은
        # 후보를 받으려는 것. 그런데 슬롯이 남아 있으면 비울 이유가 없고,
        # 자리를 만들어도 들어올 후보가 없으니 **손실만 확정**하게 된다.
        # 08-03 실측: 동시보유 최대 2종목(상한 6)이라 슬롯이 하루 종일 남았는데도
        # 시간정리·정체정리가 4건(-0.78%, +0.41%, +0.34%, ...) 나갔다.
        #
        # 지수 가드 발동 중에는 신규매수가 막혀 있으므로, 슬롯을 비워도 쓸 곳이
        # 없다 -> 이때도 발동하지 않는다. 이게 없으면 "본전 이하는 손절선이나
        # 14:50까지 가져간다"는 가드 사양이 30분 컷에 먼저 잘려 무의미해진다
        # (시뮬레이션으로 확인: 보유 31분 종목이 '시간정리 30분'으로 매도됐다).
        if exit_reason is None and not self._is_index_guard_active():
            slots_full = self.occupied_slots() >= MAX_HOLDINGS
            if slots_full:
                held = self._now() - pos["buy_time"]
                if held >= HOLDING_TIMEOUT:
                    exit_reason = (
                        f"시간정리 30분 (순 {net_rate*100:+.2f}%, 슬롯 만석)"
                    )
                elif (
                    held >= timedelta(minutes=DEAD_POSITION_MIN)
                    and abs(net_rate) <= DEAD_POSITION_BAND
                ):
                    exit_reason = (
                        f"정체 정리 {DEAD_POSITION_MIN}분 (순 {net_rate*100:+.2f}%, "
                        f"±{DEAD_POSITION_BAND*100:.1f}% 밴드 — 슬롯 만석)"
                    )

        if exit_reason:
            self._execute_sell(stock_code, current_price, exit_reason)

    def _rescue_precheck(self, stock_code: str, pos: dict) -> tuple[bool, str]:
        """조건 ①거래대금 ②체결강도 — 관찰을 시작할 자격이 있는가.

        ③(반등 확증)은 관찰 창 안에서 따로 본다. 예외를 밖으로 던지지 않는다.
        """
        tf = getattr(self.phase1b, "trade_flow", None) if self.phase1b else None
        if tf is None:
            return False, "틱 트래커 없음"

        # ① 거래대금 급증
        accel = tf.value_acceleration(stock_code, short_sec=30, long_sec=120)
        if accel < RESCUE_ADD_ACCEL_MIN:
            return False, f"거래대금 배수 {accel:.2f} < {RESCUE_ADD_ACCEL_MIN}"

        # ② 체결강도 — 절대수준(매수우위) AND 기준선 대비 상승
        cur_s = self._current_strength(stock_code)
        if cur_s < RESCUE_ADD_MIN_STRENGTH:
            return False, f"체결강도 {cur_s:.0f} < {RESCUE_ADD_MIN_STRENGTH:.0f}"
        self._maybe_anchor_strength_baseline(pos, stock_code)
        base_s = self._strength_baseline(pos)
        if not base_s or base_s <= 0:
            return False, "강도 기준선 미확보(판단 불가)"
        if cur_s <= base_s:
            return False, f"강도 미상승 ({base_s:.0f} -> {cur_s:.0f})"
        return True, f"거래대금 x{accel:.2f}, 강도 {base_s:.0f}->{cur_s:.0f}"

    def _rescue_gate(self, stock_code: str, pos: dict, current_price: float,
                     origin: float) -> str:
        """-3% 손절선에서의 판정. 'added' | 'observing' | 'sell' 중 하나.

        'observing'이면 호출부는 **이번 틱에 매도하지 않는다**. 관찰 중에도
        원가 대비 RESCUE_ADD_OBSERVE_FLOOR를 이탈하면 즉시 'sell'이 된다 —
        보류에 상한을 두지 않으면 손절이 무력화되기 때문이다.
        """
        if not RESCUE_ADD_ENABLED or pos.get("rescue_added"):
            return "sell"
        now = _time_mod.time()
        watch_until = pos.get("rescue_watch_until")

        # ── 관찰 시작 판정 (첫 -3% 도달) ──────────────────────────
        if watch_until is None:
            if self._rescue_count_today >= RESCUE_ADD_MAX_PER_DAY:
                self._note_reject(stock_code, "추가매수 일일 한도 초과")
                return "sell"
            try:
                blocked = self._entry_block_reason()
                if blocked:
                    logger.info("[%s] 추가매수 관찰 미시작 — %s", stock_code, blocked)
                    return "sell"
                ok, why = self._rescue_precheck(stock_code, pos)
            except Exception:
                logger.exception("[%s] 추가매수 사전판정 실패 -> 손절", stock_code)
                return "sell"
            if not ok:
                logger.info("[%s] 추가매수 미발동 — %s", stock_code, why)
                return "sell"
            pos["rescue_watch_until"] = now + RESCUE_ADD_OBSERVE_SEC
            pos["rescue_low"] = current_price
            logger.warning(
                "[%s] %s 👀 손절 보류 %.0f초 관찰 시작 — %s | 현재 %s원 "
                "(관찰 중 %s원 이탈 시 즉시 손절)",
                stock_code, pos.get("stock_name", stock_code),
                RESCUE_ADD_OBSERVE_SEC, why, f"{current_price:,.0f}",
                f"{origin * (1 - RESCUE_ADD_OBSERVE_FLOOR):,.0f}",
            )
            return "observing"

        # ── 관찰 중 ────────────────────────────────────────────
        low = min(float(pos.get("rescue_low") or current_price), current_price)
        pos["rescue_low"] = low
        if origin > 0 and current_price <= origin * (1.0 - RESCUE_ADD_OBSERVE_FLOOR):
            logger.info("[%s] 관찰 중 하한 이탈 -> 손절", stock_code)
            return "sell"
        if now >= watch_until:
            logger.info("[%s] 관찰 창 만료(반등 없음) -> 손절", stock_code)
            return "sell"
        if low <= 0:
            return "sell"
        rebound = (current_price - low) / low
        if rebound < RESCUE_ADD_REBOUND_PCT:
            return "observing"

        # ③ 반등 확증 성립 — ①②를 다시 확인하고 집행한다
        try:
            ok, why = self._rescue_precheck(stock_code, pos)
        except Exception:
            logger.exception("[%s] 추가매수 재판정 실패 -> 손절", stock_code)
            return "sell"
        if not ok:
            logger.info("[%s] 반등했으나 %s -> 손절", stock_code, why)
            return "sell"
        why = f"{why}, 저점 {low:,.0f} 대비 +{rebound*100:.2f}%"
        return "added" if self._do_rescue_add(stock_code, pos, current_price,
                                              origin, why) else "sell"

    def _do_rescue_add(self, stock_code: str, pos: dict, current_price: float,
                       origin: float, why: str) -> bool:
        """조건이 전부 성립한 뒤의 **집행 전용**. 성공하면 True.

        판정은 _rescue_gate가 끝냈다. 여기서 실패하면(주문 거부/미체결) 호출부는
        손절로 되돌아간다 — 어떤 경우에도 '못 팔고 못 사는' 상태가 되면 안 된다.
        """
        before_qty = int(pos.get("qty", pos.get("buy_quantity")) or 0)
        info = {"current_price": current_price,
                "entry_note": f"손절 대신 추가매수 ({why})"}
        logger.warning(
            "[%s] %s 🛟 손절 대신 추가매수 — %s | 원가 %s원 / 현재 %s원 "
            "(최종손절 %s원)",
            stock_code, pos.get("stock_name", stock_code), why,
            f"{origin:,.0f}", f"{current_price:,.0f}",
            f"{origin * (1 - RESCUE_ADD_FINAL_STOP):,.0f}",
        )
        try:
            self._execute_buy(
                stock_code, pos.get("stock_name", stock_code),
                pos.get("strategy_phase", "1A"), info,
                sub_strategy=pos.get("sub_strategy", "1A"),
                size_frac=1.0, add_to_position=True,
            )
        except Exception:
            logger.exception("[%s] 추가매수 주문 실패 -> 손절로 진행", stock_code)
            return False

        after_qty = int(pos.get("qty", pos.get("buy_quantity")) or 0)
        if after_qty <= before_qty:
            logger.warning("[%s] 추가매수 미체결(수량 불변) -> 손절로 진행", stock_code)
            return False

        pos["rescue_added"] = True
        self._rescue_count_today += 1
        _notify(
            f"🛟 손절 대신 추가매수\n"
            f"{pos.get('stock_name', stock_code)} ({stock_code})\n"
            f"{why}\n"
            f"평단 {pos.get('buy_price', 0):,.0f}원 / {after_qty}주\n"
            f"최종손절 {origin * (1 - RESCUE_ADD_FINAL_STOP):,.0f}원 "
            f"(원가 -{RESCUE_ADD_FINAL_STOP*100:.0f}%)\n"
            f"오늘 {self._rescue_count_today}/{RESCUE_ADD_MAX_PER_DAY}회"
        )
        return True

    def _strength_baseline(self, pos: dict) -> float:
        """청산 판정에 쓸 체결강도 '기준선' (2026-08-03 신규).

        ⚠️ `entry_strength`를 그대로 쓰면 안 된다. 진입은 대량체결 버스트가
        터지는 바로 그 순간에 일어나므로, 그때 캡처한 compute_strength(최근
        10초 창)에는 그 버스트가 통째로 들어있어 **거의 항상 국소 최고점**이다.
        08-03 실거래에서 042700/090710/010170 세 포지션의 entry_strength가
        정확히 300(compute_strength 상한)으로 포화돼 있었다. 포화된 최고점을
        기준선으로 삼고 `현재 < 기준 x 0.8`로 비교하면 **정상 수준으로만
        돌아와도 '하락'으로 판정**된다 — 하락이 구조적으로 필연이 된다.
        (08-02에 고친 avg_trade_value의 자기모순과 정확히 같은 종류의 실수다:
         그때도 '지금 터지는 버스트'가 분모에 섞여 문턱이 같이 올라갔다.)

        그래서 워밍업이 끝난 뒤 처음 관측되는 '안정화된' 강도를 기준선으로
        다시 잡는다(re-anchor). 리앵커에 실패하면(계속 중립값/데이터 없음)
        기준선이 없는 것으로 보고 호출부가 판단을 보류한다 — 옛 스파이크
        값으로 폴백하지 않는다. 그렇게 하면 이 수정이 무의미해지기 때문이다.
        """
        return float(pos.get("strength_baseline") or 0.0)

    def _maybe_anchor_strength_baseline(self, pos: dict, stock_code: str):
        """워밍업 종료 후 첫 유효 강도를 기준선으로 고정 (2026-08-03).
        중립값(100.0=틱 부족)은 '측정 실패'이므로 기준선으로 삼지 않는다."""
        if pos.get("strength_baseline"):
            return
        warmup_until = pos.get("warmup_until")
        if warmup_until and self._now() < warmup_until:
            return
        try:
            s = self._current_strength(stock_code)
        except Exception:
            return
        if s and s > 0 and s != STRENGTH_NEUTRAL:
            pos["strength_baseline"] = float(s)
            logger.info(
                "[%s] %s 체결강도 기준선 %.0f 고정 (진입 스파이크 %.0f 대체)",
                stock_code, pos.get("stock_name", ""), s,
                pos.get("entry_strength") or 0,
            )

    def _is_strength_rising_vs_entry(self, pos: dict, stock_code: str):
        """기준선 대비 체결강도가 유의하게 상승했는지 3값 판정 (2026-07-31).
        True=상승(캡 상향) / False=미상승 / None=판단불가.
        None을 따로 두는 이유: 강도 데이터가 없을 때 '미상승'으로 몰면 멀쩡한
        포지션을 +1.0%에서 전부 잘라버리게 되므로, 그때는 기본 캡을 유지한다.
        (2026-08-03) 비교 기준을 entry_strength -> strength_baseline으로 교체.
        사유는 _strength_baseline docstring 참고."""
        self._maybe_anchor_strength_baseline(pos, stock_code)
        entry_s = self._strength_baseline(pos)
        if entry_s <= 0:
            return None
        if not (self.phase1b and getattr(self.phase1b, "trade_flow", None)):
            return None
        try:
            cur_s = self._current_strength(stock_code)
        except Exception:
            return None
        # 중립값(100.0)은 '틱 부족으로 판단 불가'를 뜻하므로 상승으로 오해하지 않음
        # (trade_flow.compute_strength가 최소틱수 미달 시 STRENGTH_NEUTRAL 반환)
        if cur_s <= 0 or cur_s == STRENGTH_NEUTRAL:
            return None
        return cur_s >= entry_s * TP_UPGRADE_STRENGTH_RATIO

    def _update_dynamic_caps(self):
        """**동적 상향된** 포지션의 조기 이탈 판정 (2026-07-30, tick() 주기 실행).

        체결강도 하락 AND 거래량 하락이 동시에 오면 캡을 기다리지 않고 즉시 매도.
        (사용자 스펙이 AND — OR로 하면 과민해서 백테스트상 오히려 손해였음:
         건당 -0.328% -> -0.532%)

        캡 '상향'은 여기가 아니라 on_price_update에서 처리한다(2026-07-31) —
        순 +1.0% 도달이라는 가격 트리거가 필요해서 틱 경로에 있어야 하고,
        여기에 두면 가격과 무관하게 강도만으로 올라가 백테스트 설계와 달라진다.

        비용 설계: 강도는 메모리(trade_flow)라 매번 계산해도 무료이지만 거래량은
        REST가 필요하다. 그래서 '강도 하락'이 먼저 확인된 종목만,
        종목당 TP_VOL_CHECK_SEC 간격으로 거래량을 조회한다."""
        if not self.holdings:
            return
        now_dt = self._now()
        for code in list(self.holdings.keys()):
            pos = self.holdings.get(code)
            if not pos or code in self.pending or code in self.sell_blocked:
                continue
            warmup_until = pos.get("warmup_until")
            if warmup_until and now_dt < warmup_until:
                continue  # 매수 직후 워밍업 중엔 판단 보류(기존 관례와 동일)

            # (2026-08-03) 비교 기준을 '진입 순간 스파이크'가 아니라 워밍업
            # 종료 후 안정화된 기준선으로 교체 — 사유는 _strength_baseline 참고.
            self._maybe_anchor_strength_baseline(pos, code)
            entry_s = self._strength_baseline(pos)
            if entry_s <= 0:
                continue  # 기준선 미확보 -> 비교 불가(보수적으로 유지)
            try:
                cur_s = self._current_strength(code)
            except Exception:
                continue

            # 중립값(틱 부족으로 판단 불가)을 "하락"으로 오판하지 않는다 (2026-07-31
            # 실거래로 발견 — 매수 66/69초 만에 강도 166->100/253->100으로
            # "동적캡 즉시매도"가 발동했는데, 가격은 거의 안 움직였고(0.00%/-0.17%)
            # 실제로는 최근 10초 틱이 부족해 compute_strength가 중립값(100)을
            # 반환한 것뿐이었다. on_price_update의 _is_strength_rising_vs_entry는
            # 이미 같은 이유로 중립값을 별도 처리하는데(07-31 도입), 여기 하락
            # 판정에는 그 방어가 빠져있었다 — 진입강도가 100 초과인 대부분의
            # 포지션에서 데이터 부족을 곧바로 "하락"으로 오인하게 되는 구조였다.
            if cur_s <= 0 or cur_s == STRENGTH_NEUTRAL:
                continue  # 판단 불가 -> 보수적으로 유지(하락 확정 아님)

            # 체결강도 하락은 두 경로(익절캡 조기이탈 / 손실반등 매도) 공통 전제.
            # 유지 중이면 어느 쪽도 해당 없으므로 거래량 조회(REST) 전에 끊는다.
            if cur_s >= entry_s * TP_DECLINE_STRENGTH_RATIO:
                continue

            price = self.phase1b.trade_flow.get_latest_price(code) if self.phase1b else None
            if not price:
                try:
                    c1 = self.api.get_minute_candles(code, interval=1, count=1)
                    price = float(c1[0]["close"]) if c1 else None
                except Exception:
                    price = None
            if not price:
                continue

            # 경로 A: **실제로 상향된** 포지션의 조기 이탈.
            #
            # (2026-08-03 수정 — 오늘 실거래로 드러난 결함)
            # 기존 조건은 `cap >= TP_CAP_UPGRADED`였는데, 1A 기본캡(0.025)이
            # TP_CAP_UPGRADED(0.025)와 **같은 값**이라 모든 1A 포지션에서 항상
            # True였다. 그 결과 1A는 매수 직후(워밍업 60초가 끝나는 순간)부터
            # 이 즉시매도 판정의 대상이 됐고, 08-03에 6건이 75~250초 만에
            # 잘려나갔다(평균 +0.35%, 수수료 0.23% 빼면 사실상 본전).
            # 이 로직의 원래 의도는 주석 그대로 "상향된 종목"이므로,
            # on_price_update가 실제로 캡을 올린 포지션만 대상으로 한정한다.
            cap_exit = bool(pos.get("tp_cap_upgraded"))
            # 경로 B(신규): 손실 종목이 저점에서 반등했으나 그 반등이 강도로
            # 뒷받침되지 않는 경우 — 손실 최소화 청산.
            loss_rebound = self._is_loss_rebound_exit(pos, price, now_dt)
            if not cap_exit and not loss_rebound:
                continue

            # (2026-08-03) 경로 A는 '익절' 로직이므로 이익 구간에서만 발동한다.
            # 기존엔 손익과 무관하게 발동해 08-03에 -0.99% / -0.48% / -0.43%를
            # "동적캡 즉시매도"라는 이름으로 실현시켰다. 손실 구간의 청산은
            # 손절(-3%)과 경로 B(손실반등)가 담당해야 할 몫이다.
            if cap_exit and not loss_rebound:
                if self._net_rate(pos["buy_price"], price) <= 0:
                    continue

            last = self._tp_vol_checked_at.get(code)
            if last is not None and (now_dt - last).total_seconds() < TP_VOL_CHECK_SEC:
                continue
            self._tp_vol_checked_at[code] = now_dt
            try:
                candles = self._get_merged_candles(code, interval=1, count=30)
                vol_ratio = self._volume_ratio(candles) if candles else None
            except Exception as e:
                logger.warning("[%s] 동적캡 거래량 조회 실패: %s", code, e)
                continue
            if vol_ratio is None or vol_ratio >= TP_DECLINE_VOLUME_RATIO:
                continue  # 거래량은 아직 살아있음 -> 계속 보유

            net_rate = self._net_rate(pos["buy_price"], price) * 100
            if loss_rebound and not cap_exit:
                low = pos.get("lowest_price") or pos["buy_price"]
                bounce = (price - low) / low * 100 if low else 0.0
                reason = (
                    f"손실반등 하이브리드 매도 (저점 대비 +{bounce:.2f}% 반등 후 "
                    f"체결강도 {entry_s:.0f}->{cur_s:.0f}, 거래량 x{vol_ratio:.2f}, "
                    f"순 {net_rate:+.2f}% — 손절 대기 대신 손실 축소)"
                )
                # 손실반등은 **전량** 청산 유지 (2026-08-04).
                # 분할은 '익절을 놓치지 않기' 위한 장치인데, 이 경로는 애초에
                # 손실을 -3% 손절 전에 줄이려는 리스크 장치다. 절반을 남기면
                # 그 방어가 절반으로 약해진다 — 성격이 반대라 적용하지 않는다.
                self._execute_sell(code, price, reason)
                continue

            # ── 동적캡(익절) 경로: 분할매도 (2026-08-04 사용자 지정) ──
            # 신호는 +1분 예측력만 검증됐다(6건 전부 음수, 평균 -0.91%).
            # 3~5분 뒤엔 부호가 갈리므로(037070 +6.5%) 전량청산은 과잉대응이다.
            # 절반은 지금 좋은 가격에 빼고, 절반은 트레일에 맡겨 추세를 남긴다.
            reason = (
                f"동적캡 즉시매도 (체결강도 {entry_s:.0f}->{cur_s:.0f}, "
                f"거래량 x{vol_ratio:.2f}, 순 {net_rate:+.2f}%)"
            )
            remaining = int(pos.get("qty", pos.get("buy_quantity")) or 0)
            if (
                PARTIAL_EXIT_ENABLED
                and not pos.get("partial_exited")
                and remaining >= 2          # 1주는 쪼갤 수 없다
            ):
                half = max(1, int(remaining * PARTIAL_EXIT_FRACTION))
                if half < remaining:        # 반올림으로 전량이 되면 의미가 없다
                    self._execute_sell(
                        code, price,
                        reason + f" — 분할 1차 {int(PARTIAL_EXIT_FRACTION*100)}%"
                        f" (잔량은 고점대비 {PARTIAL_EXIT_TRAIL*100:.1f}% 트레일)",
                        sell_qty=half,
                    )
                    # 잔량 트레일 기준 고점을 지금 시점으로 고정한다.
                    p = self.holdings.get(code)
                    if p is not None:
                        p["trail_peak"] = max(
                            float(p.get("highest_price") or price), float(price)
                        )
                    continue
            self._execute_sell(code, price, reason)

    def _is_loss_rebound_exit(self, pos: dict, price: float, now_dt) -> bool:
        """손실 반등 하이브리드 매도 대상인지 (2026-07-31 사용자 지정).

        조건: ① 현재 순손익이 손실 ② 매수 후 최소 보유시간 경과
              ③ 당일 저점 대비 LOSS_REBOUND_MIN(+1%) 이상 반등한 상태.
        여기서 True가 나와도 호출부에서 체결강도 하락 AND 거래량 하락을 함께
        확인해야 실제 매도된다 — 즉 "반등했지만 그 반등에 힘이 없다"는
        3중 확인 구조. 손절(-3%)은 그대로 남아 최후 방어선 역할을 한다."""
        buy_price = pos.get("buy_price")
        if not buy_price or not price:
            return False
        if self._net_rate(buy_price, price) >= 0:
            return False  # 손실 구간에서만 작동(이익 구간은 익절캡 담당)

        buy_time = pos.get("buy_time")
        if buy_time is None:
            return False
        if (now_dt - buy_time) < timedelta(minutes=LOSS_REBOUND_MIN_HOLD_MIN):
            return False  # 매수 직후 노이즈로 잘리는 것 방지

        low = pos.get("lowest_price")
        if not low or low <= 0:
            return False  # 저점 기록 없음(틱 미수신) -> 판단 보류
        return (price - low) / low >= LOSS_REBOUND_MIN

    @staticmethod
    def _is_early_buy(pos: dict) -> bool:
        """개장초반(09:00~09:10) 매수분인지. 1L 트레일링 예외 판정에도 쓴다(1L은
        현재 주석처리 상태라 사실상 1A/Pullback/1B의 익절캡 판정에만 쓰임)."""
        buy_time = pos.get("buy_time")
        if buy_time is None:
            return False
        try:
            return GROUP_A_START <= buy_time.time() < EARLY_WINDOW_END
        except AttributeError:
            return False

    @classmethod
    def _take_profit_cap(cls, pos: dict) -> tuple[float, str]:
        """포지션별 익절 캡과 표시용 라벨 (2026-07-30).
        기본 캡은 매수 시점 기준으로 고정하되, 동적캡 로직이 올려둔
        pos["tp_cap"]이 있으면 그 값이 우선한다.
        (2026-08-02) 1L/1B 분기는 두 전략 삭제와 함께 제거 — 이제 이 함수가
        모든 포지션의 익절 캡을 결정한다(트레일링 예외 없음)."""
        override = pos.get("tp_cap")
        if override is not None:
            return float(override), pos.get("tp_cap_label", "동적")

        if cls._is_early_buy(pos):
            return TAKE_PROFIT_CAP_EARLY, "개장초반"

        sub = pos.get("sub_strategy")
        if sub == "1A_눌림":
            return TAKE_PROFIT_CAP_PULLBACK, "눌림"
        return TAKE_PROFIT_CAP, "기본"

    def _execute_sell(self, stock_code, current_price, exit_reason, sell_qty=None):
        """포지션 청산. sell_qty를 주면 **부분매도**(2026-08-04 신규).

        부분매도 설계 — DB 정합성이 핵심이다:
          trades 행 하나가 곧 '한 번의 왕복'이다. 부분매도마다 update_sell을
          부르면 status가 'closed'로 바뀌고 남은 수량이 어느 행에도 안 남는다.
          그래서 **중간 매도는 메모리에만 누적**하고(pos["_realized_*"]),
          포지션이 완전히 닫히는 순간 한 번만 update_sell을 부른다 —
          이때 수량은 원래 전량, 가격은 **수량가중 평균 매도가**를 넘긴다.
          결과적으로 행 하나에 그 포지션의 총 손익이 정확히 남고,
          update_sell의 matched_buy_amount 계산(2026-07-30 수정분)과도 어긋나지 않는다.
          CLAUDE.md 이월과제 18번(부분매도 시 buy_quantity 미반영)도 이 방식이면
          애초에 발생하지 않는다 — buy_quantity를 건드리지 않기 때문이다.
        """
        pos = self.holdings.get(stock_code)
        if not pos or stock_code in self.pending:
            return
        if stock_code in self.sell_blocked:
            return

        remaining = int(pos.get("qty", pos.get("buy_quantity")) or 0)
        if remaining <= 0:
            return
        if sell_qty is None:
            quantity = remaining
        else:
            quantity = max(0, min(int(sell_qty), remaining))
            if quantity <= 0:
                return
        is_partial = quantity < remaining

        logger.info(
            "청산 트리거 [%s] %s | 사유: %s | 현재가 %s%s",
            stock_code,
            pos.get("stock_name", ""),
            exit_reason,
            f"{current_price:,}",
            f" | 부분매도 {quantity}/{remaining}주" if is_partial else "",
        )

        self.pending.add(stock_code)
        try:
            # 매도는 시장가 (2026-08-01) — 지정가 미체결 시 포지션이 봇의 관리
            # 대상에서 영구 이탈하는 구멍이 있었다(order_manager.sell 주석 참고).
            # 시장가가 거부되면 검증된 지정가로 1회 폴백해서, 새 주문 방식 때문에
            # 청산 자체를 놓치는 일이 없게 한다 — 매수 경로와 같은 안전망.
            result = self.order_manager.sell(stock_code, quantity, order_style="market")
            if not result or not result.get("success"):
                logger.warning(
                    "[%s] 시장가 매도 실패(%s) -> 지정가로 1회 폴백",
                    stock_code, (result or {}).get("error", "unknown"),
                )
                result = self.order_manager.sell(
                    stock_code, quantity, price=0, order_style="limit"
                )

            if not result or not result.get("success"):
                err = (result or {}).get("error", "unknown")
                cnt = self.sell_fail_count.get(stock_code, 0) + 1
                self.sell_fail_count[stock_code] = cnt

                logger.error(
                    "[%s] 매도 실패 (%d/%d): %s", stock_code, cnt, MAX_SELL_FAIL, err
                )
                SystemEventRepository.log(
                    "ORDER_FAIL",
                    f"SELL {stock_code}: {err} ({cnt}/{MAX_SELL_FAIL})",
                    "ERROR",
                )

                if cnt >= MAX_SELL_FAIL:
                    self.sell_blocked.add(stock_code)
                    stock_name = pos.get("stock_name", stock_code)
                    self.holdings.pop(stock_code, None)
                    logger.warning(
                        "[%s] %s 매도 %d회 실패 -> 차단", stock_code, stock_name, cnt
                    )
                    SystemEventRepository.log(
                        "SELL_BLOCKED",
                        f"{stock_code} 매도 {cnt}회 실패 -> 차단",
                        "WARNING",
                    )
                    _notify(
                        f"매도 차단\n{stock_name} ({stock_code})\n"
                        f"매도 {cnt}회 실패 -> 수동 확인 필요"
                    )
                else:
                    _notify(
                        f"매도 실패 ({cnt}/{MAX_SELL_FAIL})\n"
                        f"{pos.get('stock_name', stock_code)} ({stock_code})\n사유: {err}"
                    )
                return

            self.sell_fail_count.pop(stock_code, None)
            self.sold_at[stock_code] = self._now()

            # 부분매도 누적 (2026-08-04) — DB에는 아직 쓰지 않는다.
            pos["_realized_qty"] = int(pos.get("_realized_qty", 0)) + quantity
            pos["_realized_amount"] = (
                float(pos.get("_realized_amount", 0.0)) + current_price * quantity
            )

            if is_partial:
                # 포지션을 유지한 채 수량만 줄인다. DB 갱신은 완전 청산 시 1회.
                pos["qty"] = remaining - quantity
                pos["partial_exited"] = True
                net_profit_part = self._net_profit(
                    pos["buy_price"], current_price, quantity
                )
                self._daily_realized += net_profit_part
                net_rate_part = self._net_rate(pos["buy_price"], current_price) * 100
                logger.info(
                    "SELL(부분) [%s] %s %d주 @ %s원 -> %s | 순손익 %s원 (순 %.2f%%) "
                    "| 잔량 %d주",
                    stock_code, pos.get("stock_name", ""), quantity,
                    f"{current_price:,}", exit_reason,
                    f"{net_profit_part:+,.0f}", net_rate_part, pos["qty"],
                )
                SystemEventRepository.log(
                    "SELL_PARTIAL",
                    f"{stock_code} {quantity}주 @ {current_price:,}원 | {exit_reason} "
                    f"| 잔량 {pos['qty']}주",
                    "INFO",
                )
                _notify(
                    f"부분 매도 [{pos.get('sub_strategy', '?')}]\n"
                    f"종목: {pos.get('stock_name', '')} ({stock_code})\n"
                    f"수량: {quantity}주 @ {current_price:,}원 (잔량 {pos['qty']}주)\n"
                    f"순손익: {net_profit_part:+,.0f}원 (순 {net_rate_part:+.2f}%)\n"
                    f"사유: {exit_reason}",
                    target="order",
                )
                return

            # ── 여기부터는 완전 청산 ──
            # DB에는 이 포지션의 **전체 왕복**을 한 행으로 남긴다.
            # 부분매도가 있었으면 수량가중 평균 매도가로 환산해야 손익이 맞다.
            total_qty = int(pos["_realized_qty"])
            avg_sell_price = pos["_realized_amount"] / total_qty if total_qty else current_price

            # 매도 주문은 이미 체결됨 — DB 기록이 실패(또는 trade_id 없음)해도
            # 아래 포지션 정리(self.holdings 제거)는 반드시 이어져야 한다.
            if pos.get("trade_id") is not None:
                try:
                    TradeRepository.update_sell(
                        trade_id=pos["trade_id"],
                        sell_price=avg_sell_price,
                        sell_quantity=total_qty,
                        exit_reason=exit_reason,
                    )
                except Exception as e:
                    logger.exception(
                        "[%s] 매도 DB 기록 실패 (청산은 정상 처리): %s", stock_code, e
                    )
                    SystemEventRepository.log(
                        "DB_LOG_FAIL", f"update_sell {stock_code}: {e}", "ERROR"
                    )
            else:
                logger.warning(
                    "[%s] trade_id 없음(매수 DB 기록 실패 이력) — 매도 DB 갱신 스킵",
                    stock_code,
                )

            # 순손익 (수수료/세금 차감).
            # 이번에 판 수량만 MDD에 더한다 — 앞선 부분매도분은 그때 이미 더했다.
            net_profit_last = self._net_profit(
                pos["buy_price"], current_price, quantity
            )
            self._daily_realized += net_profit_last  # MDD 누적(이번 체결분만)
            # 표시/성과기록은 **포지션 전체**(부분매도 포함) 기준이어야
            # 사후 분석과 전략성과 축소추정이 왜곡되지 않는다.
            net_profit = self._net_profit(
                pos["buy_price"], avg_sell_price, total_qty
            )
            gross_rate = self._gross_rate(pos["buy_price"], avg_sell_price) * 100
            net_rate = self._net_rate(pos["buy_price"], avg_sell_price) * 100
            stock_name = pos["stock_name"]
            sub = pos.get("sub_strategy", "?")
            was_partial = bool(pos.get("partial_exited"))
            del self.holdings[stock_code]
            # 틱 진입 상태 초기화 (2026-08-02) — 이걸 빼먹으면 매수 전에 켜둔
            # 강도 타이머가 그대로 남아, 재매수 가능해진 순간 "연속 유지"가
            # 이미 충족된 것으로 계산돼 무장 단계를 통째로 건너뛴다.
            self.reset_tick_entry_state(stock_code)

            # 장중 전략 성과에 반영 (2026-07-31) — 이후 이 전략의 점수 컷라인이
            # 자동 조정된다. net_rate는 위에서 %로 환산돼 있으므로 소수로 되돌림.
            try:
                self.perf.record(sub, net_rate / 100.0)
                self.perf.log_tier_change(sub)
                # [제안 B] 조건검색식 축에도 같은 성과를 기록 (2026-08-01).
                # 전략 축과 독립된 키라 서로 간섭하지 않는다.
                cond_key = pos.get("cond_key")
                if cond_key:
                    self.perf.record(cond_key, net_rate / 100.0)
                    self.perf.log_tier_change(cond_key)
            except Exception as e:
                logger.warning("[%s] 전략성과 기록 실패: %s", stock_code, e)

            # 실제 손실로 마감된 청산은 사유(손절/슬롯교체/시간정리) 무관하게 당일
            # 재매수 금지. 익절만 기존 3분 쿨다운 후 재진입 허용. (2026-07-29 수정 —
            # 기존엔 "손절"로 시작하는 사유만 차단해서, 슬롯교체로 손실 나간 종목이
            # 3분 쿨다운만 지나면 바로 재매수돼 같은 종목에서 반복 손실이 났음.
            # 예: 스피어(347700) 09:38→09:50 슬롯교체(-59,899)→09:53 재매수→10:04
            # 또 슬롯교체(-9,172)→10:07 재매수→10:17 결국 손절(-130,219), 합계
            # -199,290원. 이제 09:50 시점에 바로 차단되어 반복이 끊긴다.)
            if net_profit < 0:
                self._stoploss_blocked.add(stock_code)
                logger.info(
                    "[%s] 손실 청산(%s, 순%.2f%%) → 당일 재매수 차단",
                    stock_code, exit_reason, net_rate,
                )

            logger.info(
                "SELL [%s] %s %d주 @ %s원 -> %s | 순손익 %s원 (순 %.2f%%, 가격 %.2f%%) [%s]",
                stock_code,
                stock_name,
                quantity,
                f"{current_price:,}",
                exit_reason,
                f"{net_profit:+,.0f}",
                net_rate,
                gross_rate,
                sub,
            )
            SystemEventRepository.log(
                "SELL",
                f"{stock_code} {stock_name} {quantity}주 @ {current_price:,}원 [{sub}] | "
                f"{exit_reason} | 순손익 {net_profit:+,.0f}원",
                "INFO",
            )
            emoji = "+" if net_profit > 0 else "-"
            _notify(
                f"매도 체결 [{sub}] ({emoji})\n종목: {stock_name} ({stock_code})\n"
                f"수량: {quantity}주 @ {current_price:,}원"
                + (
                    f"\n(분할매도 합산 {total_qty}주, 평균 매도가 {avg_sell_price:,.0f}원)"
                    if was_partial else ""
                )
                + f"\n순손익: {net_profit:+,.0f}원 (순 {net_rate:+.2f}%, 가격 {gross_rate:+.2f}%)\n"
                f"사유: {exit_reason}\n재매수 차단: {int(REBUY_COOLDOWN.total_seconds()/60)}분"
            )
        finally:
            self.pending.discard(stock_code)

    # ========================================
    # 타임아웃
    # ========================================
    def check_timeouts(self):
        """보유 30분 초과분 정리 — **on_price_update와 별개의 두 번째 경로**다.

        ⚠️ (2026-08-03) on_price_update의 시간정리에 '슬롯 만석' 조건을 걸면서
        여기도 **똑같이** 걸어야 한다. 안 그러면 틱이 안 들어오는 종목이 이
        경로로 30분에 잘려나가, 조건을 건 의미가 사라진다(같은 규칙이 두 곳에
        있다는 걸 놓치면 한쪽만 고쳐 조용히 어긋나는 전형적인 사고다).
        지수 가드 발동 중 제외도 같은 이유로 동일하게 적용한다.
        """
        now = self._now()
        # 슬롯이 남으면 자리를 비울 이유가 없고, 가드 중이면 비워도 쓸 곳이 없다.
        if self.occupied_slots() < MAX_HOLDINGS or self._is_index_guard_active():
            return
        for code in list(self.holdings.keys()):
            pos = self.holdings[code]
            warmup_until = pos.get("warmup_until")
            if warmup_until and now < warmup_until:
                continue
            if now - pos["buy_time"] < HOLDING_TIMEOUT:
                continue
            if code in self.sell_blocked:
                continue
            try:
                # 병합 메서드 사용
                candles = self._get_merged_candles(code, interval=1, count=1)
                if candles:
                    self._execute_sell(code, candles[0]["close"], "시간정리 30분 (슬롯 만석)")
            except Exception as e:
                logger.exception("[%s] 타임아웃 청산 실패: %s", code, e)
